insert into public.transaction_municipal_requirements
  (municipality_code, municipality_name, county, requirement_key, requirement_state, title, requirements, fees, application_url, department_url, source_urls, source_excerpt, source_hash, last_verified_at, metadata, curated_note, curated_override)
values
  ($t$0301$t$, $t$Bass River Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale / Rental Inspection (Rental/Resale Application)$t$, $j$["Issued by: Tuckerton Borough Construction and Code Enforcement Office, serving Bass River under an interlocal service agreement","Contact: Joseph Ventresca, Housing Official / Code Enforcement Officer (Tuckerton Borough) · 609-296-4916 · LCranmer@TuckertonBorough.com","How to apply: Download the Resale - Rental Application from the Bass River Forms page, check Resale Inspection, and submit it with payment (cash, check or money order) to the Tuckerton Borough Construction Office, 420 East Main Street, Tuckerton, NJ 08087. Inspections are done on Fridays only. Attach any required certifications (well water, chimney, woodstove, fireplace, heat and hot water, elevation, lead paint).","Yard free of debris and weeds, sheds empty; waterfront lots need bulkhead in good condition","Home clean and move-in ready, trash and hazardous material removed; paint, flooring, siding, roof, windows and screens in good condition","Attached garage walls and attic ceilings finished with 1/2 inch drywall (two layers of Type X under living space); rated doors","Stairs with graspable handrails and closed risers; decks and landings 30 inches or more above grade need 36 inch guardrails with openings under 4 inches","Smoke alarms to code (see fire certificate) and carbon monoxide alarm within 10 feet of all bedrooms","Anti-tip device on the range","Electrical: no exposed wires, panel labeled, all boxes covered","Water heater relief valve piped to within 6 inches of the floor; heating equipment properly vented","House numbers at least 4 inches near the front door (not on the door), contrasting","Well water test by the Board of Health if on well water","Flood elevation certificate in special flood hazard areas","Chimney caps on all fireplaces","Certificates by professionals for chimneys, woodstoves, fireplaces, heat and hot water systems, elevation, bulkhead, and lead paint for homes built before 1978","Portable fire extinguisher, minimum 2A:10BC, 2.5 to 10 lb dry chemical, within 10 feet of the kitchen (still listed on the May 2026 form)","Also: Well water test: The form says a well water test must be completed by the Board of Health for homes on well water.","Also: Professional certifications: Attach certifications for well and septic, chimneys, woodstoves, fireplaces, heat and hot water systems, elevation, and lead paint if the home was built before 1978.","Also: Rental certificate of occupancy (rentals only): Rental units need a township certificate of occupancy before each new occupancy, applied for through the municipal clerk (Chapter 5.16). Not a resale requirement."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://bassriver-nj.org/site_files/Forms/Property_Resale_Rental_Application.pdf$t$, $t$https://bassriver-nj.org/offices/$t$, $j$[{"url":"https://bassriver-nj.org/offices/","label":"Official source (bassriver-nj.org)"},{"url":"https://bassriver-nj.org/forms/","label":"Official source (bassriver-nj.org)"},{"url":"https://bassriver-nj.org/site_files/Forms/Property_Resale_Rental_Application.pdf","label":"Official source (bassriver-nj.org)"},{"url":"https://tuckertonborough.com/government/departments/construction-and-code-enforcement/","label":"Official source (tuckertonborough.com)"}]$j$::jsonb, $t$The Township of Bass River has an Interlocal Service Agreement with Tuckerton Borough for building, electrical, and plumbing services. All three services are coordinated through the Tuckerton Borough Construction Office located in the Administrative Building, 420 East Main Street Tuckerton, New Jersey 08087.$t$, $t$57b479106e4d3276a434c47a18a7267569ed978825469505fc1102a93d4556dc$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":15,"q_ok":9,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0301.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0301.json$t$, true),
  ($t$0301$t$, $t$Bass River Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Tuckerton Borough Fire Prevention / Construction and Code Enforcement Office (for Bass River under interlocal agreement) (town fire bureau)","Contact: Joseph Ventresca, Housing Official / Code Enforcement Officer (Tuckerton Borough) · 609-296-4916 · LCranmer@TuckertonBorough.com","Apply: Fee depends on how soon the inspection is needed: more than 10 business days, 4 to 10 business days, or 1 to 4 business days after the application is received.","How to apply: Use the Resale - Rental Application on Bass River's Forms page. Submit it with the non-refundable fee (cash, check or money order only) to the Tuckerton Borough Construction Office, 420 East Main Street, Tuckerton, NJ 08087. Inspections are done on Fridays only.","Fire official in the NJ state directory (NJ DCA, state), updated 5/18/2026: Louis Kilmer · (609)633-6132","Ten-year sealed battery smoke alarms required where alarms are battery powered (effective January 1, 2019); hardwired alarms from original construction must stay hardwired","Smoke alarm rules by year built (1978 and before, 1979-1981, 1981-1987, 1987-1991, 1991 to present), with hardwired and interconnected alarms required for newer homes","Carbon monoxide alarm within 10 feet of the sleeping areas","Portable fire extinguisher, minimum 2A:10BC, 2.5 to 10 lb dry chemical, within 10 feet of the kitchen (form dated May 2026 still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO/extinguisher certificate, inspection more than 10 business days after application","amount":"$75.00"},{"label":"Smoke/CO/extinguisher certificate, inspection 4 to 10 business days after application","amount":"$150.00"},{"label":"Smoke/CO/extinguisher certificate, inspection 1 to 4 business days after application","amount":"$225.00"}]$j$::jsonb, $t$https://bassriver-nj.org/site_files/Forms/Property_Resale_Rental_Application.pdf$t$, $t$https://tuckertonborough.com/government/departments/construction-and-code-enforcement/$t$, $j$[{"url":"https://bassriver-nj.org/site_files/Forms/Property_Resale_Rental_Application.pdf","label":"Official source (bassriver-nj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Certification of smoke detector, carbon monoxide alarm and portable fire extinguisher compliance.$t$, $t$e954fe33cc052a2a52de2f95692d8807d7f49001f805e9d5aa115073c5cd79d4$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":15,"q_ok":9,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0301.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0301.json$t$, true),
  ($t$0303$t$, $t$Bordentown City$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy / Certificate of Approval (Change of Occupancy housing inspection)$t$, $j$["Issued by: City of Bordentown Department of Housing, Zoning & Code Enforcement (Housing Inspector)","Contact: Charles Latini, Housing/Code Enforcement · 609-298-0604 · planning@cityofbordentown.com","Apply: Apply at least 14 days but not more than 30 days before the change in occupancy; the FAQ says allow at least 2 weeks to get the first inspection appointment.","How to apply: Fill out the Change of Occupancy Application (Certificate of Occupancy Application in the city's Application & Forms folder), pay the fee, and send it to the Department of Housing, Zoning & Code Enforcement, 101 E. Park Street, Bordentown, NJ 08505 (planning@cityofbordentown.com). The next available inspection is scheduled once the form is filed and paid. Vacant homes can use a lock box; otherwise someone 18 or older must let the inspector in.","Smoke alarms on every level and outside each sleeping area; replace alarms older than 10 years; battery units must be 10-year sealed","Carbon monoxide alarm near the bedrooms if there are fuel-burning appliances or an attached garage","Fire extinguisher at least 2A:10B:C (see fire certificate details)","Electrical: 100-amp minimum service, outlets grounded with cover plates, GFI outlets in bathrooms, panel door and no open slots","Plumbing: no leaks, J-bend sink drains, water heater relief pipe to 6 inches above floor, hot water 120 to 140 degrees F, backflow devices, water meter installed","Sump pump works and opening is covered","Floors, walls and ceilings sound and free of holes, trip hazards and peeling paint","Kitchen: stove, oven and broiler work; anti-tip bracket on range; cabinets intact","Windows open, stay open, lock and have intact screens; doors latch, exterior and bathroom doors lock","Graspable handrails on 3 or more steps; porch and deck railings with openings no more than 4 inches","Roofing certification if there are signs of active leaks; Level II chimney certification for wood stoves or wood fireplaces","Exterior, gutters, fences, sidewalks, driveways and patios in safe repair; trip hazards on adjacent sidewalks must be fixed","Visible structural defects fixed; yard mowed and cleared of junk and debris","Work done without permits must be permitted and inspected before the CO is issued","House number visible from the street (front and back if on an alley)","Also: Open permits: Work done without required permits must be permitted and inspected before the CO is issued. Open permits and violations can be checked with an OPRA request to the Municipal Clerk.","Also: As-is purchase: Buyer can request a 'No Occupancy' letter for closing; the application and fee, signed as-is contract and a signed buyer letter are required, and the buyer signs the letter at the Housing Inspection Office.","Also: Chimney certification: Level II chimney inspection by a qualified chimney sweep for solid fuel stoves or wood burning fireplaces.","Also: Roofing certification: Required from a licensed roofer if there is interior evidence of active leaks."]$j$::jsonb, $j$[{"label":"Resale inspection","amount":"$125.00"},{"label":"Re-inspection","amount":"$50.00"},{"label":"Rental inspection (for comparison, rentals only)","amount":"$75.00"}]$j$::jsonb, $t$https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4658/Bordentown/c744b606-0a0d-4ae2-a805-cf8ea0b38705/CO-APP.pdf?disposition=inline$t$, $t$https://www.cityofbordentown.com/documents/application-%26-forms/597539$t$, $j$[{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4658/Bordentown/3f01d2a8-840c-4602-a4b0-7ae1e78ed4c6/Frequently_Asked_Questions.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4658/Bordentown/36ca67e8-58db-4c60-8e1f-68ff29cda6e2/Important_Housing_Inspection_Information.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4658/Bordentown/c744b606-0a0d-4ae2-a805-cf8ea0b38705/CO-APP.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://thrillshare-cmsv2.services.thrillshare.com/api/v2/s/366850/directories?page_no=1","label":"Official source (thrillshare-cmsv2.services.thrillshare.com)"},{"url":"https://web.archive.org/web/20240620180801/https://cityofbordentown.com/wp-content/uploads/2022/10/CO-Application-rev-9-2022.pdf","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$A Certificate of Occupancy is required in Bordentown City when selling or purchasing a property, when there is a change in occupancy, or when a property is to be rented out.$t$, $t$aba432019b553501553235ad4a00970a7d05f3e7d7a34aedd3bf56519e4384fc$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":13,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0303.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0303.json$t$, true),
  ($t$0303$t$, $t$Bordentown City$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Bordentown Department of Housing, Zoning & Code Enforcement (smoke, CO and extinguisher checked in the city housing inspection) (town fire bureau)","Contact: Charles Latini, Housing/Code Enforcement · 609-298-0604 · planning@cityofbordentown.com","Apply: Apply 14 to 30 days before the change in occupancy","How to apply: Part of the city Change of Occupancy Application; no separate smoke certificate application was found.","Fire official in the NJ state directory (fire district), updated 7/31/2025: Mark Mezger · (609) 298-5375 · mmezger@missionfire.org","Smoke alarms must be replaced after 10 years; battery alarms must be 10-year sealed (ANSI/UL 217); hardwired alarms from original construction stay hardwired","Required alarm type depends on the year the house was built (for example 1984-1990 electric interconnected on all levels; 1992 to present electric interconnected in all bedrooms with battery backup)","Carbon monoxide alarm near the bedrooms if fuel-burning appliances or an attached garage (UL 2034)","Fire extinguisher at least 2A:10B:C, no more than 10 lb, within 10 feet of the kitchen, top no higher than 5 feet, on the maker's bracket, near an exit path","Extinguisher must be tagged by a Division of Fire Safety certified contractor within 12 months or have a recent purchase receipt; leave the owner's manual; do not remove the tamper seal","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Combined resale housing inspection including smoke/CO/extinguisher (paid once)","amount":"$125.00"},{"label":"Combined re-inspection","amount":"$50.00"}]$j$::jsonb, $t$https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4658/Bordentown/c744b606-0a0d-4ae2-a805-cf8ea0b38705/CO-APP.pdf?disposition=inline$t$, $t$https://www.cityofbordentown.com/documents/application-%26-forms/597539$t$, $j$[{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4658/Bordentown/20494142-8d92-4c65-b53c-83e27bd9568b/Inspection_Guidelines.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4658/Bordentown/a24fbf43-2648-48d7-87f9-19375ba92f53/Smoke_Detector_Information.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4658/Bordentown/22e0f63e-a3a2-45b7-815f-23d4ef758fb7/Fire_Extinguisher_Information.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.missionfire.org/prevention.php","label":"Official source (missionfire.org)"},{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4658/Bordentown/c744b606-0a0d-4ae2-a805-cf8ea0b38705/CO-APP.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"}]$j$::jsonb, $t$Required in all buildings that contain fuel burning appliances or that have an attached garage.$t$, $t$8637b5f76a961c00d8756918762ab7284baabea1d6059dcd695208ae0a4c6ada$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":13,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0303.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0303.json$t$, true),
  ($t$0304$t$, $t$Bordentown Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Conformity for Resale / Change of Occupancy$t$, $j$["Issued by: Bordentown Township Construction Department (inspection by the fire district serving the block)","Contact: Reyan Frank, Technical Assistant to the Construction Official · 609-298-2800 ext. 2121 · r.frank@bordentowntownship.org","Apply: Request at least 10 business days before the change in ownership or occupancy","How to apply: Fill out page 2 (Request for Certificate of Conformity) of the fillable form, check the fire district for the property's block, and return it to the Bordentown Township Construction Department, 1 Municipal Drive, with exact cash or a check payable to Bordentown Township. The fire district then calls the contact person to schedule; the homeowner, realtor or maintenance staff must be present.","Valid for: 60 days","Smoke detectors on all floors (Township Code 274-5); battery units must be 10-year sealed","Carbon monoxide alarm within 10 feet of sleeping areas (UL 2034) if there is a fuel-burning appliance or attached garage","Portable fire extinguisher, 2A:10BC residential, no more than 10 lb, within 10 feet of the kitchen (form still lists it)","House numbers in Arabic numerals, at least 3 inches, on the front wall or porch and visible from the street (Township Code 200-7)","Open construction permits and violations must be closed first","Also: Open permits and violations: Open construction permits and violations must be closed before the Certificate of Conformity is issued."]$j$::jsonb, $j$[{"label":"Single family home, townhouse, duplex, or apartment in a single family home","amount":"$100.00"},{"label":"House resale re-inspection","amount":"$65.00"},{"label":"Apartment in an apartment complex","amount":"$80.00"},{"label":"Apartment re-inspection","amount":"$55.00"}]$j$::jsonb, $t$https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4427/Bordentown/dfb58020-382a-46f3-ab06-b2b90f5c8736/COC_RESALE__fillable_.pdf.pdf?disposition=inline$t$, $t$https://www.bordentowntownship.com/documents/departments/construction/resale-housing-%2F-change-of-occupancy-%2F-change-of-commercial-tenancy/563317$t$, $j$[{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4427/Bordentown/dfb58020-382a-46f3-ab06-b2b90f5c8736/COC_RESALE__fillable_.pdf.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://thrillshare-cmsv2.services.thrillshare.com/api/v2/s/339998/documents?folder_id=563317","label":"Official source (thrillshare-cmsv2.services.thrillshare.com)"},{"url":"https://web.archive.org/web/20240620031242/https://www.bordentowntownship.com/documents/departments/construction/548482","label":"Official source (web.archive.org)"},{"url":"https://thrillshare-cmsv2.services.thrillshare.com/api/v2/s/339996/directories?page_no=1","label":"Official source (thrillshare-cmsv2.services.thrillshare.com)"}]$j$::jsonb, $t$Inspection requests must be made at least TEN (10) BUSINESS DAYS prior to the change in ownership or occupancy of the dwelling.$t$, $t$de6e2b76c40a9b162c4f1d27e0f8e818f77913c4e31a8a9358fbea328bb0bfdc$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":17,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0304.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0304.json$t$, true),
  ($t$0304$t$, $t$Bordentown Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Blocks 1 through 61: issued by Bordentown Township Fire District #1 (Mission Fire Company) Fire Prevention Bureau (fire district)","Blocks 1 through 61 contact: Mark Mezger, Fire Marshal · 609-298-5375 ext. 105 · dutyfm@missionfire.org","Blocks 1 through 61, apply: 10 business days","Blocks 1 through 61, how to apply: Apply through the township Construction Department using the Certificate of Conformity form and check Fire District #1 (Mission). The district calls to schedule.","Block 62 and up: issued by Bordentown Township Fire District #2 (Derby) (fire district)","Block 62 and up contact: Scully, Captain · 609-298-8527 · inspections@btfd2.org","Block 62 and up, apply: 10 business days","Block 62 and up, how to apply: Apply through the township Construction Department using the Certificate of Conformity form and check Fire District #2 (Derby). The district calls to schedule.","Fire official in the NJ state directory (fire district), updated 3/5/2026: Mark Mezger · (609) 298-5375 · mmezger@missionfire.org","All battery smoke alarms must be 10-year sealed units; alarms on each level and outside each sleeping area; alarms need not be interconnected; hardwired alarms from original construction cannot be replaced with battery units","Smoke/CO combination units are acceptable but must have the 10-year sealed battery","Fire extinguisher at least 2A:10BC, no more than 10 lb, within 10 feet of the kitchen, top no higher than 60 inches, on the maker's bracket, near an exit path, with the owner's manual; proof of purchase accepted instead of a service tag (form created March 2024 still lists it)","House numbers at least 3 inches, Arabic numerals, contrasting and visible from the street","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Blocks 1 through 61: Combined Certificate of Conformity inspection, house (paid once, to Bordentown Township)","amount":"$100.00"},{"label":"Blocks 1 through 61: Combined re-inspection, house","amount":"$65.00"},{"label":"Block 62 and up: Combined Certificate of Conformity inspection, house (paid once, to Bordentown Township)","amount":"$100.00"},{"label":"Block 62 and up: Combined re-inspection, house","amount":"$65.00"}]$j$::jsonb, $t$https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4427/Bordentown/dfb58020-382a-46f3-ab06-b2b90f5c8736/COC_RESALE__fillable_.pdf.pdf?disposition=inline$t$, $t$https://www.missionfire.org/prevention.php$t$, $j$[{"url":"https://files-backend.assets.thrillshare.com/documents/asset/uploaded_file/4427/Bordentown/dfb58020-382a-46f3-ab06-b2b90f5c8736/COC_RESALE__fillable_.pdf.pdf?disposition=inline","label":"Official source (files-backend.assets.thrillshare.com)"},{"url":"https://www.missionfire.org/prevention.php","label":"Official source (missionfire.org)"},{"url":"https://www.missionfire.org/","label":"Official source (missionfire.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.btfd2.org/contact-information.html","label":"Official source (btfd2.org)"}]$j$::jsonb, $t$FIRE DISTRICT #1 (Mission) Block 1 through 61 (609) 298-5375 ext. 105 or email dutyfm@missionfire.org$t$, $t$ad16c22b31247156a13d2115b7f2d106a2d27e2fc4b3ecc15b3a9e44e8529fd6$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":17,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0304.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0304.json$t$, true),
  ($t$0305$t$, $t$Burlington City$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate of Inspection / Housing Clear Certificate (certificate of continued occupancy)$t$, $j$["Issued by: City of Burlington Code Enforcement (Resales)","Contact: Autumn Harley, Resales, Code Enforcement · 609-386-0200 ext. 132 · Resales@burlingtonnj.us","Apply: Apply at least 30 business days before closing, as soon as the seller decides to sell. No same-day inspections.","How to apply: Once there is a buyer, the seller or agent submits the Resale Certificate of Inspection Application to resales@burlingtonnj.us (or by mail to Code Enforcement, 525 High Street) with the $100 fee. Pay online through the city's Pay Here link on the Code Enforcement page, using the property address as the reference number. Code Enforcement emails the appointment to the agent; inspections are Monday, Wednesday and Friday 9 AM to 1 PM. A lock box code is used only if the home is vacant.","Valid for: 60 days","Ten-year sealed battery smoke alarm on each level of living space, in every bedroom and in the basement","Carbon monoxide alarm within 10 feet of the sleeping areas","Fire extinguisher 2A-10B:C under 10 lb within 10 feet of the kitchen, visible, not behind a door or cabinet, top no more than 5 feet above the floor","Chimney certification for fossil fuel burning fireplaces and appliances","Handrails on 4 or more risers; guardrails on porches and decks 30 inches or more above grade","GFCI outlets within 6 feet of water; circuit breaker panel in order; no bare-wire fixtures","Ceilings, walls and floors without holes, chipped paint, severe cracks or water stains","Key locks on entry doors only","Heat, appliances, hot and cold water and toilets working; anti-tip device on range","Water heater bonding strap and relief valve pipe extended to 6 inches from the floor","Bathroom has a window or exhaust fan","Utilities on at the time of inspection","Yard free of trash, motor vehicles and debris; no exterior damage or roof leaks; code violations abated","No work without permits, no illegal apartments or illegally rented rooms","Also: Open permits: All open construction permits must be closed out with the Construction Office, and any work needing permits must pass permit inspection, before the city issues the final clear housing certificate.","Also: Permits for water heaters and HVAC: The application asks that permits be pulled and closed for all water heaters, HVAC equipment and any other work before the inspection.","Also: Chimney certification: Needed for fossil fuel burning fireplaces and appliances."]$j$::jsonb, $j$[{"label":"Resale processing and inspection","amount":"$100.00"},{"label":"Each additional re-inspection","amount":"$75.00"},{"label":"No one present / missed inspection","amount":"$100"}]$j$::jsonb, $t$https://www.burlingtonnj.us/wp-content/uploads/2026/02/Resale-Application.pdf$t$, $t$https://www.burlingtonnj.us/code-enforcement/$t$, $j$[{"url":"https://www.burlingtonnj.us/wp-content/uploads/2026/02/RESALE-PROCESS-with-Checklist-2-3-26.pdf","label":"Official source (burlingtonnj.us)"},{"url":"https://www.burlingtonnj.us/wp-content/uploads/2026/02/Resale-Application.pdf","label":"Official source (burlingtonnj.us)"},{"url":"https://www.burlingtonnj.us/code-enforcement/","label":"Official source (burlingtonnj.us)"}]$j$::jsonb, $t$Homes that are sold in the City of Burlington must be inspected. The seller must receive a Housing Clear Certificate before transferring ownership.$t$, $t$cf6f7fd659df6e45d83a4decc359ac8f6c5bf0942fde67c3b473325afc0232b6$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":11,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0305.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0305.json$t$, true),
  ($t$0305$t$, $t$Burlington City$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: City of Burlington Code Enforcement (resale inspection issues the Housing Clear Certificate and the NJ Division of Fire Safety certificate) (town fire bureau)","Contact: Autumn Harley, Resales, Code Enforcement · 609-386-0200 ext. 132 · Resales@burlingtonnj.us","Apply: At least 30 business days before closing","How to apply: Part of the city Resale Certificate of Inspection application; no separate smoke certificate application.","Fire official in the NJ state directory (town), updated 8/13/2026: Corey Towner · (609) 386-0200 · ctowner@burlingtonnj.us","Ten-year sealed battery smoke alarm on each level, in every bedroom and in the basement","Carbon monoxide alarm within 10 feet of the sleeping areas","Fire extinguisher 2A-10B:C, under 10 lb, within 10 feet of each kitchen, visible and accessible, on the maker's bracket, top no more than 5 feet above the floor (Resale Process dated February 2026 still requires it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Combined resale inspection including smoke/CO/extinguisher (paid once)","amount":"$100.00"},{"label":"Combined re-inspection","amount":"$75.00"}]$j$::jsonb, $t$https://www.burlingtonnj.us/wp-content/uploads/2026/02/Resale-Application.pdf$t$, $t$https://www.burlingtonnj.us/code-enforcement/$t$, $j$[{"url":"https://www.burlingtonnj.us/wp-content/uploads/2026/02/RESALE-PROCESS-with-Checklist-2-3-26.pdf","label":"Official source (burlingtonnj.us)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.burlingtonnj.us/division-of-fire-prevention/","label":"Official source (burlingtonnj.us)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The inspection conducted by City of Burlington is the basis for the issuance of a Housing Clear Certificate & New Jersey Division Fire Safety (NJDFS) Certificate as required by Chapter 195 -15A, City Ordinance.$t$, $t$acaa666ceb8ee3f1063c4f22caeb977f5a4c83234b5a1fe6505c51d7972217dc$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":11,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0305.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0305.json$t$, true),
  ($t$0306$t$, $t$Burlington Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (resale housing inspection)$t$, $j$["Issued by: Burlington Township Licenses & Inspections (Housing Inspector)","Contact: Anthony Trappanese, Housing Inspector/Zoning Officer/Property Maintenance Inspector · 609-239-5845 · HousingInspection@twp.burlington.nj.us","Apply: No minimum lead time published; an expedited inspection within 5 days of the request costs $200.","How to apply: Fill out the Housing Inspection Request (listed as Residential CO Application on the Licenses & Inspections page) and return it to Caitlyn Bryant or Anthony Trappanese by email to HousingInspection@twp.burlington.nj.us or fax 609-239-6293. Licenses & Inspections is at 851 Old York Road.","Valid for: 60 days from issuance","Smoke detector on each level","Carbon monoxide detector in the hallway outside the bedrooms, within 10 feet of each bedroom (one per hallway on each bedroom floor)","Fire extinguisher 2A 10 BC mounted no higher than 5 feet, within 10 feet of the kitchen","All windows open, close and lock; screens on windows and patio doors without rips","Outlets grounded; GFCI outlets working near water sources","Toilets flush properly, no leaks under sinks","Oven and stove working with an anti-tilt bracket","Overflow pipe on the water heater","Heater certification and chimney certification before the CO is issued","Railings for 4 or more steps or 30 inches and above","House number on the home; exterior maintained","No active, open or unpaid permits","Also: Heater and chimney certifications: Required on single family, townhouse and condo resales before the CO is issued; they expire with the CO.","Also: Open permits: Call Licenses and Inspections (609-239-5847) to make sure there are no active, open or unpaid permits for the home."]$j$::jsonb, $j$[{"label":"Resale inspection, single family house, townhouse or condo","amount":"$100.00"},{"label":"Resale re-inspection, single family house, townhouse or condo","amount":"$50.00"},{"label":"Resale inspection, low-mod (affordable housing) unit","amount":"$50.00"},{"label":"Resale re-inspection, low-mod (affordable housing) unit","amount":"$20.00"},{"label":"Expedited inspection (within 5 days of request)","amount":"$200.00"}]$j$::jsonb, $t$https://www.twp.burlington.nj.us/filestorage/279/714/753/HousingInspectionRequestForm.pdf$t$, $t$https://www.twp.burlington.nj.us/licenses-and-inspections/$t$, $j$[{"url":"https://www.twp.burlington.nj.us/licenses-and-inspections/","label":"Official source (twp.burlington.nj.us)"},{"url":"https://www.twp.burlington.nj.us/filestorage/279/714/753/CO_Inspection_Fees.pdf","label":"Official source (twp.burlington.nj.us)"},{"url":"https://www.twp.burlington.nj.us/filestorage/279/714/753/HousingInspectionRequestForm.pdf","label":"Official source (twp.burlington.nj.us)"},{"url":"https://www.twp.burlington.nj.us/filestorage/279/714/753/HousingInspectionItems.pdf","label":"Official source (twp.burlington.nj.us)"}]$j$::jsonb, $t$Housing/Rental/Apartment Inspections are to provide minimum, reasonable standards before the occupancy of a home/apartment$t$, $t$95582acb9a499c176a19f4c0ad3521a198e37c94ba68c6facde2df7d26c65b53$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":13,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0306.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0306.json$t$, true),
  ($t$0306$t$, $t$Burlington Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Burlington Township Licenses & Inspections (housing inspector checks smoke, CO and extinguisher in the resale inspection) (town fire bureau)","Contact: Caitlyn Bryant, Technical Assistant, Licenses & Inspections · 609-239-5846 · cbryant@twp.burlington.nj.us","How to apply: Part of the township Housing Inspection Request; no separate smoke certificate application was found.","Fire official in the NJ state directory (fire district), updated 7/22/2026: Ashley L Johnson · (609) 239-5850 · ajohnson@btfd.org","Smoke detector on each level","Carbon monoxide detectors in the bedroom hallway, within 10 feet of each bedroom","Fire extinguisher 2A 10 BC mounted in the kitchen no more than 5 feet above the floor (still listed on the township page and 2018 items sheet)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Combined resale housing inspection including smoke/CO/extinguisher, single family house, townhouse or condo (paid once)","amount":"$100.00"},{"label":"Combined re-inspection","amount":"$50.00"}]$j$::jsonb, $t$https://www.twp.burlington.nj.us/filestorage/279/714/753/HousingInspectionRequestForm.pdf$t$, $t$https://www.twp.burlington.nj.us/licenses-and-inspections/$t$, $j$[{"url":"https://www.twp.burlington.nj.us/licenses-and-inspections/","label":"Official source (twp.burlington.nj.us)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://btfd.org/fire-safety-prevention/","label":"Official source (btfd.org)"},{"url":"https://www.twp.burlington.nj.us/filestorage/279/714/753/CO_Inspection_Fees.pdf","label":"Official source (twp.burlington.nj.us)"}]$j$::jsonb, $t$The housing inspector also checks smoke detectors(one on each level), carbon monoxide detector(s) and fire extinguisher.$t$, $t$8cbdbb4b871468044fcdcfbea540f3ce3fcb4dfd51e57f79dc2162e68de4cdec$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":13,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0306.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0306.json$t$, true),
  ($t$0307$t$, $t$Chesterfield Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection (resales or rentals)$t$, $j$["Issued by: Chesterfield Township Construction Office (Code Enforcement Officer)","Contact: Glenn McMahon, Code Enforcement Officer · 609-298-2311 ext. 140 · glenn@chesterfieldtwp.com","Apply: No set lead time; the certificate takes 3 business days to generate after all repairs and certifications are in, so allow time before closing.","How to apply: Fill out the Application for Certificate of Inspection, mark Resale, and pay by check or cash at the Township of Chesterfield, 295 Bordentown-Chesterfield Road. Call 609-298-2311 ext. 140 to schedule the inspection (voice mail requests are accepted). Turn in original certifications and the well water form if needed.","Smoke detectors on each floor, working; tested by the township inspector (or certification from the monitoring company if monitored)","Carbon monoxide detectors near the bedrooms","Visible 2.5 to 10 lb ABC fire extinguisher hung no higher than 60 inches and within 10 feet of the kitchen (April 2024 form)","Original certifications for the heater, heater chimney, wood fireplaces or woodstoves, and their chimneys","Well water test by a certified lab if on well water; buyer signs that they were told the results","GFI outlets outside, within 6 feet of the kitchen sink and in every bathroom; three-prong outlet for the washer; no open spaces in the panel; no multi-gang outlets or extension cords","Guardrails and handrails on all stairways; halls and stairways lighted","Heater and water heater relief valve pipe within 6 to 8 inches of the floor","Gutters, downspouts, screens, windows, siding, paint, decks, porches and accessory buildings in repair","Interior wall holes, tub and shower tile and leaking faucets repaired","No trash or rubbish on the property","House number visible on the front of the house or the mailbox","Also: Well water test: If on well water, have it tested by a certified lab; the buyer signs the township water test certification.","Also: Heater and chimney certifications: Original certifications for the heater, heater chimney, fireplaces or woodstoves and their chimneys are required before the certificate is issued."]$j$::jsonb, $j$[{"label":"Resale certificate of inspection (includes one re-inspection)","amount":"$50.00"},{"label":"Each additional inspection after the included re-inspection","amount":"$25.00"}]$j$::jsonb, $t$https://web.archive.org/web/20240520224747/https://chesterfieldtwpnj.gov/images/construction/certificate_of_inspection_app41824.pdf$t$, $t$https://web.archive.org/web/20241228104107/https://www.chesterfieldtwpnj.gov/construction$t$, $j$[{"url":"https://web.archive.org/web/20240520224747/https://chesterfieldtwpnj.gov/images/construction/certificate_of_inspection_app41824.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20241228104107/https://www.chesterfieldtwpnj.gov/construction","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$APPLICATION FOR CERTIFICATE OF INSPECTION$t$, $t$a15917c041b1bc845fd083bd713d4021fa7cc8266550ead0d39ad60a061e9546$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":11,"q_ok":6,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0307.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0307.json$t$, true),
  ($t$0307$t$, $t$Chesterfield Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Chesterfield Township Construction Office (smoke and CO checked in the township Certificate of Inspection) (town fire bureau)","Contact: Glenn McMahon, Code Enforcement Officer · 609-298-2311 ext. 140 · glenn@chesterfieldtwp.com","How to apply: Part of the township Certificate of Inspection application; no separate smoke certificate application was found.","Fire official in the NJ state directory (NJ DCA, state), updated 6/16/2026: Louis Kilmer · (609)633-6132","Smoke detectors on each floor and carbon monoxide detectors near the bedrooms, tested by the township inspector during the Certificate of Inspection","2.5 to 10 lb ABC fire extinguisher, visible, no higher than 60 inches, within 10 feet of the kitchen (April 2024 form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Combined resale Certificate of Inspection including smoke/CO check (paid once)","amount":"$50.00"}]$j$::jsonb, $t$https://web.archive.org/web/20240520224747/https://chesterfieldtwpnj.gov/images/construction/certificate_of_inspection_app41824.pdf$t$, $t$https://web.archive.org/web/20241228104107/https://www.chesterfieldtwpnj.gov/construction$t$, $j$[{"url":"https://web.archive.org/web/20240520224747/https://chesterfieldtwpnj.gov/images/construction/certificate_of_inspection_app41824.pdf","label":"Official source (web.archive.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Smoke detectors and carbon monoxide detectors will be tested by the Township Inspector during the physical inspection of your property, unless you have a monitored system.$t$, $t$62ff3be77b366fcf3b32c1866723f321473e13699d27f0d1c011377a3f5c9d0a$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":11,"q_ok":6,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0307.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0307.json$t$, true),
  ($t$0308$t$, $t$Cinnaminson Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Cinnaminson Township. Confirm with the office if the buyer's lender or title company asks.","Contact: 856-829-6000 ext. 2379","How to apply: No town resale CO is needed. The Township says to contact the Cinnaminson Sewerage Authority (856-829-5287) for the sewer compliance inspection and the Fire District (856-829-5220) for the smoke and CO alarm inspection.","Also: Sewer compliance inspection (Cinnaminson Sewerage Authority): All properties require a sewer compliance inspection before settlement. Call 856-829-5287 to schedule. Title companies can submit the online form to get the open balance and recommended escrow. The inspection fee is collected at the time of inspection; the amount is not published."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://cinnaminsonnj.org/office-of-community-and-economic-development/$t$, $j$[{"url":"https://cinnaminsonnj.org/office-of-community-and-economic-development/","label":"Official source (cinnaminsonnj.org)"}]$j$::jsonb, $t$Do I need a Certificate of Occupancy Inspection to sell my home? No, Cinnaminson Township does not require CO inspections for resale of a residential home. They do require an inspection from the Sewerage Authority (856)829-5287 and the Fire District (856)829-5220. Please contact them directly for scheduling and fees.$t$, $t$4d2f05917db4260826bc4d5d7d64e6a965595c2b3939968f5e0fdd507fb9c6b0$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":9,"q_ok":9,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0308.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0308.json$t$, true),
  ($t$0308$t$, $t$Cinnaminson Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Cinnaminson Fire District No. 1, Fire Marshal's Office (Bureau of Fire Prevention) (fire district)","Contact: Jesse Nickum, Fire Marshal (Lieutenant) · 856-829-5220 · jnickum@cinnaminsonfire.org","Apply: At least one week advance notice to schedule the inspection","How to apply: Submit the online Application for Home Inspection on the fire department website (property address, block and lot, seller and agent contacts, settlement date). Pay by check or money order payable to Cinnaminson Fire District, or through the district's online payment link. Give at least one week notice.","Fire official in the NJ state directory (fire district), updated 1/12/2026: Jesse Nickum · (856) 829-5220 · jnickum@cinnaminsonfire.org","Battery smoke alarms must be 10-year sealed lithium battery units","Smoke alarms cannot be older than 10 years from the manufacture date","Smoke alarms on each level and outside each sleeping area; hardwired alarms must stay hardwired with battery backup and cannot be swapped for battery units","CO alarm near all sleeping areas (within 10 feet of all bedrooms) if there are fuel burning appliances or an attached garage","The district's current forms still list a portable fire extinguisher: at least 2-A:10-B:C, no more than 10 pounds, within 10 feet of the kitchen in the path of exit, not next to the stove, mounted on the maker's bracket with the top no more than 5 feet above the floor, with the manual left for the buyer, and a service tag from a state-certified contractor within 12 months or a purchase receipt under 12 months old","House numbers visible from the street: Arabic numerals, contrasting color, at least 3 inches tall, mounted at least 30 inches above grade","Owner or representative 18 or older must be present at the inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Initial inspection","amount":"$80.00"},{"label":"Re-inspection","amount":"$55.00"},{"label":"Missed appointment","amount":"$45.00"},{"label":"Senior citizen discount (ID required)","amount":"$10.00"}]$j$::jsonb, $t$https://cinnafire.org/fire-marshal/application-for-home-inspection/$t$, $t$https://cinnafire.org/fire-marshal/home-inspection-information/$t$, $j$[{"url":"https://cinnafire.org/fire-marshal/home-inspection-information/","label":"Official source (cinnafire.org)"},{"url":"https://cinnafire.org/fire-marshal/application-for-home-inspection/","label":"Official source (cinnafire.org)"},{"url":"https://cinnafire.org/cfd/staff/","label":"Official source (cinnafire.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The New Jersey Fire Code requires that whenever a home is being sold, or a rental unit changes occupant, that a Certificate of Smoke and Carbon Monoxide Detector Compliance be obtained from the local fire code enforcing agency, which in Cinnaminson is the Cinnaminson Fire Marshal's Office.$t$, $t$a2ae2ebb8892f379988987dc5b69415cbd7c7aebd6810053967125867c74ed87$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":9,"q_ok":9,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0308.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0308.json$t$, true),
  ($t$0309$t$, $t$Delanco Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Habitability (COH)$t$, $j$["Issued by: Delanco Township (Rental/COH Coordinator, Municipal Building)","Contact: Jessica Husband, Rental / COH Coordinator · 856-461-0561 ext. 222","Apply: No set lead time published. The applicant must schedule the inspection, and any violations must be corrected within 90 days.","How to apply: Fill out the Certificate of Habitability Application (Buying or Selling a Home) and return it with $100 cash or a check payable to Delanco Township to the Municipal Building, 770 Coopertown Rd., Delanco, NJ 08075. Then call Jessica Husband at 856-461-0561 ext. 222 to set up the inspection; the applicant must schedule it.","Valid for: 90 days or until the next change in ownership, whichever comes first","Walls and ceilings free of cracks or holes in every room","Floor coverings, windows and doors in good condition","Electrical wiring, fixtures and receptacles working; enough outlets in bedrooms","Entrance locks on front, rear and side doors cannot need a key from the inside","Kitchen counter, sink, dishwasher, exhaust and stove anti-tip device","Bathroom tile, sink, tub, toilet and ventilation fan","Handrails, guards and stairs sound","Exterior: roof, gutters and downspouts, paint, windows, foundation, siding, chimney cap","Fence and gate, lawn and landscaping kept up, no rubbish or debris","House number visible, driveway cracks and holes, front light working","Heating, electrical or plumbing certifications if the inspector asks for them","Also: Sewer inspection (Delanco Sewerage Authority): SEWER INSPECTION: $25 cash or check payable to Delanco Sewerage Authority may accompany the COH application. Call Delanco Sewer at 856-461-6876 to set up the appointment."]$j$::jsonb, $j$[{"label":"Home inspection (COH application)","amount":"$100"},{"label":"Each re-inspection after the first free one","amount":"$50"}]$j$::jsonb, $t$https://www.delancotownship.com/filestorage/5328/5330/10714/Certificate_of_Habitability_Application_REVISED_06-02-2025.pdf$t$, $t$https://www.delancotownship.com/onlineforms$t$, $j$[{"url":"https://www.delancotownship.com/filestorage/5328/5330/10714/Certificate_of_Habitability_Application_REVISED_06-02-2025.pdf","label":"Official source (delancotownship.com)"},{"url":"https://www.delancotownship.com/content/5300/7041/default.aspx","label":"Official source (delancotownship.com)"},{"url":"https://www.delancotownship.com/filestorage/5328/5330/10714/Certificate_of_Habitability_-COH-_Inspection_Guidelines.pdf","label":"Official source (delancotownship.com)"}]$j$::jsonb, $t$CERTIFICATE OF HABITABILITY APPLICATION ... Buying or Selling a Home$t$, $t$7e00d189220ccfd0ec0ad5566dafe5594f8cb99ab989080197b498ca21fddc5b$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0309.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0309.json$t$, true),
  ($t$0309$t$, $t$Delanco Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Delanco Fire District No. 1, Bureau of Fire Prevention & Inspection (fire district)","Contact: Randy Johnson, Fire Official · 856-764-8176 · fm@delancofire.com","Apply: Submit the form and payment at least 10 business days before settlement. Inspections are scheduled on the first available Monday after all information and payment are received. If settlement is less than 10 business days away, email and call the Fire Official.","How to apply: Download the Application for Certification of Smoke Alarm and Carbon Monoxide Alarm Compliance, complete the self-inspection form, and mail it with a check or money order payable to Delanco Fire District #1 to Delanco Fire Official, P.O. Box 5021, Delanco, NJ 08075. Payment must be received before the inspection is scheduled.","Fire official in the NJ state directory (fire district), updated 6/16/2026: Randy Johnson · (856) 764-8176 · rjjohnson@comcast.net","All smoke and CO alarms must be less than 10 years old","All non-AC (battery) smoke alarms must be the 10-year sealed battery type","Smoke alarm type and locations depend on the year the home was built (for example, 1991 and newer: interconnected AC alarms with battery backup on each level and in each bedroom)","CO alarms near sleeping areas if the home has a fuel-burning device or attached garage","House number easily visible from the street","Homes with a secondary power source (generator, solar panels, battery storage) need printed warning labels such as 'CAUTION: MULTIPLE SOURCES OF POWER' within 18 inches of the main electrical panel and within 18 inches of the electric meter (ANSI Z535.4 label accepted); hand-written labels not allowed","Seller must complete and sign a self-inspection certification on the form before the inspection is scheduled","A separate application and fee is required for each dwelling unit on the property","The current form (August 2025) does not list a portable fire extinguisher","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO certificate, application received 10+ business days before settlement (per dwelling unit)","amount":"$45.00"}]$j$::jsonb, $t$https://www.delancofire.com/_files/ugd/6a69cf_4e8f084c80ef4ec28cc09d33bdc48ff7.pdf$t$, $t$https://www.delancofire.com/fire-marshall$t$, $j$[{"url":"https://www.delancofire.com/fire-marshall","label":"Official source (delancofire.com)"},{"url":"https://www.delancofire.com/_files/ugd/6a69cf_4e8f084c80ef4ec28cc09d33bdc48ff7.pdf","label":"Official source (delancofire.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$This includes the Residential Resale-Smoke/CO Detector Inspection.$t$, $t$d63a983404f7c5cd63b746617618a73ec2235cf92dd8e3949b849f099491dabc$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0309.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0309.json$t$, true),
  ($t$0310$t$, $t$Delran Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$verify$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not confirmed yet: Delran Township's official pages list no town resale certificate for sales, but they don't say in writing that none is needed. Call the office before closing.","Contact: Bill Lunemann, Construction Official · 856-461-8667 · constructioninspections@delrantownship.org","How to apply: The Township's Construction Office page tells sellers that the Fire District Office handles resale inspections; no separate township resale certificate is described. See the fire certificate section."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://delrantownship.org/construction-office/$t$, $j$[{"url":"https://delrantownship.org/construction-office/","label":"Official source (delrantownship.org)"},{"url":"https://delrantownship.org/fire-department/","label":"Official source (delrantownship.org)"}]$j$::jsonb, $t$Selling Your House? The Fire District Office handles inspections for resale. You will need to have your house inspected before you go to settlement;$t$, $t$05e081348d6a71ab9fc4cae8064714fb9ffedc37371f951c105fe481603b363f$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["no town certificate listed, but not ruled out in writing"],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":11,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0310.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0310.json. Red flag: no town certificate listed, but not ruled out in writing$t$, true),
  ($t$0310$t$, $t$Delran Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Delran Township Fire District No. 1, Bureau of Fire Prevention (Local Enforcing Agency) (fire district)","Contact: Joseph Cunningham Jr., Fire Marshal / Fire Official · 856-461-5474 · LEA@delranfire.org","Apply: Apply more than 10 business days (excluding holidays) before the change of occupant for the lowest fee. Payment is due before the inspection.","How to apply: Fill out the Application for Inspection (Smoke Detector and CO Detector) and email it to LEA@delranfire.org or drop it off at the Fire District office in the Municipal Building, 900 S. Chester Avenue, Delran. Pay before the inspection by check payable to Delran Fire District #1 or online (list the inspection address as the invoice number).","Fire official in the NJ state directory (fire district), updated 3/5/2026: Joseph Cunningham, Jr · (856) 577-1077 · joseph.cunninghamjr@delranfire.org","Older homes need 10-year sealed battery smoke alarms (or AC powered alarms) on each level and outside sleeping areas","Homes built with hardwired, battery backup, interconnected alarms (for example Summer Hill, Forest Hill, Waters Edge, The Grande, the Orchard) must keep them on each level and in each bedroom, and they must be less than 10 years old","Carbon monoxide detectors must be less than 5 years old (check the manufacture or replace-by date) and installed outside each sleeping area","All smoke and CO detectors must be UL listed","House number: Arabic numerals, contrasting color, at least 3 inches tall, at least 30 inches above ground, visible from the street (Township Code Chapter 95)","The current form (February 2025) does not list a portable fire extinguisher","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received more than 10 business days before closing","amount":"$45.00"},{"label":"Request received 4 to 10 business days before closing","amount":"$90.00"},{"label":"Request received fewer than 4 business days before closing","amount":"$161.00"}]$j$::jsonb, $t$https://www.delranfire.org/content/forms/file/APPLICATION%20FOR%20SD%20INSPECTION%202025.pdf$t$, $t$https://www.delranfire.org/content/prevention$t$, $j$[{"url":"https://www.delranfire.org/content/forms/file/APPLICATION%20FOR%20SD%20INSPECTION%202025.pdf","label":"Official source (delranfire.org)"},{"url":"https://www.delranfire.org/content/prevention","label":"Official source (delranfire.org)"},{"url":"https://www.delranfire.org/content/payment","label":"Official source (delranfire.org)"},{"url":"https://delrantownship.org/fire-department/","label":"Official source (delrantownship.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$N.J. State Fire Code N.J.A.C. 5:70-2.3 requires the inspection of One & Two Family Dwellings and R-2 Occupancies for smoke detectors and carbon monoxide detectors before it is sold or leased.$t$, $t$c7ffeecb487ee0be4890790afce32d895180f93648fb07f77804ce0b24eae9ad$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["no town certificate listed, but not ruled out in writing"],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":11,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0310.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0310.json. Red flag: no town certificate listed, but not ruled out in writing$t$, true),
  ($t$0311$t$, $t$Eastampton Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO), Resale/Rental Inspection$t$, $j$["Issued by: Eastampton Township Resale/Rental Inspections office","Contact: David Shaw, Resale/Rental Inspector · 609-267-5723 ext. 200 · resales@eastampton.com","Apply: Schedule the inspection at least 5 calendar days before settlement; requests 4 calendar days or less before settlement pay the higher fee.","How to apply: Submit the online CCO Application on GovPilot (choose Resale) and pay the fee online, or pay by check payable to Eastampton Township mailed or delivered to 12 Manor House Court, Eastampton, NJ 08060. Schedule the inspection at least 5 calendar days before settlement.","House numbers: numerals at least 4 inches high, contrasting color, fixed to the house and visible from the street (mailbox or lamp post numbers not accepted)","Smoke alarm on every level, including the bottom of the basement stairs at the ceiling","Smoke alarm within 10 feet of all bedroom doors and one on the ceiling of every bedroom","Hardwired smoke alarms cannot be replaced with battery alarms","Smoke alarms under 10 years old and working; battery alarms must be 10-year sealed type","CO alarm in the hallway within 10 feet of all bedrooms, under 10 years old and working","Fire extinguisher (2019 checklist): 2A-10B:C, under 10 pounds, mounted on its bracket within 10 feet of the kitchen in the path of exit","Homes with a monitored low-voltage fire alarm system need a test certificate from an alarm contractor at the inspection","Owner certifies all structures meet zoning and no rubbish, debris or bulk trash is left before the new occupant moves in"]$j$::jsonb, $j$[{"label":"CCO inspection, 5 or more calendar days before settlement (per dwelling unit, includes one reinspection)","amount":"$75"},{"label":"CCO inspection requested 4 calendar days or less before settlement","amount":"$125"},{"label":"Each additional reinspection (after the one included)","amount":"$25"}]$j$::jsonb, $t$https://main.govpilot.com/web/public/f108198f-fab_CCO-Application-eastampton?uid=7272&ust=NJ&pu=1&id=0$t$, $t$https://www.eastampton.com/rental$t$, $j$[{"url":"https://web.archive.org/web/20230323224804/https://www.eastampton.com/rental","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20211231133235/https://www.eastampton.com/sites/default/files/fileattachments/resale/rental_inspections/page/1891/ordinance_2019-9.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20240625220011/http://www.eastampton.com/rental/directory-listing/david-shaw","label":"Official source (web.archive.org)"},{"url":"https://main.govpilot.com/web/public/f108198f-fab_CCO-Application-eastampton?uid=7272&ust=NJ&pu=1&id=0","label":"Official source (main.govpilot.com)"},{"url":"https://web.archive.org/web/20211231172247/https://www.eastampton.com/sites/default/files/fileattachments/resale/rental_inspections/page/4301/inspection_checklist.pdf","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$Per Ordinance 2010-4; 385-4 a Certificate of Occupancy inspection is required for all property resales or rental units whenever there is a change of occupancy and/or ownership.$t$, $t$0049f098304c60075ecc23ba7dbe96feb083e0ff2d3201c17cfe898fa4c481b0$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":2,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0311.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0311.json$t$, true),
  ($t$0311$t$, $t$Eastampton Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Eastampton Township Local Enforcing Agency (Fire Prevention Bureau, Office of the Fire Marshal) (town fire bureau)","Contact: Yunus Boduroglu, Fire Marshal / Fire Official · 609-267-5723 ext. 203 · firemarshal@eastampton.com","How to apply: No separate resale smoke/CO certificate application or fee was found. The smoke, CO and extinguisher items are on the Township's resale CCO checklist; ask the Resale/Rental Inspector or the Fire Marshal whether the CCO inspection also issues the smoke/CO certificate.","Fire official in the NJ state directory (fire district), updated 5/18/2026: Yunus Bodugroglu · (609) 267-5723 · firemarshal@eastampton.com","The Township's CCO inspection checklist (November 2019) covers smoke alarms, CO alarms and a mounted 2A-10B:C fire extinguisher within 10 feet of the kitchen, so these are checked at the resale inspection","Smoke and CO alarms must be under 10 years old; battery smoke alarms must be 10-year sealed type","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.eastampton.com/fm$t$, $j$[{"url":"https://web.archive.org/web/20240130220436/https://www.eastampton.com/fm","label":"Official source (web.archive.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://web.archive.org/web/20211231172247/https://www.eastampton.com/sites/default/files/fileattachments/resale/rental_inspections/page/4301/inspection_checklist.pdf","label":"Official source (web.archive.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Eastampton LEA is administered by Eastampton Township, and is outside of the Fire Department command structure.$t$, $t$e7bda46d3707a5ebd96a74eb3be10caf8c7874d820b5df82923becde40d72f73$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":2,"fee_bad":0,"fee_unchecked":1,"quotes":13,"q_ok":12,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0311.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0311.json$t$, true),
  ($t$0312$t$, $t$Edgewater Park Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection (C/I), formerly Certificate of Occupancy$t$, $j$["Issued by: Edgewater Park Township Inspections Department, Code Enforcement","Contact: Yakup Koksaldi, Code Enforcement · 609-877-2050 ext. 314 · code-enforcement@edgewaterpark-nj.com","Apply: No set lead time published. Payment must be received before the inspection is scheduled; inspections are given the next available slot. A failed resale inspection gets a Temporary C/I good for 30 days.","How to apply: Fill out the Certificate of Inspection Application Report (check Re-Sale Inspection), including seller and buyer contacts and a requested inspection date, and submit it with payment. Pay by check or money order mailed to or left in the drop box at 400 Delanco Road, Edgewater Park, NJ 08010, or in person (cash accepted). The form can also be submitted through the Township's SDL citizen portal (account required). Inspections are not scheduled until payment is received. Call 609-877-2050 ext. 314 or email code-enforcement@edgewaterpark-nj.com to reserve a time.","Valid for: Temporary C/I after a failed resale inspection: 30 days from the first inspection","All open construction permits (old or new) must be closed; work done without a permit must be permitted and inspected","Exterior walls, roof, gutters, foundation, stairs, decks, porches, fences and accessory structures sound and in good repair","House number at least 3 inches high, readable from the street","Driveways and sidewalks level with no tripping hazards; yard maintained","Guardrails on landings and porches 30 inches or higher (balusters no more than 4 inches apart)","No double-keyed deadbolts on exit doors","Pool fence with self-closing, self-latching gate (48 inches; 6 feet for in-ground pools); no stagnant pool water","All utilities on at the time of inspection","Smoke detector on each level and within 10 feet outside sleeping areas; battery units must be 10-year sealed type; existing hardwired units stay","CO detector on all levels with bedrooms","2A-10B:C fire extinguisher mounted on the wall within 10 feet of the kitchen, about 5 feet high, on the way to the exit","Stove anti-tip device; GFCI outlets at kitchen counters and bathrooms; no extension-cord wiring or open splices","No plumbing leaks; heat to all habitable rooms; water heater bonding strap and relief valve pipe to 6 inches off the floor","Electrical, plumbing, roofing or heating certification may be required at the inspector's discretion","A blue recycling cart must be on the property at the inspection","Also: Open construction permits must be closed: Any old or new outstanding construction permits must be closed before a final Certificate of Inspection is issued; unpermitted work must be permitted and inspected by the Construction Department (609-877-2217, inspections@edgewaterpark-nj.com).","Also: Blue recycling cart: A blue recycling cart must be on the premises at the time of inspection and must stay with the property.","Also: Heating system certification: At the inspector's discretion a heating system certification form may be required."]$j$::jsonb, $j$[{"label":"Resale inspection (includes 1 re-inspection)","amount":"$120.00"},{"label":"Each additional re-inspection for a temporary or expired C/O","amount":"$50.00"},{"label":"Re-inspection fee when the Temporary C/I passes its 30-day expiration or after 2 failed inspections in a row","amount":"$50"}]$j$::jsonb, $t$https://www.edgewaterpark-nj.com/filestorage/173/360/430/432/Certificate_of_Occupancy_Form.pdf$t$, $t$https://www.edgewaterpark-nj.com/content/163/338/4749.aspx$t$, $j$[{"url":"https://www.edgewaterpark-nj.com/content/163/338/4749.aspx","label":"Official source (edgewaterpark-nj.com)"},{"url":"https://www.edgewaterpark-nj.com/filestorage/173/360/430/432/Certificate_of_Occupancy_Form.pdf","label":"Official source (edgewaterpark-nj.com)"},{"url":"https://www.edgewaterpark-nj.com/content/163/338/default.aspx","label":"Official source (edgewaterpark-nj.com)"}]$j$::jsonb, $t$is always required when selling or purchasing a property in Edgewater Park Township (this includes purchasing a bank owned/foreclosed parcel), and when a property is to be rented out.$t$, $t$37297996103eb7df463979a5010e5486db45ea0ad9d9424086493a6f0430b952$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":14,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0312.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0312.json$t$, true),
  ($t$0312$t$, $t$Edgewater Park Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Edgewater Park Township Fire District No. 1 (Fire Official / Bureau of Fire Safety) (fire district)","Contact: Matt Augustino, Fire Official · 609-877-8812 · epfdfi14@gmail.com","How to apply: No resale smoke/CO certificate application or fee is posted on the Township or fire district pages. Call the Fire Official's office at 609-877-8812 to request the certificate and confirm the fee.","The Township's resale C/I checklist also covers smoke detectors on each level (10-year sealed battery type if battery powered), CO detectors on levels with bedrooms, and a wall-mounted 2A-10B:C extinguisher within 10 feet of the kitchen (form dated September 2026, after P.L.2025, c.19)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.edgewaterpark-nj.com/content/161/330/907/default.aspx$t$, $j$[{"url":"https://www.edgewaterpark-nj.com/content/161/330/907/default.aspx","label":"Official source (edgewaterpark-nj.com)"},{"url":"https://www.edgewaterpark-nj.com/filestorage/161/330/907/Beverly-EP_Smoke-Detectors_revised.pdf","label":"Official source (edgewaterpark-nj.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The Township has one Fire District, with its own publicly elected Board of Fire Commissioners. The Fire Commissioners are the legal governing body of the Fire Companies, the Bureau of Fire Safety, and the Training Center.$t$, $t$0d4927d430aadb192c90f1a8d917ce011e071406906e2889e4b04f24750e0a5f$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":14,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0312.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0312.json$t$, true),
  ($t$0313$t$, $t$Evesham Township (Marlton)$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Evesham Township (Marlton). Confirm with the office if the buyer's lender or title company asks.","Contact: 856-983-2914","How to apply: No township resale CO or CCO. The Township says all home resales and rentals must get an inspection from the fire department (Evesham Fire-Rescue); see the fire certificate section."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://evesham-nj.org/departments/construction$t$, $j$[{"url":"https://web.archive.org/web/20260508123727/https://evesham-nj.org/construction-page-list/791-construction-faq","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20260508113240/https://evesham-nj.org/departments/construction","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$What if I am selling my house? Is an inspection required? The Township of Evesham does not currently inspect existing residential homes for Certificate of Occupancy or Continuing Certificate of Occupancy. All home resales and rentals are required to obtain an inspection from the Township fire department.$t$, $t$baa1fa11476a7be5a249bad15c128442a866d543ad2ad73730a27bc6276341d1$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":9,"q_ok":9,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0313.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0313.json$t$, true),
  ($t$0313$t$, $t$Evesham Township (Marlton)$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Evesham Township Fire District No. 1 (Evesham Fire-Rescue), Division of Fire Prevention (fire district)","Contact: Scott Freedman, Deputy Chief, Fire Marshal / Fire Official / Fire Subcode Official · 856-983-2750 · sfreedman@eveshamfire.org","Apply: Apply more than 10 business days before the change of occupant for the lowest fee. Inspections are given a block of time; missing it requires a new non-refundable application fee.","How to apply: Start the online Smoke/CO Certificate application on the fire district's Muniverse portal (linked from the Home Smoke/CO Alarm Inspections page). All fees are non-refundable. Questions: Fire Prevention Office, 984 Tuckerton Road, Suite 205, Marlton (Municipal Building 2nd floor), 856-983-2750, open Monday to Thursday 7:30 a.m. to 5:30 p.m. Short sales and foreclosures: call the Division of Fire Prevention to schedule.","Fire official in the NJ state directory (fire district), updated 3/5/2026: Scott L Freedman · (856) 983-2750 · sfreedman@eveshamfire.org","Smoke alarm type and locations depend on the year the home was built (before 1977: 10-year sealed battery alarm on each level including basement; 1992 to present: interconnected hardwired alarms with battery backup in all bedrooms, near bedrooms and on all levels)","Hardwired smoke alarms older than 10 years must be replaced with new hardwired alarms with battery backup","All smoke alarms must be less than 10 years old; if no date is stamped, replace the alarm","Each level needs an AC (hardwired) or 10-year sealed battery smoke alarm; hardwired alarms must be interconnected","CO alarm outside and near all sleeping areas if the home has a fuel-burning appliance, fireplace or garage","House numbers: 3-inch Arabic numerals, contrasting color, at least 30 inches off the ground, visible from the street","Low-voltage fire alarm systems must be tested and approved by an alarm contractor before the inspection; give the certificate to the inspector","Homes with residential fire sprinklers need a licensed sprinkler contractor inspection within 30 days before the fire inspection","Portable fire extinguisher is required for RENTALS ONLY (2A:10BC, kitchen, visible, mounted no higher than 5 feet, tagged within 12 months or new with receipt); not required for sales","No change of ownership or occupancy before a successful inspection and certificate; violators face a $500 penalty per occurrence","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received more than 10 business days before the change of occupant","amount":"$70"},{"label":"Request received 4 to 10 business days before the change of occupant","amount":"$115"},{"label":"Request received fewer than 4 business days before the change of occupant","amount":"$160"},{"label":"Each required re-inspection (a third visit needs a new application and fee)","amount":"$35"}]$j$::jsonb, $t$https://geo.muniverse.us/prod1/portal/portal.jsp?c=596833708&p=557152673&g=557273727$t$, $t$https://eveshamfire.org/inspections-forms/smoke-alarm-certficate/$t$, $j$[{"url":"https://eveshamfire.org/inspections-forms/smoke-alarm-certficate/","label":"Official source (eveshamfire.org)"},{"url":"https://geo.muniverse.us/prod1/portal/portal.jsp?c=596833708&p=557152673&g=557273727","label":"Official source (geo.muniverse.us)"},{"url":"https://eveshamfire.org/facilities/fire-administration-fire-prevention-office/","label":"Official source (eveshamfire.org)"},{"url":"https://eveshamfire.org/organization/contact/","label":"Official source (eveshamfire.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Any change of ownership or occupancy/tenancy may not occur prior to a successful inspection and possession of a CSACMAPFEC Certification. Changes without this inspection will result in a $500 penalty per occurrence (N.J.S.A 52:27D-198.3).$t$, $t$d91184c577585350d70dcb57de0f88db81bd5a6d35989efc77723a1a0a186a55$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":9,"q_ok":9,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0313.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0313.json$t$, true),
  ($t$0315$t$, $t$Florence Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Occupancy (CCO), Residential Change of Tenant/Occupancy/Ownership inspection$t$, $j$["Issued by: Florence Township Housing Department (Construction and Code Enforcement)","Contact: Michael Perna, Housing Inspector · 609-499-2130 ext. 124 · housing@florence-nj.gov","Apply: Allow at least 2 weeks to get the first inspection appointment; in busy times it can be up to 4 weeks out.","How to apply: Fill out page 1 of the Housing Inspection Application form (check Buyer, give owner and buyer contact details) and submit it with the fee to the Florence Township Housing Department, 711 Broad Street, Florence. The inspection is booked for the next open slot once the form is complete and paid. A lock box is allowed for vacant homes; otherwise an adult must let the inspector in. Give at least 24 hours notice to cancel or reschedule. For an as-is sale where the buyer will not move in, ask for a notarized \"No Occupancy\" letter (needs the paid application, the as-is contract and a signed buyer letter).","Smoke alarms on every level and outside each sleeping area; replace alarms older than 10 years; battery units must be 10-year sealed (UL 217)","Carbon monoxide alarm near the bedrooms if the home has fuel-burning appliances or an attached garage","Portable fire extinguisher (Township Code 116-4.B(1)(d)), see fire certificate section","Electrical: 100 amp minimum service, grounded outlets with cover plates, GFI outlets in bathrooms, panel door with no open slots","Plumbing: no leaks, J-bend sink drains, water heater relief pipe to 6 inches above floor, hot water 120 to 140 degrees, backflow devices where needed","Sump pump works, drains properly and opening is covered","Floors, walls and ceilings sound with no holes, trip hazards or loose paint","Kitchen: stove, oven and broiler work; anti-tilt bracket on range","Windows open, stay open and lock; screens on all windows; no broken glass","Doors latch; exterior and bathroom doors lock; garage door and opener work safely","Graspable handrails on stairs; deck and porch railings at 30 inches or more with no more than 4 inch openings","Roof certification from a licensed roofer if there are signs of active leaks","Exterior, gutters, downspouts, fences, sidewalks and driveway in good repair; yard mowed and cleared","Heating system certification on the Township form, original with raised seal (not needed for Florence Tollgate condos); inactive oil fill pipes and tanks removed","Level II chimney certification for wood-burning fireplaces or solid fuel stoves; any work done without permits must be permitted and inspected","Also: Open permits and unpermitted work: Property records are checked. Any work done without a permit must get a permit and pass inspection, and outstanding construction permits must be closed, before the CCO is issued.","Also: Heating system certification: Original Township Heating System Certification form signed by a licensed contractor with raised seal; copies or faxes not accepted.","Also: Chimney certification: Level II chimney certification for wood-burning fireplaces or solid fuel stoves.","Also: Age Restricted Development form: Required if applicable, listed with the CCO application.","Also: Underground oil tank: Township FAQ says a tank in use and not leaking, or properly abandoned in place with permits, may stay; removal is a buyer/seller negotiation."]$j$::jsonb, $j$[{"label":"Initial CCO inspection, per unit (new fees from November 1, 2024, Ordinance 2024-16)","amount":"$165"},{"label":"1st re-inspection","amount":"$35"},{"label":"2nd re-inspection","amount":"$50"},{"label":"3rd re-inspection","amount":"$75"},{"label":"4th and each later re-inspection","amount":"$100"},{"label":"\"No Occupancy\" letter for an as-is purchase (application and inspection fee must be paid first)","amount":"$165.00"}]$j$::jsonb, $t$https://www.florence-nj.gov/wp-content/uploads/Housing-Inspection-Application-Form-7-2-25.pdf$t$, $t$https://florence-nj.gov/departments/housing/housing-application/$t$, $j$[{"url":"https://web.archive.org/web/20260911211838/https://florence-nj.gov/departments/housing/","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20260511030111/https://florence-nj.gov/departments/housing/housing-faqs/","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20260606135559/https://florence-nj.gov/departments/housing/housing-application/","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20251110020217/http://www.florence-nj.gov/wp-content/uploads/Housing-Inspection-Application-Form-7-2-25.pdf","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$All residential units must be inspected by the Housing Department and a Continued Certificate of Occupancy issued PRIOR to a change in occupancy or a transfer of property$t$, $t$9c02ca54a3bd8c51ccc47236facbdb27db7023fe36448a0f9bba3f5f48b9da33$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0315.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0315.json$t$, true),
  ($t$0315$t$, $t$Florence Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Florence Township Housing Department / Construction Office (smoke, CO and extinguisher checked on the CCO housing inspection) (town fire bureau)","Contact: Michael Perna, Housing Inspector · 609-499-2130 ext. 124 · housing@florence-nj.gov","Apply: Same as the CCO: allow at least 2 weeks, up to 4 weeks in busy times.","How to apply: No separate application found. The smoke alarm, CO alarm and extinguisher check is part of the Housing Inspection Application for the CCO, submitted with the fee to the Housing Department at 711 Broad Street.","Fire official in the NJ state directory (fire district), updated 3/5/2026: Brian Richardson · (609) 499-1393 · brichardson@ftfd40.org","Smoke alarms on every level (including habitable attic and basement) and outside each sleeping area; alarms must be replaced after 10 years","Battery smoke alarms must be 10-year sealed, single station, listed to UL 217; hard-wired alarms from original construction may not be swapped for battery units","Carbon monoxide alarm (UL 2034) in the immediate vicinity of the bedrooms when the home has fuel-burning appliances or an attached garage","Portable fire extinguisher still required by Township Code 116-4.B(1)(d) on the July 2025 form: at least 2A:10B:C, residential rated, 10 lb or less","Extinguisher mounted with the maker's bracket, within 10 feet of the kitchen, top no more than 5 feet above the floor, visible, near an exit path","Extinguisher serviced and tagged by a certified contractor within 12 months, or a receipt for a newly bought unit; owner's manual present; do not remove the tamper seal","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"No separate fire certificate fee published; smoke, CO and extinguisher are items 1 to 3 of the CCO housing inspection, which costs this per unit","amount":"$165"}]$j$::jsonb, $t$https://www.florence-nj.gov/wp-content/uploads/Housing-Inspection-Application-Form-7-2-25.pdf$t$, $t$https://florence-nj.gov/departments/housing/$t$, $j$[{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://web.archive.org/web/20251110020217/http://www.florence-nj.gov/wp-content/uploads/Housing-Inspection-Application-Form-7-2-25.pdf","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20260911211838/https://florence-nj.gov/departments/housing/","label":"Official source (web.archive.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://web.archive.org/web/20231130075912/https://ftfd40.org/fire-prevention/","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$SMOKE DETECTOR COMPLIANCE Name: Florence Twp Constr Dept Addr: 711 Broad Street Florence NJ 08518 Phone (609) 499-2130$t$, $t$b4ebd9e05832055d20aeab39ef9a05498676cd0398f7c5ff8846508a03f26c9f$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0315.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0315.json$t$, true),
  ($t$0319$t$, $t$Maple Shade Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Occupancy (Certificate of Inspection / Certificate of Continued Occupancy), Housing Code Chapter 155$t$, $j$["Issued by: Maple Shade Township Housing Inspection (Land Use / Community Development; Housing Inspector or Code Enforcement Officer)","Contact: Kyle Wagner, Director of Community Development (Zoning Officer / Planning Administration) · 856-779-9610 ext. 151 · zoning@mapleshade.com","Apply: No lead time published. Violations found at the first inspection must be fixed and re-inspected within 90 days (extendable once to 120 days if asked before day 90), or a new application and fee are needed.","How to apply: Fill out the Application for Residential Certificate of Occupancy (property, block and lot, seller, buyer, agent, rooms per floor, access contact), signed by owner and buyer, and submit it with the $125.00 fee by cash or check to Maple Shade Township Housing Inspection, 200 Stiles Avenue, Maple Shade, NJ 08052 (fax 856-779-2524, email Zoning@MapleShade.com). For an as-is sale where the buyer will not move in until repairs are done, use the Transfer of Title application instead ($75, one battery smoke detector per level); the buyer must then apply for the full CO within 120 days.","Valid for: Valid until the next sale, transfer or change of occupancy; not transferable to a new owner except between spouses or family members.","House numbers visible from the street, 4 inches high, contrasting color","Sidewalks, driveways and curbs without raised cracks over 1/2 inch or damage","Roof sound; signs of leaks need a licensed roofer's certification","Gutters and downspouts draining away from the building; front and rear exterior lights","Handrail on front steps with more than 3 risers; guardrails on decks and porches over 30 inches with balusters under 4 inches apart","Peeling paint scraped and painted; rotted wood, loose siding and broken glass repaired; screens on all windows","Yard cut and cleared; trash and recycling cans stored out of view from the street","10-year sealed battery smoke detector on every level and in every bedroom, none more than 10 years old; CO detectors within 10 feet of all sleeping areas","2A:10B:C fire extinguisher mounted in the kitchen area per NJ fire code","Graspable handrails on all stairs including basement; guards on open sides","Outlets, switches and fixtures working with covers; GFCI at kitchen counters, within 6 feet of sinks, bathrooms and washer","Windows open, close, lock and stay up; exterior door locks not keyed from inside; no infestation","Fireplaces and chimneys certified by a licensed contractor; termite damage needs an exterminator's certificate","Basement: water heater relief pipe within 6 inches of floor, emergency heater switch, sump pump to the outside (not the sewer), 60 amp minimum service with labeled breakers, hard-piped dryer vent, abandoned oil tanks removed with a permit","Stove anti-tip device; bedrooms need proper egress, and no basement bedrooms without egress; work done without permits must be permitted","Also: Work done without permits: Permits are needed for new wiring, plumbing, electrical service or panel, heater, A/C, water heater and similar work. A buyer of a home with unpermitted improvements takes on getting and closing those permits.","Also: As-is (rehab / fixer upper) sales: The home must stay vacant until permits and CO approvals are done. A Certificate for Transfer of Property Title ($75, valid 120 days) allows the closing; the full CO application must be filed before it expires."]$j$::jsonb, $j$[{"label":"Residential CO, initial inspection and first re-inspection","amount":"$125"},{"label":"Each later re-inspection","amount":"$65"},{"label":"Residential CO application fee on the form (cash or check)","amount":"$125.00"},{"label":"As-is sale where no one will move in: Certificate for Transfer of Property Title (smoke detector inspection only; valid 120 days)","amount":"$75"}]$j$::jsonb, $t$https://mapleshade.com/wp-content/uploads/2026/01/Residential-CO-Form.pdf$t$, $t$https://mapleshade.com/certificate-of-occupancy/$t$, $j$[{"url":"https://mapleshade.com/certificate-of-occupancy/","label":"Official source (mapleshade.com)"},{"url":"https://mapleshade.com/wp-content/uploads/2025/12/ORDINANCE-2025-18.pdf","label":"Official source (mapleshade.com)"},{"url":"https://mapleshade.com/wp-content/uploads/2026/01/Residential-CO-Form.pdf","label":"Official source (mapleshade.com)"},{"url":"https://mapleshade.com/wp-content/uploads/2026/03/Maple-Shade-Township-Housing-Inspection-Checklist.pdf","label":"Official source (mapleshade.com)"}]$j$::jsonb, $t$Effective immediately, properties within the Township of Maple Shade are required to obtain a Certificate of Occupancy Inspection & Approvals prior to: The Sale of a Property whether Residential or Commercial.$t$, $t$6a67ac571d49fd5e7231456bafd9ac4835f8103c260d08b149a4d98ee08a9941$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":13,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0319.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0319.json$t$, true),
  ($t$0319$t$, $t$Maple Shade Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Maple Shade Township Fire Official / Housing Inspection (the Resale Smoke Alarm Application was replaced by the Residential CO Form) (town fire bureau)","Contact: Matthew Orsini, Interim Fire Official · (856) 779-9610 ext. 179 · firemarshal@mapleshade.com","Apply: Not published.","How to apply: Use the Residential CO Form (it replaced the Resale Smoke Alarm Application) and submit it with the fee to Maple Shade Township Housing Inspection, 200 Stiles Avenue (Zoning@MapleShade.com). For an as-is sale with no occupancy, use the Transfer of Title form. Fire Official staff can answer fire safety questions.","Fire official in the NJ state directory (town), updated 9/10/2025: Matthew Orsini · (856) 779-9610 · firemarshal@mapleshade.com","Smoke detectors: 10-year sealed battery units, one on each level and one in each bedroom; no detector more than 10 years old (Township checklist, March 2026)","Carbon monoxide detectors within 10 feet of all sleeping areas","Fire extinguisher still listed on the March 2026 Township checklist: 2A:10B:C, mounted per NJ fire code in the kitchen area","For an as-is Transfer of Title sale (no one moving in): at least one battery smoke detector on each level, inspected before the transfer certificate is issued","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"No separate smoke certificate fee; the resale smoke/CO check is now part of the Residential CO application","amount":"$125.00"},{"label":"As-is Transfer of Title (vacant sale) with smoke detector inspection","amount":"$75.00"}]$j$::jsonb, $t$https://mapleshade.com/wp-content/uploads/2026/01/Residential-CO-Form.pdf$t$, $t$https://mapleshade.com/new-fire-official/$t$, $j$[{"url":"https://mapleshade.com/new-fire-official/","label":"Official source (mapleshade.com)"},{"url":"https://mapleshade.com/land-use-community-development/","label":"Official source (mapleshade.com)"},{"url":"https://mapleshade.com/wp-content/uploads/2026/03/Transfer-of-Title-Form.pdf","label":"Official source (mapleshade.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://mapleshade.com/wp-content/uploads/2026/01/Residential-CO-Form.pdf","label":"Official source (mapleshade.com)"}]$j$::jsonb, $t$The “Resale Smoke Alarm Application” has been replaced with the “Residential CO Form”.$t$, $t$15fa0d0bbffbbf4272448024d20395441ef436b40277340b9d8b77dfec707077$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":13,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0319.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0319.json$t$, true),
  ($t$0320$t$, $t$Medford Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Occupancy for closing$t$, $j$["Issued by: Medford Township Fire & EMS Department","Contact: Brian Widmann, Fire Marshall · (609) 953-3291 · bwidmann@medfordfire.org","Apply: Apply more than 10 business days before the change of occupant for the lowest fee.","How to apply: The Township's closing requirements say to contact the Fire Department for the residential Certificate of Occupancy. Apply online with the Fire Department's Smoke Detector Inspection Application (see the fire certificate). If the home has public water or sewer, also call Utility Billing for a final meter reading and sewer inspection.","Working smoke alarm on every level including the basement (not attic or crawl space) and within 10 feet of sleeping areas","Original hard-wired or interconnected alarm systems must be kept working; they cannot be swapped for stand-alone battery detectors","Carbon monoxide alarm near the sleeping areas, with more if bedrooms are on more than one level","Leave alarm instruction manuals for the next owner","House number clearly visible from the road (Township Code 51-3)","Also: Final water meter reading and sewer inspection: For homes on public water and/or sewer, contact the Township Utility Billing office for final meter readings and sewer inspections before closing.","Also: Wells and septic systems: Handled by the Burlington County Health Department, 15 Pioneer Boulevard, Westampton, 609-265-5515."]$j$::jsonb, $j$[{"label":"Same single Fire Department inspection as the fire certificate (not an extra fee): request received more than 10 business days before the change of occupant","amount":"$50"}]$j$::jsonb, $t$https://hipaa.jotform.com/221363427572152$t$, $t$https://medfordtownship.com/construction/$t$, $j$[{"url":"https://medfordtownship.com/construction/","label":"Official source (medfordtownship.com)"},{"url":"https://hipaa.jotform.com/221363427572152","label":"Official source (hipaa.jotform.com)"}]$j$::jsonb, $t$To obtain a Certificate of Occupancy please contact the Fire Department . For those units with public water and/or sewer, please contact the Utility Billing office for final meter readings and sewer inspections.$t$, $t$19848fb40f5d99d46230e80c65ee9361159b74c2476e874da24f794db81d3c86$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":10,"q_ok":5,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0320.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0320.json$t$, true),
  ($t$0320$t$, $t$Medford Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Medford Township Fire & EMS Department (Fire Marshal / fire inspections) (town fire bureau)","Contact: Brian Widmann, Fire Marshall · (609) 953-3291 · bwidmann@medfordfire.org","Apply: Apply more than 10 business days before the change of occupant for the lowest fee.","How to apply: Fill out the online Smoke Detector Inspection Application linked from medfordfire.org (property address, settlement date, time until settlement, owner, phone to set up the inspection, email for the certificate) and check each compliance box; all boxes must be checked before an inspection is scheduled. The form says to add the fee amount to the MuniPay form when paying by credit card. The certificate is emailed. Inspection line (609) 953-3291.","Fire official in the NJ state directory (town), updated 7/30/2026: Brian D Widmann · (609) 953-3291 · bwidmann@medfordfire.org","Smoke alarm on each level including basements (not attic or crawl space), and smoke and CO alarms outside each sleeping area within 10 feet of bedrooms","Homes built before 1977: 10-year sealed battery smoke alarms; later homes: AC hard-wired alarms by year built, interconnected where required, and kept in working order","Homes with a monitored NFPA 72 system instead of AC alarms need a certificate of compliance from a certified alarm contractor or electrician; the Fire Department cannot test these systems","CO alarm in the common hall outside of, and within 10 feet of, the bedroom doors; battery or plug-in is acceptable","House number visible from the public road, contrasting and bright or reflective (Township Code 51-3)","The Medford online form (titled 2022) does not list a fire extinguisher","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received more than 10 business days before the change of occupant","amount":"$50"},{"label":"Request received 5 to 9 business days before the change of occupant","amount":"$90"},{"label":"Request received 4 or fewer business days before the change of occupant","amount":"$161"},{"label":"Second re-inspection or later, each (first re-inspection is free)","amount":"$35"}]$j$::jsonb, $t$https://hipaa.jotform.com/221363427572152$t$, $t$https://medfordtownship.com/fire-ems-department/$t$, $j$[{"url":"https://www.medfordfire.org/","label":"Official source (medfordfire.org)"},{"url":"https://hipaa.jotform.com/221363427572152","label":"Official source (hipaa.jotform.com)"},{"url":"https://medfordtownship.com/fire-ems-department/","label":"Official source (medfordtownship.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Smoke Detector Inspection Application$t$, $t$a41cc99e4ac31b421226055c787d34a40052a3a243a0993f35f115af429a6f16$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":10,"q_ok":5,"q_bad":0,"q_unchecked":5},"source":"property/data/municipal-requirements/checked/0320.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0320.json$t$, true),
  ($t$0321$t$, $t$Medford Lakes Borough$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Borough of Medford Lakes Office of Construction","Contact: Tom Boyd, Construction Official · 609-654-8898, ext. 128 · construction@medfordlakes.com","Apply: Inspections are scheduled based on availability. The related fire and extraneous flow applications cost least when filed more than 10 business days before settlement.","How to apply: The Borough says a simple application is completed when applying for a residential CCO when selling or renting a home; no separate CCO form is posted, so contact the Office of Construction, 1 Cabin Circle, 609-654-8898 ext. 128, construction@medfordlakes.com. File the Fire Inspection Application and the Application for Certificate of Extraneous Flow Elimination Compliance (Wastewater Department, 14 Stokes Road, 609-654-2013, office hours Monday to Friday 7 a.m. to 2:30 p.m.) with their fees; each inspector contacts the applicant once the paid application is received.","Smoke alarm, CO alarm and fire extinguisher inspection done together with the CCO inspection (see the fire certificate)","Separate extraneous flow inspection by the Wastewater Department: sump pumps, roof drains and floor drains must not be connected to the Borough wastewater system","Also: Extraneous flow elimination certificate (sump pump, roof and floor drains): Wastewater Department inspection needed at change of occupancy to confirm sump pumps, roof drains and floor drains are not tied into the Borough wastewater system. Same fee tiers as the fire certificate; $35 re-inspection. Wastewater Department, 14 Stokes Road, 609-654-2013."]$j$::jsonb, $j$[{"label":"Extraneous flow (sump pump / roof / floor drain) inspection, Wastewater Department, more than 10 business days before settlement (no separate CCO fee was found)","amount":"$50"},{"label":"Extraneous flow inspection, 4 to 10 business days before settlement","amount":"$70"},{"label":"Extraneous flow inspection, less than 4 business days before settlement","amount":"$125"},{"label":"Extraneous flow re-inspection","amount":"$35"}]$j$::jsonb, null, $t$https://www.medfordlakes.com/157/Rentals-Change-of-Occupancy$t$, $j$[{"url":"https://www.medfordlakes.com/157/Rentals-Change-of-Occupancy","label":"Official source (medfordlakes.com)"},{"url":"https://www.medfordlakes.com/149/Construction-Building","label":"Official source (medfordlakes.com)"},{"url":"https://www.medfordlakes.com/DocumentCenter/View/28/Extraneous-Flow-Application","label":"Official source (medfordlakes.com)"}]$j$::jsonb, $t$A residential Smoke Alarm/CO Alarm/Fire Extinguisher inspection is performed in conjunction with the CCO (Certificate of Continued Occupancy) inspection. A simple application can be completed when applying for a residential CCO when selling or renting a home.$t$, $t$ec3cfda8311635ed3efd5b5427edcf075b8192146d841624d70552f102340f9c$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":11,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0321.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0321.json$t$, true),
  ($t$0321$t$, $t$Medford Lakes Borough$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Medford Lakes Fire Department, Bureau of Fire Prevention (LEA #03321) (town fire bureau)","Contact: Vincent Knott, Fire Official (per the Borough's October 2024 application form) · (856) 316-8584 · vincent.knott@mlfd371.org","Apply: Submit to the Borough Office more than 10 business days before settlement to avoid higher fees. The Fire Official contacts the applicant once the paid application is received. The October 2024 form says certificates are valid for 90 days; the Borough web page says six months.","How to apply: Fill out the Application for Certificate of Smoke Alarm, Carbon Monoxide Alarm and Portable Fire Extinguisher Compliance (address, block and lot, owner, occupant, sales agent and firm, settlement date) and submit it with the fee, payable to the Borough of Medford Lakes, to the Borough Office at 1 Cabin Circle. The form records cash or check; the web page says cash or money order. The Fire Official then calls to schedule.","Fire official in the NJ state directory (town), updated 5/18/2026: Craig Farnsworth II · (609) 654-8898 · craig.farnsworth@mlfd371.org","House numbers: numerals at least 4 inches high, contrasting color, permanently fixed to the house and visible from the street; light post or mailbox numbers are not accepted","Smoke alarm on every level; basement alarm at the bottom of the stairwell at ceiling level (not between joists); hallway alarm within 10 feet of all bedroom doors","Smoke alarm on the ceiling of every bedroom in homes built 1991 to present","Hard-wired smoke alarms cannot be replaced with battery alarms; all smoke alarms under 10 years old and working; battery alarms must be the 10-year battery type","CO alarm in the hallway within 10 feet of all bedrooms, under 10 years old, installed per the maker; plug-in, battery or hard-wired accepted, but not in switched outlets or against floor molding","Fire extinguisher still on the October 2024 form: minimum 2A-10B:C, under 10 pounds, mounted on its bracket within 10 feet of the kitchen in the exit path, visible and reachable","Homes with a low voltage fire alarm system must have it tested and approved by the alarm company before the inspection and show the alarm certification at the inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days before settlement","amount":"$50"},{"label":"4 to 10 business days before settlement","amount":"$70"},{"label":"Less than 4 business days before settlement","amount":"$125"},{"label":"Re-inspection","amount":"$35"}]$j$::jsonb, $t$https://www.medfordlakes.com/DocumentCenter/View/119/Fire-Inspection-Application-PDF$t$, $t$https://www.medfordlakes.com/157/Rentals-Change-of-Occupancy$t$, $j$[{"url":"https://www.medfordlakes.com/157/Rentals-Change-of-Occupancy","label":"Official source (medfordlakes.com)"},{"url":"https://www.medfordlakes.com/DocumentCenter/View/119/Fire-Inspection-Application-PDF","label":"Official source (medfordlakes.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The cost of the Smoke Detector/CO Detector Compliance Certificate is $50 if scheduled 10 days prior to change of occupancy, $70 if scheduled 4 to 10 days prior to change or $125 if scheduled less than 4 days prior.$t$, $t$8b552c03b4e88972efaf88c7cb0cca1565b92438261aa2a761cc313a4327dae3$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":8,"fee_ok":8,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":11,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0321.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0321.json$t$, true),
  ($t$0322$t$, $t$Moorestown Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate for Change in Occupancy/Ownership (Township page calls it Certificate of Continuing Occupancy)$t$, $j$["Issued by: Moorestown Township Department of Public Works (inspection); Director of Community Development reviews surveys","Contact: Don Lloyd, Director, Public Works · 856-235-3520, option 2 · dlloyd@moorestown.nj.us","Apply: Get it before the real estate closing; the seller schedules the inspection with Public Works.","How to apply: Call Public Works at 856-235-3520, option 2, to schedule the inspection. The fee is noted on the tax search and collected at closing. If the property is on the Township's list of properties adjoining Township land, give a survey (no more than 90 days old) to the Department of Community Development.","Valid for: 60 days from issue; if closing does not happen within 60 days a new certificate is needed","No sump pumps, roof drains or other drainage connected to the sanitary sewer (must be permanently disconnected)","Water meter working and reading accurately; the Township replaces a bad meter, but any plumbing changes needed are at the owner's cost by a licensed plumber","Sidewalks free of trip hazards or other hazards; owner repairs or replaces as directed","No open construction permits; all improvements inspected and passed so permits can be closed","No encroachment on Township-owned land","If the property adjoins Township-owned property: a survey no more than 90 days old, with corner flags left in place until closing","Also: Open permits must be closed before settlement: 'Property cannot settle until all open permits are closed.' Construction Office: (856) 235-0914, Ext. 3018 or 3069 (per the selling sheet); the Construction Office page lists 856-235-0912, ext. 3018.","Also: Final water meter reading: Call Public Works 856-235-3520, option 2. Final figures are available after 2 p.m. the day before settlement at (856) 235-0912 ext. 3008, 3009, 3010.","Also: Survey for properties adjoining Township land: Needed to settle if the property adjoins Township-owned land; survey dated no more than 90 days before, flags left in place until closing.","Also: Buyer water/sewer account: Buyers contact Tax / Water & Sewer Billing (856) 235-0912 ext. 3008, 3009, 3010 with name, address, settlement date and mailing address."]$j$::jsonb, $j$[{"label":"Inspection, all residential and commercial properties (noted on tax search, collected at closing)","amount":"$75.00"},{"label":"Inspection, second floor condominium (noted on tax search, collected at closing)","amount":"$50.00"}]$j$::jsonb, null, $t$https://www.moorestown.nj.us/641/Certificate-of-Continuing-Occupancy$t$, $j$[{"url":"https://www.moorestown.nj.us/DocumentCenter/View/6678/05-2022","label":"Official source (moorestown.nj.us)"},{"url":"https://www.moorestown.nj.us/641/Certificate-of-Continuing-Occupancy","label":"Official source (moorestown.nj.us)"},{"url":"https://www.moorestown.nj.us/DocumentCenter/View/6604/Buying_-Selling_Renting-_Change-of-Mailing-Address","label":"Official source (moorestown.nj.us)"},{"url":"https://www.moorestown.nj.us/162/Water-Sewer","label":"Official source (moorestown.nj.us)"}]$j$::jsonb, $t$The Township of Moorestown requires the Seller of any property in the Township to obtain a Certificate for Change in Occupancy/Ownership prior to the real estate closing$t$, $t$98cc05ab00c48ca3f12367f01424d13a324903df3c0ede5bbed4f623e638dc2d$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":29,"q_ok":27,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0322.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0322.json$t$, true),
  ($t$0322$t$, $t$Moorestown Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Fire District No. 1: issued by Moorestown Fire District No. 1 (Moorestown Fire Department), served by Moorestown Fire Prevention (Bureau of Fire Prevention) (fire district). Covers: Fire District 1 part of the township (the Township says to find your district on the NJ Division of Elections 'Find Your Polling Location' page, 'Fire' row)","Fire District No. 1 contact: Matthew Orsini, Fire Official (Moorestown Fire Prevention, shared by both districts) · (856) 234-1222 · info@fireprevention31.org","Fire District No. 1, apply: Certificates are only good for 30 days, so requests for inspections more than 30 days before settlement/move-in are denied. Apply more than 10 business days before the change of occupant for the lowest fee.","Fire District No. 1, how to apply: Apply online with the Moorestown Fire Prevention Jotform application (linked from the Township's Certificate of Continuing Occupancy page). Upload a copy of the contract of sale or lease. Pick a requested inspection date; inspections are Tuesdays and Thursdays, 9 to 11 AM, excluding holidays. The bureau emails a confirmation with the fee and who to make the check payable to. Pay by check or money order to the inspector at the inspection; not paying on arrival is an automatic failure. If you need an inspection within 24 hours, call the office after submitting.","Fire District No. 2: issued by Moorestown Fire District No. 2 (Lenola Fire Company), served by Moorestown Fire Prevention (Bureau of Fire Prevention) (fire district). Covers: Fire District 2, the western portion of the township (Lenola area); confirm with the polling-location lookup","Fire District No. 2 contact: Matthew Orsini, Fire Official (Moorestown Fire Prevention, shared by both districts) · (856) 234-1222 · info@fireprevention31.org","Fire District No. 2, apply: Certificates are only good for 30 days, so requests for inspections more than 30 days before settlement/move-in are denied. Apply more than 10 business days before the change of occupant for the lowest fee.","Fire District No. 2, how to apply: Apply online with the Moorestown Fire Prevention Jotform application (linked from the Township's Certificate of Continuing Occupancy page). Upload a copy of the contract of sale or lease. Pick a requested inspection date; inspections are Tuesdays and Thursdays, 9 to 11 AM, excluding holidays. The bureau emails a confirmation with the fee and who to make the check payable to. Pay by check or money order to the inspector at the inspection; not paying on arrival is an automatic failure. If you need an inspection within 24 hours, call the office after submitting.","Fire official in the NJ state directory (fire district), updated 5/18/2026: Matthew M Orsini · (856) 234-6660 · fireofficial313@gmail.com","All smoke detectors must be within 10 years of the manufacture date","All CO detectors must be within 7 years of the manufacture date","CO detector within 10 feet outside all sleeping areas if the home has a fuel-burning appliance, fireplace or garage (CO detectors only in bedrooms fail)","Pre-1975 homes: 10-year sealed battery smoke detector on each level, within 10 feet of each bedroom, including basement","AC smoke detectors must be interconnected; smoke detector at the bottom of basement stairs and top of walk-up attic stairs","Hardwired low-voltage fire alarm system must be tested and approved by a NJ licensed fire alarm contractor before the inspection; show or upload the certification","Smoke detector circuit located and labeled at the panel before the inspector arrives; panel circuits properly labeled","Homes with a generator, solar panels or battery storage need a permanent (not handwritten) 'CAUTION: MULTIPLE SOURCES OF POWER' type label within 18 inches of the main panel and the electric meter","House numbers permanently affixed, Arabic numerals about 3 inches high and 1 inch wide, contrasting background, visible from the street, not on a door","Upload a copy of the contract of sale or lease with the application","The Construction Office is notified of each application to check for open permits or violations","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Fire District No. 1: Smoke/CO certificate, request received more than 10 business days before change of occupant","amount":"$45.00"},{"label":"Fire District No. 1: Smoke/CO certificate, request received 4 to 10 business days before change of occupant","amount":"$90.00"},{"label":"Fire District No. 1: Smoke/CO certificate, request received fewer than 4 days before change of occupant","amount":"$161.00"},{"label":"Fire District No. 1: Second or later reinspection","amount":"$45.00"},{"label":"Fire District No. 2: Smoke/CO certificate, request received more than 10 business days before change of occupant","amount":"$45.00"},{"label":"Fire District No. 2: Smoke/CO certificate, request received 4 to 10 business days before change of occupant","amount":"$90.00"},{"label":"Fire District No. 2: Smoke/CO certificate, request received fewer than 4 days before change of occupant","amount":"$161.00"},{"label":"Fire District No. 2: Second or later reinspection","amount":"$45.00"}]$j$::jsonb, $t$https://form.jotform.com/fireofficial313/smokeinspection$t$, $t$https://www.moorestown.nj.us/641/Certificate-of-Continuing-Occupancy$t$, $j$[{"url":"https://www.moorestown.nj.us/696/Fire-Department","label":"Official source (moorestown.nj.us)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.moorestown.nj.us/641/Certificate-of-Continuing-Occupancy","label":"Official source (moorestown.nj.us)"},{"url":"https://form.jotform.com/fireofficial313/smokeinspection","label":"Official source (form.jotform.com)"},{"url":"https://web.archive.org/web/20260610022031/https://bureauoffireprevention.com/contact","label":"Official source (web.archive.org)"},{"url":"https://web.archive.org/web/20260411081752/https://www.bureauoffireprevention.com/_files/ugd/42b6a6_44bdd1b5d1164a1a8102b8dd30d9ef6f.pdf?index=true","label":"Official source (web.archive.org)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.moorestownfire2.com/","label":"Official source (moorestownfire2.com)"}]$j$::jsonb, $t$Moorestown Township is home to two volunteer fire districts.$t$, $t$19b38f991af9a2714867ac5a7366ca9465667fff0dd5ebdb9237819ef2a22044$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":29,"q_ok":27,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0322.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0322.json$t$, true),
  ($t$0323$t$, $t$Mount Holly Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Inspection (Housing Office resale certification)$t$, $j$["Issued by: Mount Holly Township Code Enforcement and Housing Department (Housing Office)","Contact: Carolyn Youngbean, Housing · 609-864-1203 or 609-864-2464 · cyoungbean@twp.mountholly.nj.us","How to apply: Fill out the Resale Inspection Application (all fields required, including settlement date, heater certification date and fire certification date) and submit it to the Township Housing Office, 17 Pine Street, Mount Holly, NJ 08060. The form lists payment by check, money order, cash or credit card. Call 609-864-1203 or 609-864-2464 with questions.","Heating system certification by an HVAC-R contractor or master plumber (form expires 1 year after the inspection date); the application asks for its date","Fire (smoke/CO) certification date is asked on the application","At least one working 10-year sealed battery smoke detector on each level including the basement; CO detectors within 10 feet of sleeping areas","Handrails on stairs with 4 or more risers; guard rails on porches/decks 30 inches or more above grade","GFCI within 6 feet of water sources; circuit breaker panel in order; no bare-wire fixtures","Ceilings, walls and floors with no holes, chipped paint, severe cracks or water stains; no ripped or old carpet","Interior doors sound, fit the frame and close properly; no keyed locks or deadbolts on interior doors","Heat working; appliances working with anti-tip bracket on the range","Hot and cold water; toilets flush","Bathroom has a window or exhaust fan","Utilities on at the time of inspection","Yard free of trash, debris and motor vehicles; all code violations fixed","Roof, chimney, siding, gutters and downspouts intact; windows and screens work","Driveway, sidewalks and aprons in safe condition; no trip hazards","No work done without permits","Also: Heating system certification: A licensed HVAC-R contractor or master plumber must fill out the Township Heating System Certification; it expires one year from the inspection date.","Also: Trash and recycling escrow: The Housing Office verifies trash compliance and recycling carts at closing; the 2016 fee sheet lists a $250.00 trash escrow and $100.00 recycling cart escrow.","Also: Work without permits: The inspection checklist includes 'Work without Permits'. Construction Office: inspections@twp.mountholly.nj.us."]$j$::jsonb, $j$[{"label":"Resale inspection (fee sheet effective May 5, 2016)","amount":"$150.00"},{"label":"3rd or more inspection, per unit (2016 fee sheet)","amount":"$30.00/unit"},{"label":"Trash escrow (2016 fee sheet)","amount":"$250.00"},{"label":"Recycling cart escrow (2016 fee sheet)","amount":"$100.00"}]$j$::jsonb, $t$https://storage.googleapis.com/juniper-media-library/560/2026/05/RESALE_INSPECTION_APPLICATION_2026.pdf$t$, $t$https://twp.mountholly.nj.us/departments/code-enforcement-housing-department$t$, $j$[{"url":"https://twp.mountholly.nj.us/departments/code-enforcement-housing-department","label":"Official source (twp.mountholly.nj.us)"},{"url":"https://storage.googleapis.com/juniper-media-library/560/2026/05/RESALE_INSPECTION_APPLICATION_2026.pdf","label":"Official source (storage.googleapis.com)"},{"url":"https://storage.googleapis.com/juniper-media-library/560/2026/05/Property_Inspections_List_2025_MH.pdf","label":"Official source (storage.googleapis.com)"},{"url":"https://storage.googleapis.com/juniper-media-library/560/2026/05/Fees_for_Housing_Inspections.pdf","label":"Official source (storage.googleapis.com)"}]$j$::jsonb, $t$Resale and Rental Inspections : Conducts mandatory health and safety property checks required for residential resales and tenancy turnovers.$t$, $t$332e3c611a71c792f3bf80134267f2e7544b42aa14c98c3689033a067db52fa2$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":14,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0323.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0323.json$t$, true),
  ($t$0323$t$, $t$Mount Holly Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Mount Holly Fire District No. 1, Bureau of Fire Prevention (fire district)","Contact: Thomas Mason, Jr., Fire Official / Fire Chief · (609) 864-2464 (Smoke Detector Certifications); Fire Official office (609) 518-8911 · tmason@mounthollyfire.org","Apply: Within 60 days of settlement, the seller contacts the Township Bureau of Housing and Code Enforcement to schedule the resale inspection.","How to apply: Call (609) 864-2451 or email the Township Bureau of Housing and Code Enforcement to schedule, giving the property address and settlement date (the district page lists kscelba@twp.mountholly.nj.us, which may be out of date; the district's current contact page lists Smoke Detector Certifications at (609) 864-2464). Pay the inspector with a certified check, money order or business check made payable to MOUNT HOLLY FIRE DISTRICT No.1. Cash and personal checks are not accepted. If the home is not accessible or fails, reschedule and pay again.","Fire official in the NJ state directory (fire district), updated 6/18/2025: Thomas Mason, Jr · (609) 261-7233 · Tmason@mounthollyfire.org","Smoke and CO detectors must be 10-year sealed battery (lithium) or hardwired, no more than 10 years old, and UL listed; at least one on each level including the basement","Hardwired smoke/CO detectors may not be replaced with battery units","Basement detector on the ceiling at the bottom of the basement stairs","CO alarm within 10 feet of every bedroom","Portable fire extinguisher: new within 12 months with receipt, or serviced by a NJ-certified extinguisher contractor; at least 2A-10:BC and not over 10 pounds; mounted on the manufacturer's bracket within 10 feet of the kitchen in the exit path; top no more than 5 feet and bottom at least 4.5 inches above the floor; not hidden in a cabinet or behind a door (per the district page last updated January 2024)","House numbers at least 4 inches high, contrasting color, permanently affixed, visible from the street","Monitored central alarm systems need an NFPA 72 inspection report from a NJ-licensed fire protection company at or before the inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Resale fire inspection, per dwelling unit","amount":"$85.00"},{"label":"Apartment house common area (in addition to $85.00 per apartment)","amount":"$85.00"},{"label":"Reinspection after noncompliance, per occurrence","amount":"$50"}]$j$::jsonb, null, $t$https://home.mounthollyfire.org/featured/covid-19-information-fire-inspections-annual-resale/$t$, $j$[{"url":"https://home.mounthollyfire.org/featured/covid-19-information-fire-inspections-annual-resale/","label":"Official source (home.mounthollyfire.org)"},{"url":"https://home.mounthollyfire.org/contact-directory/","label":"Official source (home.mounthollyfire.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Mount Holly Township, Bureau of Housing and Code Enforcement is currently scheduling residential resale inspections for the purpose of issuance of certification for resale.$t$, $t$faa9afa2c3318e0c96209044ccf0afa062a69e963f323faf71487a571dbc4473$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":14,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0323.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0323.json$t$, true),
  ($t$0324$t$, $t$Mount Laurel Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Mount Laurel Township Department of Community Development (Construction / Code)","Contact: Jennifer Parks, CCO questions and scheduling contact (named on the CCO application and checklist; no title given) · 856-234-0001 ext. 1227 · jparks@mountlaurel.com","Apply: Fees are tiered by how early you apply: 11 or more days before closing is the lowest fee. The application must be submitted with payment before the inspection is scheduled; the office calls you to set the time.","How to apply: Fill out the CCO application (Ordinance 2021-8 form) and mail it or drop it off with payment at Mount Laurel Township, Attn: Jennifer Parks, 750 Centerton Road, 2nd Floor, Mount Laurel, NJ 08054. Emailed applications are NOT accepted. Payment by cash, check or money order only. The office calls to schedule the inspection (Monday to Friday, 8:30 to 11:30 AM or 11:30 AM to 2:30 PM).","All permits closed before approval (decks, pools, sheds, water heaters, furnace/HVAC, finished basements, electrical, plumbing, structural work)","Electric, gas and water on; panels, furnace and water heater accessible; furnace and water heater working and properly vented","Yard free of debris, high grass and hazards; roof, chimney, siding, gutters in good condition","Sidewalks, stairs, patios, walkways and driveways free of trip hazards","House numbers visible from the street, at least 4 inches high","Windows work with no broken or missing glass; entry doors have a working lockset and deadbolt; no double-key deadbolts or slide bolts","Handrail on stairs with 4 or more risers; guards where a walking surface is more than 30 inches above grade","Plumbing works with no leaks; hot and cold water; water temperature not over 120F","Bathroom has a working window or exhaust fan vented outside","Range anti-tip device where required","GFCI protection within 6 feet of sinks and at laundry sinks, garage and exterior outlets; covers on outlets, switches, junction boxes; panel cover with no open breaker spaces","Garage-to-house door solid wood, solid-core, steel or 20-minute rated; garage door opener plugged directly into an outlet (no extension cords); garage attic access fire rated (permit required)","Dryer vented outside with 4-inch rigid or semi-rigid metal duct (no plastic or foil); washer drains to approved drain","Pool barriers maintained; gates self-closing and self-latching, latch at least 54 inches high, opening away from pool","Any other health or safety hazard found by the inspector must be fixed","Also: Open permits must be closed: All required permits must be obtained and closed before CCO approval. Construction Department 856-234-9686.","Also: Rental registration if the buyer will rent: If the property will be a rental, it must be registered with the Township within 14 days of the closing date (Code Chapter 121).","Also: Fire department smoke/CO certificate: Smoke certificate required from the Fire Department; schedule at mlfd.org."]$j$::jsonb, $j$[{"label":"Initial inspection, requested 11 or more days before closing","amount":"$75.00"},{"label":"Inspection requested 4 to 10 days before closing","amount":"$100"},{"label":"Inspection requested 3 days or less before closing","amount":"$125"},{"label":"Discount: low/moderate income deed-restricted home or primary owner aged 65+","amount":"fifty percent (50%)"},{"label":"Re-inspection (waived if within 30 days and all items fixed)","amount":"$25.00"}]$j$::jsonb, $t$https://www.mountlaurel.com/CCO%20APPLICATION%202nd%20floor.pdf?t=202603171035570$t$, $t$https://www.mountlaurel.com/department/community_development___construction/new_page.php$t$, $j$[{"url":"https://www.mountlaurel.com/Document%20Center/Department/Community%20Development%20Construction/Forms/Housing%20Inspection%20List%20final.pdf?t=202106251245530","label":"Official source (mountlaurel.com)"},{"url":"https://www.mountlaurel.com/CCO%20APPLICATION%202nd%20floor.pdf?t=202603171035570","label":"Official source (mountlaurel.com)"},{"url":"https://www.mountlaurel.com/Mount_Laurel_Municipal_CCO_Checklist.pdf?t=202606101127590","label":"Official source (mountlaurel.com)"},{"url":"https://www.mountlaurel.com/department/community_development___construction/new_page.php","label":"Official source (mountlaurel.com)"}]$j$::jsonb, $t$REQUIREMENTS FOR CERTIFICATE OF CONTINUED OCCUPANCY (C.C.O.) For Resale of ALL Residential Homes$t$, $t$05865513cf71df3dcdba9170cf174747ad8dafb74b1120ef04d1b6c88f572de8$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":17,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0324.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0324.json$t$, true),
  ($t$0324$t$, $t$Mount Laurel Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Mount Laurel Fire Department (Mount Laurel Fire District #1), Bureau of Fire Prevention (fire district)","Contact: Bill Glassman, Fire Marshal · (856) 234-6053 · wglassman@mlfd.org","Apply: Fee tiers are counted back from the inspection date: more than 10 days before the inspection date is the lowest fee. Inspections are each Wednesday, by appointment only; the appointment is made when the application and payment are made.","How to apply: Apply and pay online through the Mount Laurel Fire Department's Muniverse portal (linked from mlfd.org under Inspections / Forms, Residential Smoke Alarm Inspections), or in person at Fire Headquarters, 69 Elbo Lane, Mount Laurel (office hours Monday to Friday, 8 AM to 12 PM and 1 PM to 4 PM). Have the buyer's and seller's names, property address, settlement date and year built. Payment by exact change, check or charge. All fees are non-refundable; a missed time block or a failed inspection needs a new application and a new fee. Communication is by email.","Fire official in the NJ state directory (fire district), updated 3/5/2026: William J Glassman, Jr · (856) 234-6053 · wglassman@mlfd.org","All smoke alarms must be less than 10 years old (Mount Laurel Township Ordinance 2021-19, Chapter 81, Section 81-24); take each alarm down and check the date on the back; replace any with no date","Each level needs an AC (hardwired) alarm or a DC 10-year sealed battery alarm, based on year built; all AC alarms must be interconnected","Pre-1975 homes: 10-year sealed battery alarm on each level including basement","CO alarm outside of, but near, all sleeping areas if the home has a fuel-burning appliance, fireplace or garage (CO alarms only in bedrooms fail)","Hardwired low-voltage fire alarm systems (alarm company) must be tested by an alarm contractor before the inspection; bring the contractor's certification","Breaker for the smoke alarms must be found and labeled before the inspector arrives; owner or agent turns it on and off","Homes with a generator, solar panels or battery storage need a permanent (not handwritten) 'CAUTION: MULTIPLE SOURCES OF POWER' type label within 18 inches of the main panel and the electric meter","House numbers: Arabic numerals at least 3 inches high, securely mounted, contrasting color, at least 30 inches above ground, visible from the street","No recalled smoke or CO alarms","Everything must be done before the inspector arrives; inspectors cannot install or repair anything","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Smoke/CO inspection, applied more than 10 days before the inspection date","amount":"$65"},{"label":"Smoke/CO inspection, applied 4 to 10 days before the inspection date","amount":"$100"},{"label":"Smoke/CO inspection, less than 4 days before the inspection date (based on availability)","amount":"$140"},{"label":"Change of ownership or occupancy without the certificate (penalty)","amount":"$500"}]$j$::jsonb, $t$https://geo.muniverse.us/prod1/portal/portal.jsp?c=596835512&p=556560486&g=556589337$t$, $t$https://mlfd.org/residential-smoke-alarm-inspections/$t$, $j$[{"url":"https://geo.muniverse.us/prod1/portal/portal.jsp?c=596835512&p=556560486&g=556589337","label":"Official source (geo.muniverse.us)"},{"url":"https://web.archive.org/web/20250421181621/https://mlfd.org/faqs/","label":"Official source (web.archive.org)"},{"url":"https://mlfd.org/governance-responsibilities/","label":"Official source (mlfd.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Any change of ownership or occupancy (including the storage of personal property) may not occur, prior to a successful inspection AND possession of a Smoke Alarm and Carbon Monoxide Alarm Inspection (CSACMAI) Certification (passed inspection).$t$, $t$a316b60e8016cab70890bf239352f56886decb165db9ed337b03a1d9e7285baf$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":17,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0324.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0324.json$t$, true),
  ($t$0326$t$, $t$North Hanover Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per North Hanover Township. Confirm with the office if the buyer's lender or title company asks.","Contact: Robert Gancarz, Fire Official (Office of the Fire Marshal) · (609) 209-8345 · fireofficial@northhanovertwp.com","How to apply: No Township resale CO/housing inspection. The only resale inspection is the smoke and CO certificate from the Fire Official (see fire certificate).","Also: Rental only: landlord registration, insurance and lead-safe certificate: Rentals also need a Landlord Registration Form, proof of liability insurance, and a lead-safe certificate (lead inspection fee $200.00 + $20.00 through the Township). Not required for a sale to an owner-occupant."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://northhanovertwp.com/Fire%20Marshal/fire_marshal.html$t$, $j$[{"url":"https://northhanovertwp.com/Fire%20Marshal/Resale%20and%20Rental%20Requirements.pdf","label":"Official source (northhanovertwp.com)"}]$j$::jsonb, $t$RESALE REQUIREMENTS Only one inspection is required for a resale in North Hanover Township: Certification of Smoke & Carbon Monoxide Detectors$t$, $t$13162797884cd7a2044d432d04f9ad6e54c0e3c15376aa64dbcb095c9cbabf1a$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":10,"q_ok":4,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0326.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0326.json$t$, true),
  ($t$0326$t$, $t$North Hanover Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: North Hanover Township Office of the Fire Marshal (Fire Official) (town fire bureau)","Contact: Robert Gancarz, Fire Official / Fire Marshal · (609) 209-8345 · fireofficial@northhanovertwp.com","Apply: Apply more than 10 business days before the change of occupant for the lowest fee.","How to apply: Fill out the 'Application for Certificate of Smoke Detector, Carbon Monoxide and Fire Extinguisher Compliance' (in the Resale & Rental Requirements packet) and submit it with the fee to schedule. Checks payable to North Hanover Township (the packet summary says check or cash). Office of the Fire Marshal, 41 Schoolhouse Road, Wrightstown, NJ 08562. A failed inspection means a reinspection and an additional fee.","Fire official in the NJ state directory (town), updated 7/22/2026: Robert E Gancarz · (609) 758-2522 · Rgancarz@jacobstownfire.org","All detectors must be less than 10 years old","Smoke alarms on every level including the basement, and within 10 feet of sleeping room doors","Homes built before 1978: battery alarms must be 10-year sealed units or the inspection fails","Do not replace hardwired smoke alarms with battery alarms; replace bad interconnected alarms with compatible ones","Test all smoke detectors before the inspection date","CO alarm required if the home has any fuel-burning appliance or an attached garage: on each sleeping level, in hallways near bedrooms (electric or battery)","No fire extinguisher required (form says the State and the Township no longer require one)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received more than 10 business days before change of occupant","amount":"$35.00"},{"label":"Request received 4 to 10 business days before change of occupant","amount":"$70.00"},{"label":"Request received fewer than 4 business days before change of occupant","amount":"$125.00"}]$j$::jsonb, $t$https://northhanovertwp.com/Fire%20Marshal/Resale%20and%20Rental%20Requirements.pdf$t$, $t$https://northhanovertwp.com/Fire%20Marshal/fire_marshal.html$t$, $j$[{"url":"https://northhanovertwp.com/Fire%20Marshal/Resale%20and%20Rental%20Requirements.pdf","label":"Official source (northhanovertwp.com)"},{"url":"https://northhanovertwp.com/Fire%20Marshal/fire_marshal.html","label":"Official source (northhanovertwp.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Note: Fill out the application form and submit along with the $35.00 fee to schedule the Smoke & CO certification.$t$, $t$7abc66d7402e638a9b802236f0d18110489b895e03140b79f51cb3a5462854e7$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":0,"fee_bad":0,"fee_unchecked":3,"quotes":10,"q_ok":4,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/0326.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0326.json$t$, true),
  ($t$0327$t$, $t$Palmyra Borough$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (resale Housing Code inspection)$t$, $j$["Issued by: Borough of Palmyra Department of Housing (Housing Official)","Contact: Tracy Kilmer, Housing Official (also Fire Marshal) · 856-829-1096 · tkilmer@boroughofpalmyra.com","Apply: Fee must be paid before the inspection is scheduled. Allow 48 hours after the inspection for the report.","How to apply: Fill out the Resale Inspection Application for Certificate of Occupancy (one per unit) and turn it in at Borough Hall, 20 W. Broad Street, with the $125.00 fee payable to the Borough of Palmyra (check or cash). Then call (856) 829-1096 to schedule. Palmyra Harbour condominiums use a separate application.","Review of required permits along with the inspection","Interior: structural members, interior surfaces, lead-based paint, stairs, railings (including attic and basement), handrails and guards","Anti-tip bracket on the oven","Exterior: paint, street numbers (Arabic numerals at least 3 inches high), foundation, walls, roof, gutters and downspouts, chimneys, porches, decks and stairs (sidewalks not inspected)","Windows open and stay open; no broken glass; insect screens; deadbolt locks on doors; basement hatch and basement window guards","Yard: sanitation, grading and drainage, weeds under 6 inches, no rodent harborage, no unregistered or junk vehicles, firewood stored off the ground, fences in good condition","Plumbing fixtures, water heater, exhaust fan and drainage in working order","Heat, HVAC, washer and dryer, flue and combustion air; electrical hazards, GFCI outlets where required, covers and switch plates, no open junction boxes","Borough green trash carts; no rubbish, no infestation","Means of egress, locked doors, emergency escape","Smoke detectors on each level including basement and walk-up attic, outside each sleeping area within 10 feet, not in the kitchen; 10-year sealed lithium battery type","CO detectors within 10 feet of sleeping areas","One 2A:10BC fire extinguisher in the kitchen (not mounted), bought within a year with receipt or tagged (checklist dated January 2022)","Also: Flood risk disclosure: The Borough's 'Resale/Rental Additional Requirements' form: since March 20, 2024 sellers must give the buyer the flood risk information (Property Condition Disclosure Statement: Flood Risk Notice, N.J.S.A. 46:8-50) before the buyer is bound by the contract.","Also: Open permits: A review of required permits is done with the CO inspection."]$j$::jsonb, $j$[{"label":"Resale inspection for Certificate of Occupancy, per unit","amount":"$125.00"},{"label":"Per unit (separate application for each unit)","amount":"$125"},{"label":"Certificate of Occupancy inspection on home resale (Borough web page)","amount":"$125.00"}]$j$::jsonb, $t$https://boroughofpalmyra.com/Documents/Government/Forms/Resale-Inspection-App.pdf?t=202502101114010$t$, $t$https://boroughofpalmyra.com/government/rental_unit_certificate_of_occupancy.php$t$, $j$[{"url":"https://boroughofpalmyra.com/government/rental_unit_certificate_of_occupancy.php","label":"Official source (boroughofpalmyra.com)"},{"url":"https://boroughofpalmyra.com/departments/code_enforcement.php","label":"Official source (boroughofpalmyra.com)"},{"url":"https://boroughofpalmyra.com/Documents/Government/Forms/Resale-Inspection-App.pdf?t=202502101114010","label":"Official source (boroughofpalmyra.com)"},{"url":"https://boroughofpalmyra.com/Documents/Government/Forms/CO-Checklist-2022.pdf?t=202502101113570","label":"Official source (boroughofpalmyra.com)"}]$j$::jsonb, $t$Attention Homeowners: thinking of selling your home? Effective April 1, 2014, Certificate of Occupancy inspections (on existing home re-sales) are now required.$t$, $t$99b859d27b82e754535573a9e666a9dafc6b6a30920e4574982ffd5aa1accdfc$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":14,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0327.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0327.json$t$, true),
  ($t$0327$t$, $t$Palmyra Borough$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Palmyra Bureau of Fire Prevention (Borough Fire Marshal) (town fire bureau)","Contact: Tracy Kilmer, Fire Marshal (also Housing Official and Fire Sub Code Official) · (856) 829-1096 · tkilmer@boroughofpalmyra.com","How to apply: The Fire Marshal page sends resale smoke detector inspections to the housing (rental and resale) page. Apply through the Borough's resale Certificate of Occupancy process: application and fee to Borough Hall, then call (856) 829-1096 to schedule. No separate smoke certificate fee is published.","Fire official in the NJ state directory (town), updated 1/23/2023: Tracy L Kilmer · (856) 829-1096 · tkilmer@boroughofpalmyra.com","Smoke detectors over 10 years old will not pass","Resale/rental smoke alarms must be 10-year sealed battery single station units (hardwired systems must work; interconnected and hardwired detectors are checked against the maker's life span)","Smoke alarm on each level; smoke and CO detector outside each sleeping area; none in the kitchen","Third floor or attic with walk-up steps needs a smoke and CO detector, used or not","One ABC 2A:10B:C portable fire extinguisher in the kitchen, tagged by a fire service company within the year or with a receipt showing purchase within a year; need not be mounted (Fire Marshal page, undated; checklist January 2022)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://boroughofpalmyra.com/Documents/Government/Forms/Resale-Inspection-App.pdf?t=202502101114010$t$, $t$https://boroughofpalmyra.com/departments/fire_marshal.php$t$, $j$[{"url":"https://boroughofpalmyra.com/departments/fire_marshal.php","label":"Official source (boroughofpalmyra.com)"},{"url":"https://boroughofpalmyra.com/Documents/Government/Forms/NEW-JERSEY-STATE-FIRE-CODE-UPDATE.pdf?t=202502101114000","label":"Official source (boroughofpalmyra.com)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$SMOKE DETECTOR INSPECTIONS FOR RESALE OR CHANGE OF OCCUPANCY: Please Visit the housing page for rental and resale information.$t$, $t$b9646c189bd15686d7933c340002af129ded203fe4bbea46098ccf72ad2c6668$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":14,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0327.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0327.json$t$, true),
  ($t$0328$t$, $t$Pemberton Borough$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy Inspection (resale)$t$, $j$["Issued by: Borough of Pemberton Department of Inspections","Contact: 609-894-8222","How to apply: Download the Re-Sale Inspection Form (Certificate of Occupancy Inspection Application) from the Borough Forms page, fill in block, lot, location, owner and buyer, and submit it with the fee to the Department of Inspections, Borough Hall, 50 Egbert St., Pemberton, NJ 08068. The office-use box lists check, cash or credit card. Call the municipal offices at 609-894-8222 for scheduling."]$j$::jsonb, $j$[{"label":"Initial resale CO inspection (form created November 2024)","amount":"$100"},{"label":"Re-inspection (form created November 2024)","amount":"$75"}]$j$::jsonb, $t$https://www.pembertonborough.us/uploads/3/4/2/1/34215036/resale_inspection_application.docx$t$, $t$https://www.pembertonborough.us/forms.html$t$, $j$[{"url":"https://www.pembertonborough.us/forms.html","label":"Official source (pembertonborough.us)"},{"url":"https://www.pembertonborough.us/uploads/3/4/2/1/34215036/resale_inspection_application.docx","label":"Official source (pembertonborough.us)"}]$j$::jsonb, $t$Re-Sale Inspection Form$t$, $t$933d1bc7e774903f5de42d10a4133a34978ceba762bdcf6c58c0c5c045c9f27b$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":2,"fee_bad":0,"fee_unchecked":3,"quotes":9,"q_ok":6,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0328.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0328.json$t$, true),
  ($t$0328$t$, $t$Pemberton Borough$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (State is the fire code enforcing agency for Pemberton Borough) (NJ DCA, state)","Contact: Louis Kilmer, Deputy Division Director (listed as the state fire official for Pemberton Borough) · (609) 633-6132 · BFCE_CSDCMAC@dca.nj.gov","Apply: Apply more than 10 business days before the closing date for the lowest fee.","How to apply: Apply online through the NJ DCA Fire Safety portal (smoke certificate application). Pay by e-check or credit card before submitting. A valid email address is required; the certificate is emailed once the application is submitted, the fee is paid and any required inspections are done. All-electric homes with no CO requirement should email BFCE_CSDCMAC@dca.nj.gov.","Fire official in the NJ state directory (NJ DCA, state), updated 8/17/2026: Louis Kilmer · (609)633-6132","State certificate is now called the Certificate of Smoke Alarm, Carbon Monoxide Alarm, and Secondary Power Source Identification Label Compliance (CSACMASPSIL); homes with a generator, solar or battery storage need the power source label","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days before closing","amount":"$45"},{"label":"4 to 10 business days before closing","amount":"$90"},{"label":"Less than 4 business days before closing","amount":"$161"}]$j$::jsonb, $t$https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/$t$, $t$https://www.nj.gov/dca/dfs/offices/bfce.shtml$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$S Pemberton Borough$t$, $t$dbde6a2ce26556478d82b001d7a82a0344403c098cc9437d472ae14c246d3621$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":2,"fee_bad":0,"fee_unchecked":3,"quotes":9,"q_ok":6,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0328.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0328.json$t$, true),
  ($t$0329$t$, $t$Pemberton Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy Transfer (Resale Application / housing inspection)$t$, $j$["Issued by: Pemberton Township Code Enforcement Division (Housing Code Official), Department of Community Development","Contact: Wendy Jones or Michael Knoblock · 609-894-3376 · wjones@pemberton-twp.com","How to apply: Download the Resale Application (dated 04.29.26) from the Code Enforcement/Housing Forms page. Fill it out completely and submit it with the $150 fee to the Housing Code Official's office in the Municipal Building, 500 Pemberton-Browns Mills Road (the checklist says payment goes to the cashier's office). Inspectors in the field do not accept applications or fees, and nothing is scheduled until the application is complete and paid. If the buyer is taking responsibility for the certificate, notify the office in writing before it is issued.","Valid for: The application expires 60 days after it is filed and cannot be transferred. How long the certificate itself is valid is not stated.","House number on the dwelling, reflective, at least 3.5 inches high and readable from the street","Fences and pool areas with self-latching, outward-swinging gates (fence at least 48 inches, latch at least 54 inches)","Landings and porches 30 inches or higher need a guard rail at least 36 inches high with openings no wider than 4 inches","Stairways, decks, porches and balconies structurally sound; handrail on any stair with 4 or more risers","No broken or missing glass; windows open, lock and have screens; egress windows open easily","Basement outside entrances kept tight against pests and water","Anti-tilt device on the stove; all utilities on at the time of inspection","Smoke alarm on every level, in every bedroom and outside each sleeping area (form says battery operated)","Carbon monoxide alarm near sleeping areas if the home has a fuel-burning appliance or attached garage","ABC fire extinguisher, 5 to 10 lb, mounted in a visible, convenient spot (April 2026 form still lists it)","Bathroom window or exhaust fan vented outside","Mechanical equipment (exhaust fans, sump pumps, wood stoves, fireplaces) safe and working","No electrical hazards: no open junction boxes, taped splices or extension-cord wiring; service wire in sound condition","GFCI protection for pools, spas, exterior and garage outlets, within 5 feet of water, and at kitchen and bath counters","Certifications may be required for roof, electrical, structural or heating items","Also: Tax, water, sewer and solid waste accounts paid; liens checked: The Resale Application has Tax Office and Public Works sign-off lines: liens checked, taxes paid, solid waste, water and sewer accounts paid, and sewer/water units billed.","Also: Well and septic reports: The Housing Office intake checklist asks for a well report and septic report to be attached (for properties on well or septic).","Also: Open permits, code violations and vacant property fees: Housing Office checks open construction permits, open code violations and vacant property registration fees before issuing.","Also: Buyer assuming the certificate: If the buyer takes responsibility for obtaining the certificate, the office must be told in writing before it is issued."]$j$::jsonb, $j$[{"label":"Resale inspection (initial inspection)","amount":"$150.00"},{"label":"Each reinspection","amount":"$50.00"}]$j$::jsonb, $t$https://www.pemberton-twp.com/04.29.26%20Resale%20Application.pdf?t=202605041545530$t$, $t$https://www.pemberton-twp.com/departments/community_development/code_enforcement_division/index.php$t$, $j$[{"url":"https://www.pemberton-twp.com/04.29.26%20Resale%20Application.pdf?t=202605041545530","label":"Official source (pemberton-twp.com)"},{"url":"https://www.pemberton-twp.com/departments/community_development/code_enforcement_division/code_enforcement_forms.php","label":"Official source (pemberton-twp.com)"},{"url":"https://www.pemberton-twp.com/departments/community_development/code_enforcement_division/index.php","label":"Official source (pemberton-twp.com)"}]$j$::jsonb, $t$A Certificate of Occupancy Transfer is required in the Township of Pemberton EACH time a residential dwelling unit changes occupant.$t$, $t$093641445e80883740abfe35a84a29d7ef0b9edf87a0f264e55823a6461e3fd0$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":14,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0329.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0329.json$t$, true),
  ($t$0329$t$, $t$Pemberton Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Not confirmed. Likely Pemberton Township Code Enforcement Division, which checks smoke alarms, CO alarms and the extinguisher during the Certificate of Occupancy Transfer inspection","Contact: Wendy Jones or Michael Knoblock · 609-894-3376 · wjones@pemberton-twp.com","How to apply: No separate smoke/CO certificate application was found. The township CO Transfer checklist covers smoke alarms, CO alarms and the extinguisher. Call Code Enforcement at 609-894-3376 to confirm whether the CO Transfer also serves as the state smoke/CO certificate.","Fire official in the NJ state directory (NJ DCA, state), updated 6/16/2026: Louis Kilmer · (609)633-6132","Smoke alarm on every level, in every bedroom and outside each sleeping area","Carbon monoxide alarm near sleeping areas (homes with a fuel-burning appliance or attached garage)","ABC fire extinguisher, 5 to 10 lb, mounted in a visible, convenient location (still on the April 2026 township checklist)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.pemberton-twp.com/departments/community_development/code_enforcement_division/index.php$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.pemberton-twp.com/04.29.26%20Resale%20Application.pdf?t=202605041545530","label":"Official source (pemberton-twp.com)"}]$j$::jsonb, $t$S Pemberton Township$t$, $t$486582dbf34be3f4d2cfc9c7f9d50bd403b7c36f6a9e8234b1e45b38258e6082$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":14,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0329.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0329.json$t$, true),
  ($t$0330$t$, $t$Riverside Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate of Occupancy$t$, $j$["Issued by: Riverside Township Housing Office (inspections arranged through the Construction Office; the Housing Office page lists Cinnaminson Fire Department as the inspectors)","Contact: 856-461-1460 · housing@riversidetwp.org","How to apply: Download the Application for Resale (April 2025 version) from the Housing Office page, fill it out, and email it to schedule the inspection. The Housing Office page says to arrange inspections through the Construction Office at housing@riversidetwp.org; the application form itself says inspection requests must be emailed to acosello@riversidetwp.org. The $125 per unit fee is printed on the form. Payment method is not stated.","Valid for: 60 days from the date of issuance","Exterior: driveway and walks without cracks or sinking sections; yard free of high grass, trash and debris","Windows not broken or cracked, able to open and stay up; screens in place without holes","Roof, siding, gutters, downspouts and foundation in good repair; peeling paint removed","Visible house number (and unit numbers on each unit)","Doors open and close properly; double-key deadbolts not permitted","Exterior wiring in good condition and GFI outlets near water","Converted garages may need permits; garage separation needs drywall and a fire-rated or solid door","Pools safeguarded and bonded; pool gates and fencing self-closing or self-latching","Interior walls, ceilings and floors in good condition; all lights, switches and outlets work with cover plates","Handrails on all staircases, including the open side","Working stove and oven with anti-tip device; range hood or exhaust fan","Hot and cold water without leaks; drains flow freely","Smoke alarms on each floor; smoke and CO alarms within 10 feet of bedrooms (10-year battery recommended)","Electric panel covered with working, labeled breakers; water heater with relief pipe","Fire extinguisher (checklist says \"210ABC\") mounted on the kitchen wall no higher than 5 feet (2019 checklist)","Also: Resale Affidavit if the buyer takes on repairs: A notarized Resale Affidavit lets the buyer accept responsibility for noted violations, but it is not a substitute for the Certificate of Occupancy: all repairs must be completed, reinspected and approved before the property can be occupied.","Also: Rental registration if the buyer will rent it out: The resale application asks the proposed use (owner occupy, rental, renovate to sell); rental and vacant properties must be registered (contact jransburgh@riversidetwp.org per the form)."]$j$::jsonb, $j$[{"label":"Resale inspection, per unit","amount":"$125.00"}]$j$::jsonb, $t$https://riversidetwp.org/wp-content/uploads/2025/04/2APPLICATION-FOR-RESALE.pdf$t$, $t$https://riversidetwp.org/housing-office/$t$, $j$[{"url":"https://riversidetwp.org/housing-office/","label":"Official source (riversidetwp.org)"},{"url":"https://riversidetwp.org/wp-content/uploads/2025/04/2APPLICATION-FOR-RESALE.pdf","label":"Official source (riversidetwp.org)"},{"url":"https://riversidetwp.org/wp-content/uploads/2021/11/1HOUSING-INSPECTION-CHECKLIST-Copy.pdf","label":"Official source (riversidetwp.org)"}]$j$::jsonb, $t$A Certificate of Occupancy is required prior to the sale of any property within the Township.$t$, $t$9afb1663a77ed2adb12fcf7c3aeaf40ab283ad064affb285c5d0a7afaa226eb8$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":1,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":14,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0330.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0330.json$t$, true),
  ($t$0330$t$, $t$Riverside Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Riverside Township Fire Official (municipal fire code enforcing agency) (town fire bureau)","Contact: Robert Yearly, Fire Official (state directory); Fire Subcode Official, Fire Inspector (township page) · 856-461-1460","How to apply: No separate smoke/CO certificate form or fee was found on the township website. The state directory lists Riverside Township, 237 S. Pavilion Ave, (856) 461-1460 for smoke detector compliance. The resale housing inspection also checks smoke alarms, CO alarms and the extinguisher. Call 856-461-1460 to confirm how the certificate is issued.","Fire official in the NJ state directory (town), updated 3/5/2026: Robert Yearly · (856) 461-1460 · robertyearly@comcast.net","Smoke alarms on each floor, and smoke and CO alarms within 10 feet of bedrooms; 10-year battery recommended (township 2019 housing checklist)","Fire extinguisher (checklist says \"210ABC\") mounted on the wall in the kitchen no higher than 5 feet (2019 checklist)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://riversidetwp.org/construction-and-zoning-office/$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://riversidetwp.org/construction-and-zoning-office/","label":"Official source (riversidetwp.org)"},{"url":"https://riversidetwp.org/wp-content/uploads/2021/11/1HOUSING-INSPECTION-CHECKLIST-Copy.pdf","label":"Official source (riversidetwp.org)"}]$j$::jsonb, $t$M Riverside Township$t$, $t$6d94c0b7bb752812e200b184ebabad21eceee45ee731d7e55cdbb254e56402a5$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":1,"fee_bad":0,"fee_unchecked":0,"quotes":14,"q_ok":14,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0330.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0330.json$t$, true),
  ($t$0332$t$, $t$Shamong Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Re-Sale Inspection (property maintenance certificate)$t$, $j$["Issued by: Shamong Township Construction Office (Building Code, Construction Permits & Zoning)","Contact: Kevin Bagnell, Construction Permit/Resale Inspector · 609-268-2377 x305 · inspections@shamong.net","Apply: Give 14 days notice when scheduling the inspection","How to apply: Download the Residential Re-Sale Inspection form from the Building Code, Construction Permits & Zoning page. Send it with a check payable to Township of Shamong to the Construction Office, 105 Willow Grove Road, Shamong, NJ 08088, and give 14 days notice when scheduling. Questions and inspection requests go to inspections@shamong.net. The certificate can be delivered by email, mail or pick-up.","Valid for: If the ownership change does not happen within six months, a new application is required","Smoke alarm on each floor, including the basement (not unfinished attic or crawl space)","Smoke and carbon monoxide alarm within 10 feet of all bedrooms","House numbers on the front of the house or end of the driveway, at least 3 inches, lighted or reflective","Reflective house numbers on both sides of the mailbox","Pool and hot tub enclosures up to code","Steps and railings stable and secure","Chimney caps and spark arrestor installed","Visible, mounted 2A10BC fire extinguisher in the kitchen (January 2024 form)","All construction permits closed before the inspection is completed","Also: All construction permits closed: All construction permits must be closed before the resale inspection can be completed.","Also: Buyer purchasing \"as is\": If the buyer is purchasing the property as is, the township needs a notarized letter saying so; no certificate is issued without it."]$j$::jsonb, $j$[{"label":"Residential re-sale inspection","amount":"$50.00"},{"label":"Re-inspection","amount":"$25.00"}]$j$::jsonb, $t$https://www.shamong.net/Documents/Department%20Contacts%20%20Hours/Building%20Code/Residential%20Re-Sale%20Inspection%20Form.pdf?t=202401051312280$t$, $t$https://www.shamong.net/department_contacts__hours/building_code_construction_permits__zoning/index.php$t$, $j$[{"url":"https://www.shamong.net/Documents/Department%20Contacts%20%20Hours/Building%20Code/Residential%20Re-Sale%20Inspection%20Form.pdf?t=202401051312280","label":"Official source (shamong.net)"},{"url":"https://www.shamong.net/department_contacts__hours/building_code_construction_permits__zoning/index.php","label":"Official source (shamong.net)"}]$j$::jsonb, $t$RESIDENTIAL RE-SALE INSPECTION$t$, $t$1cd570cc0b60a843c2d6e134139674efcf56a3c9dd84278ae95dfeb4fa14bc65$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":17,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0332.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0332.json$t$, true),
  ($t$0332$t$, $t$Shamong Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Shamong Township Construction Office (designated for smoke detector compliance; NJ DCA is the fire code enforcing agency) (town fire bureau)","Contact: Kevin Bagnell, Construction Permit/Resale Inspector · 609-268-2377 x305 · inspections@shamong.net","Apply: Give 14 days notice when scheduling","How to apply: Smoke alarms, CO alarms and the extinguisher are checked during the Residential Re-Sale Inspection ($50, see the resale certificate section). No separate smoke certificate form or fee was found. Email inspections@shamong.net.","Fire official in the NJ state directory (NJ DCA, state), updated 6/16/2026: Louis Kilmer · (609)633-6132","Smoke alarm on each floor, including the basement","Smoke and CO alarm within 10 feet of all bedrooms","Visible, mounted 2A10BC fire extinguisher in the kitchen (January 2024 township form still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.shamong.net/Documents/Department%20Contacts%20%20Hours/Building%20Code/Residential%20Re-Sale%20Inspection%20Form.pdf?t=202401051312280$t$, $t$https://www.shamong.net/department_contacts__hours/building_code_construction_permits__zoning/index.php$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.shamong.net/Documents/Department%20Contacts%20%20Hours/Building%20Code/Residential%20Re-Sale%20Inspection%20Form.pdf?t=202401051312280","label":"Official source (shamong.net)"},{"url":"https://www.shamong.net/department_contacts__hours/building_code_construction_permits__zoning/index.php","label":"Official source (shamong.net)"}]$j$::jsonb, $t$S Shamong Township$t$, $t$86425e782cd1a736da63c902fa7cfbdeaf383d6817b49dd753937b2563624355$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":17,"q_ok":17,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0332.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0332.json$t$, true),
  ($t$0333$t$, $t$Southampton Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Resale Inspection / Resale Certificate$t$, $j$["Issued by: Southampton Township Office of Construction, Zoning and Land Development","Contact: Tom Boyd, Construction Official, Building Subcode Official (handles resale inspections) · 609-859-2786 · tboyd@southamptonnj.org","Apply: Application and fee must be received at least 14 days before the settlement date","How to apply: Download the 2026 Residential Resale Inspection Application from the Construction & Zoning page and submit it with the fee to the Construction Office, 5 Retreat Road, at least 14 days before settlement. Questions and inspection requests go to construction@southamptonnj.org. Payment method is not stated on the form.","Smoke alarms on each level of the home and within 10 feet of any sleeping room","Carbon monoxide alarms within 10 feet of any sleeping room","House number at least 3 inches, visible from the street","All utilities on","Guard rails and handrails secure and steady, no missing spindles","Yard free of trash, grass cut, brush and weeds not overgrown","Siding, soffit and fascia secure","Doors and windows in good working condition","No open electric outlets, switches or lights; electric panel cover in place with no missing blanks","No open holes in walls or ceilings","Appliance venting in place and free of defects","Burlington County recycling receptacle stays at the property","Also: County recycling receptacle: The Burlington County recycling receptacle must stay at the property; contact the Recycling Coordinator (recyclingcoordinator@southamptonnj.org, 609-859-5574) if one is needed.","Also: Utilities on for inspection: All utilities must be on for the resale inspection."]$j$::jsonb, $j$[{"label":"Resale inspection, per unit","amount":"$50.00"},{"label":"Reinspection, per unit","amount":"$25.00"}]$j$::jsonb, $t$https://www.southamptonnj.org/Construction%20&%20Zoning/Forms/Resale%20Inspection%20Application%202026%20New.pdf?t=202607210900510$t$, $t$https://www.southamptonnj.org/government/construction___zoning.php$t$, $j$[{"url":"https://www.southamptonnj.org/Construction%20&%20Zoning/Forms/Resale%20Inspection%20Application%202026%20New.pdf?t=202607210900510","label":"Official source (southamptonnj.org)"},{"url":"https://www.southamptonnj.org/government/construction___zoning.php","label":"Official source (southamptonnj.org)"}]$j$::jsonb, $t$RESIDENTIAL RESALE INSPECTION APPLICATION$t$, $t$4257d776fa9519b984141005225ea96e87a87ea636fa63ed1e7b0129bc2f2576$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":13,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0333.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0333.json$t$, true),
  ($t$0333$t$, $t$Southampton Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Southampton Township Construction Office (designated for smoke detector compliance; NJ DCA is the fire code enforcing agency) (town fire bureau)","Contact: Tom Boyd, Construction Official, Building Subcode Official (handles resale inspections) · 609-859-2786 · tboyd@southamptonnj.org","Apply: At least 14 days before settlement","How to apply: Smoke and CO alarms are checked during the Residential Resale Inspection ($50 per unit, see the resale certificate section); the resale certificate cites the state smoke alarm rules. No separate smoke certificate form or fee was found.","Fire official in the NJ state directory (NJ DCA, state), updated 6/25/2026: Louis Kilmer · (609)633-6132","Smoke alarms on each level and within 10 feet of any sleeping room","CO alarms within 10 feet of any sleeping room","The July 2026 township form does not list a fire extinguisher","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.southamptonnj.org/Construction%20&%20Zoning/Forms/Resale%20Inspection%20Application%202026%20New.pdf?t=202607210900510$t$, $t$https://www.southamptonnj.org/government/construction___zoning.php$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.southamptonnj.org/Construction%20&%20Zoning/Forms/Resale%20Inspection%20Application%202026%20New.pdf?t=202607210900510","label":"Official source (southamptonnj.org)"}]$j$::jsonb, $t$S Southampton Township$t$, $t$b1b38e54851ca900f778ab1012030386d69a493620126b5fce1c58c67914e74e$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":13,"q_ok":13,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0333.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0333.json$t$, true),
  ($t$0334$t$, $t$Springfield Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate for Change in Occupancy or Ownership (Resale/Rental Certificate)$t$, $j$["Issued by: Springfield Township Construction Office","Contact: Joseph LaRocca, Construction Official, Building and Fire Subcode Official · 609-723-2464 · jlarocca@springfieldtownshipnj.org","How to apply: Download the Resale/Rental Application (Rev. Mar 2025) from the Construction Office resources, check \"Sale\", sign it, and submit it with a check or money order for $150.00 payable to \"Springfield Township\" to the Construction Office, 2159 Jacksonville-Jobstown Road, Jobstown, NJ 08041. The fee is non-refundable. Inspection results and the certificate are sent by email.","Smoke alarms on every level and outside each sleeping area: 10-year sealed battery alarms, or hardwired where required","Basement alarm at the bottom of the stairwell on the ceiling (not between joists); hallway alarms close to all bedrooms","Smoke alarms less than 10 years old (or not past the maker's expiration date) and working","Hardwired smoke alarms required by the building code cannot be replaced with battery alarms","Homes with a monitored low-voltage fire alarm system: have it tested by the alarm company before the inspection and bring the certification","CO alarm in the hallway close to all bedrooms, less than 10 years old, UL listed and working","Fire extinguisher rated 2A-10B:C, no more than 10 lb, within 10 feet of the kitchen in the path of egress, top no more than 5 feet above the floor, on the maker's bracket, not in a closet or behind a door; leave the manual for the new occupant (March 2025 checklist)","House numbers at least 3 inches, contrasting, permanently fixed to the house and visible from the street","No open Springfield Township construction permits; all permitted work finalized and passed","Also: Open construction permits closed: No outstanding Springfield Township construction permits; all permitted work must be finalized and passed before the resale inspection passes.","Also: Rental registration deactivated: If the property was a rental, the landlord registration is deactivated on the resale application."]$j$::jsonb, $j$[{"label":"Resale inspection (includes two inspections)","amount":"$150.00"},{"label":"Each additional inspection after the first two","amount":"$65.00"}]$j$::jsonb, $t$https://www.springfieldtownshipnj.org/index?i=8EdLWBbrPaZMTUQGXRxGse9maokNtDsfLztEPHsUFaDvE4IuruYbYfb5tm5ilT4t&rf=i$t$, $t$https://www.springfieldtownshipnj.org/constructionoffice$t$, $j$[{"url":"https://www.springfieldtownshipnj.org/constructionoffice","label":"Official source (springfieldtownshipnj.org)"},{"url":"https://www.springfieldtownshipnj.org/api/blob/viewBlob?i=8EdLWBbrPaZMTUQGXRxGse9maokNtDsfLztEPHsUFaD%2fkDxkTbO4b1PLWTCA07hN","label":"Official source (springfieldtownshipnj.org)"},{"url":"https://www.springfieldtownshipnj.org/api/blob/viewBlob?i=8EdLWBbrPaZMTUQGXRxGse9maokNtDsfLztEPHsUFaDvE4IuruYbYfb5tm5ilT4t","label":"Official source (springfieldtownshipnj.org)"},{"url":"https://app.membershipware.com/api/public/mwjsPeople?et=Jfp%252B3K9fyAYWIble3%252BR4eQ%3d%3d&eb=0xG5h%252BICHBzdF1eDwLDXRA%3d%3d","label":"Official source (app.membershipware.com)"}]$j$::jsonb, $t$The Springfield Construction Office is responsible for construction permits, plan reviews, inspections, and Resale / Rental Certificates as allowed by the State of New Jersey and the Springfield Township code.$t$, $t$2f27da1c937e250a819107e47830b924639d613467bf2444fbad516e5f1be4d4$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":15,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0334.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0334.json$t$, true),
  ($t$0334$t$, $t$Springfield Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Springfield Township Construction Office (designated for smoke detector compliance; NJ DCA is the fire code enforcing agency) (town fire bureau)","Contact: Joseph LaRocca, Construction Official, Building and Fire Subcode Official · 609-723-2464 · jlarocca@springfieldtownshipnj.org","How to apply: The smoke alarm, CO alarm and extinguisher checks (N.J.A.C. 5:70-4.19) are part of the $150 resale inspection; see the resale certificate section. No separate smoke certificate form or fee was found.","Fire official in the NJ state directory (NJ DCA, state), updated n/a: Louis Kilmer · (609)633-6132","10-year sealed battery smoke alarms (or hardwired as required) on every level and near all bedrooms; alarms under 10 years old","Hardwired alarms cannot be replaced with battery alarms","CO alarms under 10 years old in the hallway near all bedrooms","Fire extinguisher 2A-10B:C, 10 lb maximum, mounted within 10 feet of the kitchen, top no higher than 5 feet (March 2025 township checklist still lists it)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.springfieldtownshipnj.org/index?i=8EdLWBbrPaZMTUQGXRxGse9maokNtDsfLztEPHsUFaDvE4IuruYbYfb5tm5ilT4t&rf=i$t$, $t$https://www.springfieldtownshipnj.org/constructionoffice$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"},{"url":"https://www.springfieldtownshipnj.org/api/blob/viewBlob?i=8EdLWBbrPaZMTUQGXRxGse9maokNtDsfLztEPHsUFaD%2fkDxkTbO4b1PLWTCA07hN","label":"Official source (springfieldtownshipnj.org)"}]$j$::jsonb, $t$S Springfield Township$t$, $t$be641db4c81e541c1a08d90b2514bd61b7bca29c56711e4040809a67ee43fb65$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":15,"q_ok":15,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0334.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0334.json$t$, true),
  ($t$0336$t$, $t$Washington Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Inspection Certificate$t$, $j$["Issued by: Washington Township Code Enforcement","Contact: Robert Henchy, III, Code Enforcement Officer · 609-965-3242 x253 · codeenforcement@wtbcnj.org","How to apply: Fill out the township Re-Sale Form (Code Enforcement; owner, block and lot, agent and settlement date) and return it to the Municipal Building, 2436 Route 563, Green Bank, Egg Harbor City, NJ 08215, with the fee. Payment method is not stated. Contact Code Enforcement at 609-965-3242 x253.","House number in Arabic numerals, at least 3 inches high, at least 30 inches above ground, not blocked by trees or shrubs, visible from the street","Any fence, deck, shed, or above-ground or in-ground pool built without zoning or construction permits will delay the certificate until corrected","Sidewalks must not be raised or broken","The form refers to an attached sheet of more inspected items; that sheet is not posted online","Also: Unpermitted structures: Fences, decks, sheds or pools built without zoning or construction permits must be corrected or abated before the Resale Inspection Certificate is issued."]$j$::jsonb, $j$[{"label":"Resale inspection","amount":"$150.00"},{"label":"Each re-inspection","amount":"$50.00"}]$j$::jsonb, $t$https://wtbcnj.org/wp-content/uploads/2026/08/0535_001.pdf$t$, $t$https://wtbcnj.org/code-enforcement-officer/$t$, $j$[{"url":"https://wtbcnj.org/wp-content/uploads/2026/08/Ordinance-2026-07-Adoption-Washington-Twp.pdf","label":"Official source (wtbcnj.org)"},{"url":"https://wtbcnj.org/wp-content/uploads/2026/09/8.4.2026-Regular.pdf","label":"Official source (wtbcnj.org)"},{"url":"https://wtbcnj.org/forms-applications/","label":"Official source (wtbcnj.org)"},{"url":"https://wtbcnj.org/wp-content/uploads/2026/08/0535_001.pdf","label":"Official source (wtbcnj.org)"},{"url":"https://wtbcnj.org/code-enforcement-officer/","label":"Official source (wtbcnj.org)"}]$j$::jsonb, $t$AMENDING CHAPTER 145 OF THE CODE OF THE TOWNSHIP OF WASHINGTON TO CREATE AN ARTICLE V ENTITLED RESALE OF PROPERTY$t$, $t$442c9e12463079d6ec7087362447b42a74bc5f453b5bbf59ce6e0c1b316477f0$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":10,"q_ok":8,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0336.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0336.json$t$, true),
  ($t$0336$t$, $t$Washington Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Not confirmed: Washington Township (NJ DCA is the fire code agency but does not issue smoke certificates here)","Contact: 609-965-3242","How to apply: Call the Municipal Building at 609-965-3242 to ask which office issues the smoke alarm and carbon monoxide alarm certificate for a sale. The NJ DCA online smoke certificate portal marks Washington Township (Burlington) as smoke-certificate exempt, so the state does not take these applications.","Fire official in the NJ state directory (NJ DCA, state), updated 6/17/2026: Louis Kilmer · (609)633-6132","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://wtbcnj.org/$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/_odata/firedistricts","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$S Washington Township$t$, $t$cd5d80122198b583561d0eae0f3a739273b188d8de6e34999ed24ba2469602f7$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":10,"q_ok":8,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0336.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0336.json$t$, true),
  ($t$0337$t$, $t$Westampton Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Westampton Township. Confirm with the office if the buyer's lender or title company asks.","Contact: (609) 267-1891 ext. 101"]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.westamptonnj.gov/construction-code-enforcement-inspections/pages/resalerental-home$t$, $j$[{"url":"https://web.archive.org/web/20260530112936/https://www.westamptonnj.gov/construction-code-enforcement-inspections/pages/resalerental-home","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$There is no Certificate of Occupancy (CO) required in Westampton Township. What is required is a Smoke Detector/Carbon Monoxide/Fire Extinguisher Inspection.$t$, $t$140a8fdefc684e96459d3ee87fcc995153a8825880afe50e515ecdb336929fc6$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":11,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0337.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0337.json$t$, true),
  ($t$0337$t$, $t$Westampton Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Westampton Township Emergency Services Bureau of Fire Prevention (WTES) (town fire bureau)","Contact: Vincent M Knott, Fire Official · 609-267-2041 (option 3 for the Fire Marshal) · firemarshal@wtes.us","Apply: Submit the request 3 to 4 weeks before settlement. The lowest fee applies when the request is received 14 calendar days or more before settlement.","How to apply: Request the inspection online with the WTES Formstack form, or call 609-267-2041 to set an appointment. Pay by check or money order payable to 'Westampton Township Emergency Services Bureau of Fire Prevention' at the time of inspection. Certificates are valid for 90 days.","Fire official in the NJ state directory (town), updated 5/18/2026: Vincent M Knott · (609) 267-2041 · Vknott@wtes.us","House numbers at least 4 inches high, contrasting color, permanently fixed to the house and visible from the street (mailbox or lamp post numbers not accepted)","Smoke alarm on every level; basement alarm at the bottom of the stairwell on the ceiling (not between joists)","Hallway smoke alarms within 10 feet of all bedroom doors; smoke alarms on the ceiling in each bedroom if the home was built after 1991","Smoke and CO alarms must be less than 10 years old and working; battery smoke alarms must be the 10-year sealed type; hard-wired alarms cannot be replaced with battery alarms","CO alarm in the hallway within 10 feet of all bedrooms (plug-in, battery or hard-wired accepted; not in switched outlets)","Homes with a low-voltage fire alarm system need the system tested and certified by an alarm contractor before the inspection, with the certificate shown to the inspector","Fire extinguisher still listed on the WTES page (2026): mounted on a bracket within 10 feet of the kitchen in the path of egress, minimum rating 2A-10B:C, under 10 pounds","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received 14 calendar days before settlement","amount":"$70.00"},{"label":"Request received 13 calendar days or less before settlement","amount":"$140.00"},{"label":"Request received 4 calendar days or less before settlement","amount":"$165.00"},{"label":"Re-inspection","amount":"$70.00"}]$j$::jsonb, $t$https://westamptonfire.formstack.com/forms/smoke_detector_inspection_application$t$, $t$https://www.westamptonfire.org/content/certificate/$t$, $j$[{"url":"https://www.westamptonfire.org/content/certificate/","label":"Official source (westamptonfire.org)"},{"url":"https://web.archive.org/web/20260530112936/https://www.westamptonnj.gov/construction-code-enforcement-inspections/pages/resalerental-home","label":"Official source (web.archive.org)"},{"url":"https://www.westamptonfire.org/content/ordinances/","label":"Official source (westamptonfire.org)"},{"url":"https://www.westamptonfire.org/content/fireprevention/","label":"Official source (westamptonfire.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$Requests must be submitted 3 to 4 weeks prior to the settlement date. For questions and to set an appointment call 609-267-2041.$t$, $t$f20896325a0c252e6fe803fb64ee02a2ab6b22fbaf4ac715bdb16bdff126be8f$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":11,"q_ok":11,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0337.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0337.json$t$, true),
  ($t$0338$t$, $t$Willingboro Township$t$, $t$BURLINGTON$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (resale housing inspection)$t$, $j$["Issued by: Willingboro Township Inspections Department (Department of Code Enforcement and Inspections)","Contact: Shaleen Bolling-Gonzalez, Housing / Rental / Resales · 609-877-2200 ext. 1033","Apply: The township advises scheduling the inspection within 30 days of the settlement date, because the CO is good for 30 days. All violations must be reinspected within 30 days of the first inspection.","How to apply: Fill out the Resale Inspection Housing Application in the township's 'Moving' packet and submit it with the $150 fee to the Inspections Department, 1 Rev. Dr. Martin Luther King Jr. Drive, Willingboro. The form's office section lists check, cash or credit card. The Inspections page says resale/rental applications can also be submitted and paid online (the portal link is not shown on the page). The seller or agent can schedule the inspection; a lock box number lets the inspector enter. Give 24 hours notice to cancel or reschedule or the fee is still charged.","Valid for: 30 days","Township housing inspection of the whole house, inside and out; all violations corrected before the CO is issued","Exterior: driveway and walks free of cracks or raised sections; lawn, trash and debris cleaned up; fence stable; screens in windows (May 1 to Oct 1)","Roof: no missing or broken shingles, maximum 2 layers; siding and gutters in repair; peeling paint scraped and repainted","House number: 6 inch numbers on the building","Interior: walls, ceilings and floors in good repair; working lights, outlets and switches with cover plates; windows open and stay up; no double-keyed deadbolts","Kitchen and bath: working burners, plumbing without leaks, exhaust fan or window, cabinets in good condition","Handrails on all staircases; garage conversions may need permits","Smoke and CO detectors within 10 feet of bedrooms; smoke alarms must be ten-year sealed battery type","Portable fire extinguisher (still listed on the township checklist): at least 2:A:10B:C, no more than 10 lbs, mounted within 10 ft of the kitchen and not more than 5 ft above the floor","Electric service panel with covers, working and labeled breakers; water heater with pressure relief pipe and bonding","Original heating certificate from a Willingboro-registered heating contractor (valid 30 days)","Private sewer lateral video inspection report from a master plumber showing no repairs needed (valid 6 months)","Open construction permits must be passed and closed; work done without permits must be permitted","Copy of a current property survey for all resales","Also: Heating certificate: Original heating system certificate from a heating contractor on the township registered list, valid 30 days, must be brought in to get the CO.","Also: Private sewer lateral inspection: Seller must hire a master plumber or utility contractor for a video inspection and certified Private Sewer Lateral Inspection Report (Ordinance 2021-13, Chapter 291). Repairs must be done before the CO; a satisfactory report is good for 6 months. Start once the home is listed, no later than the agreement of sale.","Also: Open permits: Open construction permits are checked and must have final inspections; work done without permits must be permitted. The CO will not be issued until all permits are passed and closed out.","Also: Property survey: A copy of a current survey of the property must be submitted before a certificate can be issued for all resales.","Also: Flood hazard letter: The resale CO includes a flood hazard letter and certificate of housing code along with the smoke detector certification.","Also: Certified tax search and added assessment: Certified tax search request goes to the Tax Collector with a $10.00 fee (per the packet form); see the Tax Assessor about added assessments for improvements."]$j$::jsonb, $j$[{"label":"Resale housing inspection (includes one re-inspection within 30 days)","amount":"$150.00"}]$j$::jsonb, $t$https://www.willingboronj.gov/DocumentCenter/View/307/Resale-Application-2026-PDF$t$, $t$https://www.willingboronj.gov/243/Inspections-Code-Enforcement$t$, $j$[{"url":"https://www.willingboronj.gov/DocumentCenter/View/307/Resale-Application-2026-PDF","label":"Official source (willingboronj.gov)"},{"url":"https://www.willingboronj.gov/243/Inspections-Code-Enforcement","label":"Official source (willingboronj.gov)"},{"url":"https://www.willingboronj.gov/m/directory/department?did=20","label":"Official source (willingboronj.gov)"}]$j$::jsonb, $t$Did you know Willingboro Township requires all homes to be transferred or sold to have an inspection done by a Willingboro Township Housing Inspector.$t$, $t$8cf67c993b582af647a4eca822309fa0d78b1e2f31b7378858a0bd3563c948d3$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":16,"q_ok":7,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0338.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0338.json$t$, true),
  ($t$0338$t$, $t$Willingboro Township$t$, $t$BURLINGTON$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Willingboro Township Inspections Department (town fire bureau)","Contact: Dennis Tunstall, Director, Inspections · 609-877-2200 ext. 1214","How to apply: For a sale, the township's resale Certificate of Occupancy includes the smoke detector certification, so the $150 resale housing inspection covers it. The township also posts a separate Application for Certificate of Compliance (smoke detectors, CO alarms, fire extinguisher; $150) inspected by a township inspector; submit it to the Inspections Department, 1 Rev. Dr. Martin Luther King Jr. Drive, and give 24 hours notice to cancel or reschedule or the fee is forfeited.","Fire official in the NJ state directory (NJ DCA, state), updated 6/16/2026: Louis Kilmer · (609) 633-6132","Smoke detector on each level including basements (not attics or crawl spaces)","Smoke detector and CO alarm outside each separate sleeping area and within 10 feet of bedrooms","Battery smoke alarms must be the ten-year sealed type (township checklist)","The township forms (2026 Certificate of Compliance and the resale checklist) still require a fire extinguisher within 10 feet of the kitchen, rated at least 2:A:10B:C and no more than 10 lbs, mounted with the manufacturer bracket not more than 5 ft above the floor","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Certificate of Compliance (smoke, CO alarms and fire extinguisher) inspection, when applied for separately","amount":"$150.00"}]$j$::jsonb, $t$https://www.willingboronj.gov/DocumentCenter/View/308/Certificate-of-Compliance-2026-PDF$t$, $t$https://www.willingboronj.gov/245/Inspection-Forms$t$, $j$[{"url":"https://www.willingboronj.gov/DocumentCenter/View/308/Certificate-of-Compliance-2026-PDF","label":"Official source (willingboronj.gov)"},{"url":"https://www.willingboronj.gov/DocumentCenter/View/307/Resale-Application-2026-PDF","label":"Official source (willingboronj.gov)"},{"url":"https://www.willingboronj.gov/243/Inspections-Code-Enforcement","label":"Official source (willingboronj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/_odata/firedistricts","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$A CERTIFICATE OF COMPLIANCE IS REQUIRED ON ALL HOMES BEING TRANSFERRED OR SOLD PRIOR TO OCCUPANCY$t$, $t$ebb230fc0c3d7b0b948ee1e8c9e1e96cb1ad7da5ad4696acd3d25cdef79daa26$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":16,"q_ok":7,"q_bad":0,"q_unchecked":9},"source":"property/data/municipal-requirements/checked/0338.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0338.json$t$, true),
  ($t$0401$t$, $t$Audubon Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy for Sale or Resale of Property$t$, $j$["Issued by: Borough of Audubon (requests handled by the Administrative Assistant to the Superintendent of Public Works; interior fire inspection by the Fire Marshal, exterior inspection by the Borough)","Contact: 856-547-1240 ext. 110 · k.melvin@audubonnj.com","Apply: Submit the request at least 15 business days before settlement; inspections and responses typically take 7 to 10 business days","How to apply: Only the seller or the seller's agent (attorney, agent or property manager) may request; buyers and buyers' agents cannot. Fill out the 2026 CO application (or email the seller name, property address, closing date and whether there is a sump pump) to Kristen Melvin at k.melvin@audubonnj.com. Pay with two separate payments ($50 exterior and $25 fire) by check or money order payable to Borough of Audubon, or exact cash. No credit, debit or online payments. Payments can be mailed, brought in person, or left in the black vestibule lockbox marked Attention: CO. Call the Construction Office first to make sure all permits are closed.","Valid for: 90 days from the date of issuance","Two inspections must both pass: an interior fire inspection and an exterior property inspection","Sidewalks, walkways, driveways, driveway aprons, steps and pavers must be free of cracks, raised or uneven surfaces, deterioration and trip hazards","Ramping a raised sidewalk joint is not an acceptable repair","Smoke and CO detectors must be UL listed, have a 10-year sealed battery, and be no more than 10 years old","Hardwired smoke alarms cannot be swapped for battery units; hardwired units must be interconnected and working","Smoke detector on every level (basement, each floor, and a finished or used attic) and in every bedroom","Working smoke and CO detector within 10 feet of all bedrooms","House numbers at least 4 inches tall, contrasting, visible from the street","No double-cylinder (keyed both sides) deadbolts on exit doors; exits must open from inside without a key","Sump pumps, roof drains and other discharges may not be connected to the sanitary sewer","All liens and property maintenance charges resolved and all construction permits closed before the CO is issued","Also: Open construction permits must be closed: Sellers must contact the Construction Office to make sure all permits are closed before applying: (856) 547-6312, n.bicking@audubonnj.com.","Also: Liens and property maintenance charges: All liens and outstanding property maintenance charges must be resolved before the CO is issued.","Also: Sump pump / drainage disclosure: The request must state whether there is a sump pump; sump pumps and roof drains may not discharge into the sanitary sewer."]$j$::jsonb, $j$[{"label":"Exterior property inspection","amount":"$50"},{"label":"Interior fire inspection (paid separately)","amount":"$25"},{"label":"Exterior inspection, per 2026 application form (separate check or money order)","amount":"$50.00"},{"label":"Fire inspection, per 2026 application form (separate check or money order)","amount":"$25.00"}]$j$::jsonb, $t$https://www.audubonnj.com/fs/resource-manager/view/a9f9ee38-a0fd-4f3f-9fa3-1dc8f825f14f$t$, $t$https://www.audubonnj.com/constructionzoning/resale-certificate-of-occupancy-info$t$, $j$[{"url":"https://www.audubonnj.com/constructionzoning/resale-certificate-of-occupancy-info","label":"Official source (audubonnj.com)"},{"url":"https://www.audubonnj.com/fs/resource-manager/view/05c9a18f-ba4c-4afa-972c-de7cac87ec93","label":"Official source (audubonnj.com)"},{"url":"https://www.audubonnj.com/fs/resource-manager/view/a9f9ee38-a0fd-4f3f-9fa3-1dc8f825f14f","label":"Official source (audubonnj.com)"}]$j$::jsonb, $t$A Certificate of Occupancy (CO) is required for the sale or resale of all residential and non-residential properties in the Borough of Audubon, whether occupied or vacant.$t$, $t$8d92e5ebc1c7eff042e0e4d997b8875123adcac94586943f6f2ae0bddab4cb14$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":8,"q_ok":8,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0401.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0401.json$t$, true),
  ($t$0404$t$, $t$Bellmawr Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Residential Certificate of Occupancy (Resale or Change of Ownership)$t$, $j$["Issued by: Bellmawr Construction/Zoning/Code Enforcement Office","Contact: 856-933-1286 · ConstructionOffice@Bellmawr.com","Apply: Must be obtained before settlement; application and payment are required before an inspection is scheduled (no specific number of days published)","How to apply: Fill out the Residential Certificate of Occupancy Application and bring or mail it (addressed 'Attn: Construction') to the Construction Office, 21 E. Browning Road, Bellmawr, with cash (exact) or a check payable to Borough of Bellmawr. No credit cards in the office. All taxes, grass cuts, liens and open permits must be paid or closed before the application is accepted. The office calls to schedule the inspection once approved. Inspections are by lockbox or a 2 to 3 pm or 3 to 4 pm window. After passing, email to request the certificate or pick it up from the bin outside the Construction Office.","Valid for: 30 days from issuance","House number visible from the street, at least 4 inches tall","Steps without trip-hazard cracks; open wood risers closed so a 4 inch ball cannot pass","Cracked sidewalk or walkway blocks with a change in elevation must be replaced","Guardrails (36 inch minimum) where porches, landings or stairs are over 30 inches above grade; handrail on steps with 4 or more risers","Yard free of high grass, weeds, debris and bamboo (unless contained per Borough code)","Grading slopes away from the foundation; gutters, downspouts and splash blocks in place","Sump pump crock must have a pump, check valve, proper outlet, and discharge outside (never to the sanitary sewer)","No signs of pests; if found, a licensed pest control certification is needed","Bathroom window or exhaust fan; GFCI protection on existing bathroom, kitchen counter, garage and exterior outlets","Electrical covers, fixtures and panel secure and labeled; A/C disconnect at the outdoor unit","Bedroom windows open easily for escape; no double-keyed deadbolts","Water heater with proper relief valve and discharge pipe to 2 to 6 inches above the floor; no leaks","Heating system working","Smoke alarms on each floor including basement (10-year sealed battery); CO alarms near bedrooms if there is a gas or oil appliance; ABC extinguisher no larger than 10 lbs within 10 feet of the kitchen","Work done without permits and open permits must be resolved","Also: Taxes, grass cutting charges and liens paid first: All charges (taxes, grass, liens, etc.) must be paid before the CO application is accepted, even if they would be paid at settlement. Call 856-933-1313.","Also: Open permits and vacant property fees: Any vacant property fees and open permits must be closed out before any certificate is issued."]$j$::jsonb, $j$[{"label":"Resale CO inspection (cash or check only)","amount":"$100"},{"label":"Second inspection","amount":"No charge"},{"label":"Third inspection (re-inspection)","amount":"$75"},{"label":"Fourth or later re-inspection, each","amount":"$100"}]$j$::jsonb, $t$https://bellmawr.com/DocumentCenter/View/143/Residential-Certificate-of-Occupancy-Application-Resale-or-Change-of-Ownership-for-Duplex-Triplex-Also-PDF$t$, $t$https://www.bellmawr.com/172/Certificates-of-Occupancy$t$, $j$[{"url":"https://www.bellmawr.com/172/Certificates-of-Occupancy","label":"Official source (bellmawr.com)"},{"url":"https://bellmawr.com/DocumentCenter/View/143/Residential-Certificate-of-Occupancy-Application-Resale-or-Change-of-Ownership-for-Duplex-Triplex-Also-PDF","label":"Official source (bellmawr.com)"}]$j$::jsonb, $t$Must be obtained prior to settlement.$t$, $t$8814198f196fec78e044e9c5a3a29f0a84a1b9d52721438f73378be298f0aa8c$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":8,"q_ok":8,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0404.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0404.json$t$, true),
  ($t$0405$t$, $t$Berlin Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO)$t$, $j$["Issued by: Borough of Berlin Construction Department","Contact: 856-767-7777 ext. 316 · construction@berlinnj.org","How to apply: Fill out the Inspection Application for Certificate of Continued Occupancy (check 'House Sale') and submit it to the Construction Department, 59 S. White Horse Pike, Berlin. The Tax Collector must certify that taxes are current and there are no liens. Inspection requests can be emailed to construction@berlinnj.org.","All utilities on for the inspection; lockbox code if vacant","Trash and debris cleared inside and out","Walkways level and free of trip hazards","4 inch contrasting house number visible from the street","Graspable handrail on steps with more than four risers; guardrails on open stairs","Windows and doors operable, no cracked or broken glass","No pest or rodent infestation","Egress window or door in every bedroom; no bedrooms in basements","Bathroom window or exhaust fan","Dryer vent hard piped to the outside","Water heater discharge pipe ending 2 to 6 inches above the floor","Smoke detectors working on every level, under 10 years old, 10-year sealed battery if battery powered, hardwired units interconnected and not swapped for battery units","CO detector within 10 feet of each bedroom","Pools, fences, garages and decks safe; pool gates self-closing and self-latching","Wood-burning fireplace or stove needs a certificate showing it is in good working order","Thumb-turn locks (no keyed interior locks)","All open permits closed with final inspections; unpermitted work must be documented before the CCO is issued","Also: Tax Collector certification: The CCO application includes a Tax Collector sign-off that taxes are current and there are no liens.","Also: Open permits closed: All open permits must be closed with final passing inspections before a CCO is issued."]$j$::jsonb, $j$[{"label":"Initial CCO inspection","amount":"$100"},{"label":"Re-inspection","amount":"$50"}]$j$::jsonb, $t$https://www.berlinnj.org/wp-content/uploads/2025/05/CCO-Application.pdf$t$, $t$https://www.berlinnj.org/construction/$t$, $j$[{"url":"https://www.berlinnj.org/wp-content/uploads/2025/05/CCO-Application.pdf","label":"Official source (berlinnj.org)"},{"url":"https://berlinnj.org/berlinnj/AGENDA%20%202020-07-09.pdf","label":"Official source (berlinnj.org)"}]$j$::jsonb, $t$INSPECTION APPLICATION FOR CERTIFICATE OF CONTINUED OCCUPANCY$t$, $t$25e6dafb36ae2a1163c3f23be007fde123f752b4e54e316c68574a5766c9a824$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":8,"q_ok":8,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0405.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0405.json$t$, true),
  ($t$0407$t$, $t$Brooklawn Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued Certificate of Occupancy / Housing Inspection (Residential Dwelling Resale)$t$, $j$["Issued by: Borough of Brooklawn Construction/Zoning/Code Enforcement","Contact: 856-456-0750 ext. 105 · mperry@brooklawn-nj.com","Apply: Application and fee must be received before any inspection is scheduled; no set number of days published","How to apply: Fill out the Application for Continued Certificate of Occupancy/Housing Inspection (check 'Residential Dwelling RESALE') and bring or mail it with the fee (cash or check payable to Borough of Brooklawn, mailed 'Attn: Construction') to 301 Christiana St., Brooklawn. Then call the office to schedule. Inspections are by appointment only, Tuesday and Thursday 10:00 am to 12:00 pm. The report can be mailed, picked up or emailed.","Also: Water final reading: Water final reading request is $25.00, payable by check to Borough of Brooklawn, cash or money order. The form adds: 'If settlement date is within 3 days from the date of application, the fee is $100.00'; it is unclear whether that $100.00 applies to the water reading or the CO."]$j$::jsonb, $j$[{"label":"Residential dwelling resale CO","amount":"$100.00"},{"label":"CO re-inspection","amount":"$50.00"}]$j$::jsonb, $t$https://brooklawn-nj.com/wp-content/uploads/2023/07/CO-APP000.pdf$t$, $t$https://brooklawn-nj.com/departments/construction/$t$, $j$[{"url":"https://brooklawn-nj.com/wp-content/uploads/2023/07/CO-APP000.pdf","label":"Official source (brooklawn-nj.com)"},{"url":"https://brooklawn-nj.com/frequently-used-forms","label":"Official source (brooklawn-nj.com)"}]$j$::jsonb, $t$CO Inspections for both Rental Properties / Residential Sales or Commercial Properties are completed on Tuesday & Thursday between 10:00 am -12:00 pm by appointment only Application and fee must be received prior to scheduling any Inspection$t$, $t$08498e345c13e9780c6ffe052b9df4ebb20c9f67bdc4d2c7337724d240a022f7$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":3,"q_ok":2,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0407.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0407.json$t$, true),
  ($t$0408$t$, $t$Camden City$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Camden Resale Occupancy Certificate (C.R.O.C.); formerly Certificate of Continued Occupancy (C.C.O.)$t$, $j$["Issued by: City of Camden Construction & Building Bureau (Department of Code Enforcement)","Contact: 856-757-7032","Apply: Zoning approval must be obtained first; no set number of days published","How to apply: First apply for a zoning permit (Zoning, City Hall Room 224, 856-757-7214). After zoning approval, submit the application to the Building Bureau, City Hall Room 403, 520 Market Street (856-757-7032). The seller is responsible for applying; the buyer may apply as the seller's agent with written permission, and the certificate is issued to the buyer. Building Bureau visits are by appointment only (call the day before) and inspection requests must be made by email. The posted form is the 2022 CCO application; no separate C.R.O.C. form was found.","Valid for: Application is good for 6 months","Zoning permit and zoning approval before the application is accepted","Building, electrical, plumbing and fire inspections by the Building Bureau","All open building permits must be closed before the inspection","General inspection of the visible parts of the building for Uniform Construction Code violations","Also: Zoning approval first: A zoning permit and approval are required before the Building Bureau accepts the CCO/C.R.O.C. application. Zoning: City Hall Room 224, 856-757-7214.","Also: Open permits closed: All existing open building permits must be closed out before the CCO inspection; no certificate is issued while permits are open."]$j$::jsonb, $j$[{"label":"C.R.O.C. application","amount":"$200.00"},{"label":"CCO application fee (form)","amount":"$200.00"},{"label":"Name change on the CCO","amount":"$37.00"},{"label":"Penalty if the buyer closes without the certificate (up to)","amount":"$2,000.00"}]$j$::jsonb, $t$https://www.camdennj.gov/wp-content/uploads/2022/05/BB-CCO-App.pdf$t$, $t$https://www.camdennj.gov/construction-building-bureau/$t$, $j$[{"url":"https://www.camdennj.gov/faq-items/what-is-a-c-r-o-c/","label":"Official source (camdennj.gov)"},{"url":"https://www.camdennj.gov/building-bureau-faqs/","label":"Official source (camdennj.gov)"},{"url":"https://www.camdennj.gov/construction-building-bureau/","label":"Official source (camdennj.gov)"},{"url":"https://www.camdennj.gov/wp-content/uploads/2022/05/BB-CCO-App.pdf","label":"Official source (camdennj.gov)"}]$j$::jsonb, $t$The City of Camden requires that a Camden Resale Occupancy Certificate shall be applied for and issued prior to the sale or conveyance of any property within the city.$t$, $t$0381e74a92f95ecc16af77be7be26aa709a49aa96b78bf1f3fcf1a8913f8a6ed$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":8,"q_ok":8,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0408.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0408.json$t$, true),
  ($t$0410$t$, $t$Chesilhurst Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Winslow Township Fire Department, Fire Prevention Division (Winslow Township Fire District) (fire district)","Contact: 609-561-4225 · firedistrict@winslowtwpfd.org","Apply: Apply 3 to 4 weeks before the closing or move-in date","How to apply: Apply online through the Winslow Township Fire Department resale application, then pay through the Edmunds WIPP payment link; or download the packet and fax it to 609-561-5823; or apply in person at 9 Cedar Brook Road, Sicklerville (9 am to 5 pm weekdays). Pay by check (payable to Winslow Township Fire District), credit card, debit card or money order. Inspections are Tuesdays and Thursdays in a morning or afternoon block. All fees are non-refundable. Certificates are valid 90 days from the inspection date.","Fire official in the NJ state directory (fire district), updated 12/9/2025: Joseph G Hahn · (609) 561-4225 · josephh@winslowtwpfd.org","All battery (DC) smoke alarms must be 10-year sealed battery alarms","Smoke alarms must be less than 10 years old; the realtor, owner, seller or buyer must take each alarm down and check the date","Smoke alarm type and number follow the year the house was built (for example 1991 to present: hardwired alarms with battery backup on each level and in each bedroom, interconnected); hardwired alarms cannot be replaced with a single battery alarm","CO alarm within 10 feet of all sleeping areas if the home has a fuel-burning appliance, fireplace or attached garage","Homes with a secondary power source (solar, generator, battery storage) need a permanent, non-handwritten label at the main electrical panel and electric meter, such as 'Caution: Multiple Sources of Power'","Homes with a low-voltage fire alarm system must have it certified by an alarm contractor before the inspection","Electric power must be on; an adult (18+) must be present for the whole inspection; inspectors do not use lockboxes","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"8 or more days advance notice (instructions sheet)","amount":"$65.00"},{"label":"4 to 7 days notice","amount":"$100.00"},{"label":"3 days or less notice","amount":"$150.00"},{"label":"Senior discount, 62 or older (proof of age)","amount":"$30.00"},{"label":"Re-inspection, per visit","amount":"$35.00"},{"label":"Failure to keep appointment (no-show)","amount":"$35.00"}]$j$::jsonb, $t$https://winslowtwpfd.org/online-resale-application$t$, $t$https://winslowtwpfd.org/fire-marshal-office$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://winslowtwpfd.org/fire-marshal-office","label":"Official source (winslowtwpfd.org)"},{"url":"https://winslowtwpfd.org/vertical/sites/%7B2458775F-59B7-4354-B7A0-12D3BE8EC490%7D/uploads/Smoke_Application_2025.pdf","label":"Official source (winslowtwpfd.org)"},{"url":"https://winslowtwpfd.org/vertical/sites/%7B2458775F-59B7-4354-B7A0-12D3BE8EC490%7D/uploads/CSDCMACPFE_Instructions_4.15.2025.pdf","label":"Official source (winslowtwpfd.org)"}]$j$::jsonb, $t$Winslow Township is the LEA for Chesilhurst Borough.$t$, $t$ec6c0c8062f169f39208500ee9561c5afd6cc18c70eb6f47b4f5b504ce6d43fa$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online"],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":5,"q_ok":5,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0410.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0410.json. Red flag: town certificate not confirmed online$t$, true),
  ($t$0412$t$, $t$Collingswood Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (CO) Resale / Exterior Resale Certification (Exterior Housing Code Inspection, Borough Ordinance 227-3)$t$, $j$["Issued by: Collingswood Fire Department, Office of Fire Prevention & Inspection Bureau","Contact: 856-854-7447 x101 · fireprevention@collingswood.com","How to apply: Use the combined 'Residential Inspection for Sale of Property Application' (covers both the exterior resale certificate and the fire CSACMAPFEC). Print, complete and deliver it with a check or money order payable to 'Borough of Collingswood' to the Fire Prevention & Inspection Bureau, 434 Haddon Avenue, Collingswood NJ 08108. One check may cover both inspections. Call 856-854-7447 to schedule (inspections Tuesday, Wednesday or Thursday, AM or PM). Get the Construction Permit Affidavit and Zoning Official Affidavit in the packet signed.","Valid for: 6 months from the date of inspection, or one change of ownership","Exterior only: sidewalks, walkways, curbing, driveways and aprons, exterior stairs and handrails, house numbers","Sidewalks and walkways free of trip hazards (1/2 inch or more height difference between blocks, or cracks 1/4 inch or wider); bad blocks replaced, not patched; Public Works permit needed","Curbs free of disintegration and cracks over 1/2 inch","Driveways in good condition, at least 9 by 18 feet; dirt, grass, gravel, stone or shell surfaces not allowed","Exterior stairs with more than 4 risers or over 30 inches high need handrails and guards","House numbers at least 3 1/2 inches high, readable from the street","Repairs must be finished within 30 days of notice; a shade tree permit is needed if trees are in the curb strip","No open construction permits and no outstanding zoning violations (signed affidavits from the Construction Office and Zoning Office)","Also: Construction Permit Affidavit: Construction Office must certify there are no open permits.","Also: Zoning Official Affidavit: Zoning Office must certify there are no outstanding zoning violations.","Also: Sidewalk/curb repair permit: Owner must get a Public Works permit before sidewalk or curb repairs; Shade Tree Commission permit if trees are in the curb strip. Public Works: 856-854-0533."]$j$::jsonb, $j$[{"label":"Exterior resale inspection","amount":"$ 50.00"},{"label":"Re-inspection (applies to all re-inspections)","amount":"$50.00"},{"label":"Returned check processing fee","amount":"$20.00"}]$j$::jsonb, $t$https://www.collingswood.com/Residential%20Inspection%20for%20Sale%20of%20Property%20Application%202025.pdf?t=202504071408130$t$, $t$https://www.collingswood.com/government/departments/property_maintenance_nuisance_cos.php$t$, $j$[{"url":"https://www.collingswood.com/government/departments/property_maintenance_nuisance_cos.php","label":"Official source (collingswood.com)"},{"url":"https://www.collingswood.com/Residential%20Inspection%20for%20Sale%20of%20Property%20Application%202025.pdf?t=202504071408130","label":"Official source (collingswood.com)"}]$j$::jsonb, $t$There are several types of Certificates of Occupancy (COs). This type is required at the time of resale of any property in the Borough of Collingswood. The criteria for this CO are contained in Chapter 227-3 of the Collingswood Code$t$, $t$29ffc6f606dc123593bfbd389030aa3d9b38d6e0959240f165fed86e95c1a38a$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":6,"q_ok":6,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0412.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0412.json$t$, true),
  ($t$0415$t$, $t$Gloucester Township$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Fire District #1 (Glendora area): issued by Gloucester Township Fire District #1 Bureau of Fire Prevention (Glendora Fire Company) (fire district). Check the property's fire district in the 'Special Taxing Districts' block at https://wipp.edmundsassoc.com/Wipp/?wippid=0415","Fire District #1 (Glendora area) contact: 856-939-1177 · gtfm81@comcast.net","Fire District #1 (Glendora area), apply: 10 or more business days before settlement for the lowest fee","Fire District #1 (Glendora area), how to apply: Download the District 1 smoke application (08-2025 version) from the district's forms page, and mail it with cash or check payable to GTFD1 to PO Box 38, Glendora, NJ 08029. Fees are based on business days.","Fire District #2 (Chews Landing area): issued by Gloucester Township Fire District #2 Bureau of Fire Prevention (Chews Landing Fire Department) (fire district). Check the property's fire district at https://wipp.edmundsassoc.com/Wipp/?wippid=0415","Fire District #2 (Chews Landing area) contact: 856-282-3370 ext. 124 · gtfm82@gtfd2.com","Fire District #2 (Chews Landing area), apply: 10 or more business days before settlement (not counting settlement day) for the lowest fee","Fire District #2 (Chews Landing area), how to apply: Download the application (Word file) from the Fire Prevention Bureau page, fill it in (include lockbox code if vacant), and submit it with exact cash or a check payable to GTFD#2 to 43 Somerdale Road, Blackwood, NJ 08012 (fax 856-545-7485, email gtfm82@gtfd2.com). Appointments are given as a two-hour window. Call the Fire Prevention Office to schedule a re-inspection after a failure.","Fire District #3 (Blenheim area): issued by NJ DCA Division of Fire Safety, Bureau of Fire Code Enforcement (for Gloucester Township Fire District #3, Blenheim) (NJ DCA, state). Check the property's fire district at https://wipp.edmundsassoc.com/Wipp/?wippid=0415","Fire District #3 (Blenheim area) contact: 609-633-6132 · BFCE_CSDCMAC@dca.nj.gov","Fire District #3 (Blenheim area), apply: More than 10 business days before closing for the lowest fee","Fire District #3 (Blenheim area), how to apply: Apply online through the DCA Fire Safety portal ('Apply For Smoke Certification'). The applicant checks off each placement and operating requirement, pays by e-check or credit card before submitting, and the certificate is emailed once the fee is paid and any required inspections are done. A valid email address is required. Electric-heat homes with no CO requirement should email BFCE_CSDCMAC@dca.nj.gov.","Fire District #4 (Blackwood area): issued by Gloucester Township Fire District #4 Bureau of Fire Prevention (Blackwood Fire Company) (fire district). Check the property's fire district at https://wipp.edmundsassoc.com/Wipp/?wippid=0415","Fire District #4 (Blackwood area) contact: 856-227-7037 · fm84@gtfd4.org","Fire District #4 (Blackwood area), apply: 10 or more business days before settlement for the lowest fee","Fire District #4 (Blackwood area), how to apply: Download the Smoke Detector/CO application, and mail it with cash or check payable to GTFD4 to 14 West Central Avenue, Blackwood, NJ 08012. To schedule, email fm84@gtfd4.org or call 856-227-7037 with the address, preferred dates and a contact phone. Office hours Monday to Thursday 8 am to 4 pm.","Fire District #5 (Lambs Terrace / Sicklerville area): issued by Gloucester Township Fire District #5 Bureau of Fire Prevention (Lambs Terrace Fire Company) (fire district). Check the property's fire district at https://wipp.edmundsassoc.com/Wipp/?wippid=0415","Fire District #5 (Lambs Terrace / Sicklerville area) contact: 856-228-0678","Fire District #5 (Lambs Terrace / Sicklerville area), apply: 10 or more business days before settlement for the lowest fee","Fire District #5 (Lambs Terrace / Sicklerville area), how to apply: Download the Smoke Application from the district's Forms & Applications page and mail it with cash or check payable to GTFD5 to 1781 Sicklerville Rd., Sicklerville, NJ 08081 (fax 856-374-0424).","Fire District #6 (Erial area): issued by Gloucester Township Fire District No. 6 Bureau of Fire Prevention (Erial) (fire district). Check the property's fire district at https://wipp.edmundsassoc.com/Wipp/?wippid=0415","Fire District #6 (Erial area) contact: 856-435-0700 · Inspections@gtfd6.com","Fire District #6 (Erial area), apply: 10 or more business days before settlement for the lowest fee; affidavits are processed once a week","Fire District #6 (Erial area), how to apply: For a sale, the owner or agent completes and signs the district's CSACMAPFEC affidavit (self-certification in lieu of inspection under N.J.A.C. 5:70-2.3(b)) and emails it to Inspections@gtfd6.com or drops it off at 1946 Williamstown-Erial Road, Sicklerville (mailbox if no one is there). Pay by cash or check payable to GTFD6; no certificate until paid. Affidavits are processed once a week. Rentals with a new tenant are inspected in person. Certificate valid 6 months, not transferable.","Fire official in the NJ state directory (fire district), updated 6/25/2025: Brandon O'Connor · (856) 227-7731 · fm84@gtfd4.org","Fire official in the NJ state directory (NJ DCA, state), updated 2/9/2026: Louis Kilmer · (609) 633-6132","Fire official in the NJ state directory (fire district), updated 3/16/2026: Kenneth Young · (856) 282-3370 · gtfm82@gtfd2.com","Districts 1, 2, 4 and 5: CO alarms must be less than 7 years old","Districts 1, 4 and 5: smoke alarms older than 10 years not accepted; battery alarms must be 10-year sealed (hardwired exempt); hardwired alarms cannot be replaced with battery alarms","Basement smoke alarm at the bottom of the stairwell on the ceiling (not between joists); hallway alarms within 10 feet of all bedroom doors","House numbers at least 4 inches high, contrasting color, permanently on the house and visible from the street (mailbox or light post numbers not accepted)","Homes with a secondary power source (solar, generator, battery storage) need a non-handwritten 'CAUTION: MULTIPLE SOURCES OF POWER' label within 18 inches of the main electrical panel and the electric meter","District 5 checklist: alarm type follows the year the house was built (for example 1991 to present: hardwired interconnected alarms with battery backup on every level and in each bedroom)","Current 2025-2026 district forms do not list a fire extinguisher (District 6's 2026 affidavit title still says 'Portable Fire Extinguisher' but its checklist has no extinguisher item)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Fire District #1 (Glendora area): 10 or more business days before settlement","amount":"$45.00"},{"label":"Fire District #1 (Glendora area): 4 to 9 business days before settlement","amount":"$90.00"},{"label":"Fire District #1 (Glendora area): Less than 4 business days before settlement","amount":"$161.00"},{"label":"Fire District #1 (Glendora area): Re-inspection or failure to appear","amount":"$45.00"},{"label":"Fire District #2 (Chews Landing area): 10 or more business days before settlement","amount":"$35.00"},{"label":"Fire District #2 (Chews Landing area): 5 to 9 business days before settlement","amount":"$70.00"},{"label":"Fire District #2 (Chews Landing area): 4 or fewer business days before settlement (done as manpower permits)","amount":"$125.00"},{"label":"Fire District #3 (Blenheim area): More than 10 business days before closing","amount":"$45"},{"label":"Fire District #3 (Blenheim area): 4 to 10 business days before closing","amount":"$90"},{"label":"Fire District #3 (Blenheim area): Less than 4 business days before closing","amount":"$161"},{"label":"Fire District #4 (Blackwood area): 10 or more business days before settlement","amount":"$45.00"},{"label":"Fire District #4 (Blackwood area): 4 to 9 business days before settlement","amount":"$90.00"},{"label":"Fire District #4 (Blackwood area): Less than 4 business days before settlement","amount":"$161.00"},{"label":"Fire District #4 (Blackwood area): Re-inspection or failure to appear","amount":"$45.00"},{"label":"Fire District #5 (Lambs Terrace / Sicklerville area): 10 or more business days before settlement","amount":"$45.00"},{"label":"Fire District #5 (Lambs Terrace / Sicklerville area): 4 to 9 business days before settlement","amount":"$90.00"},{"label":"Fire District #5 (Lambs Terrace / Sicklerville area): Less than 4 business days before settlement","amount":"$161.00"},{"label":"Fire District #5 (Lambs Terrace / Sicklerville area): Re-inspection or failure to appear","amount":"$45.00"},{"label":"Fire District #6 (Erial area): 10 or more business days before settlement","amount":"$35.00"},{"label":"Fire District #6 (Erial area): 4 to 9 business days before settlement","amount":"$70.00"},{"label":"Fire District #6 (Erial area): Fewer than 4 business days before settlement","amount":"$125.00"}]$j$::jsonb, $t$https://img1.wsimg.com/blobby/go/3bf548b5-402d-4490-8fd3-def7b989165b/downloads/e04298d2-df83-4cf5-af43-ddc780efee15/Township%20Smoke%20Application%2008-2025.pdf?ver=1789009271453$t$, $t$https://glotwpnjfd1.gov/district-forms$t$, $j$[{"url":"https://glotwp.com/department/fire-departments/","label":"Official source (glotwp.com)"},{"url":"https://img1.wsimg.com/blobby/go/3bf548b5-402d-4490-8fd3-def7b989165b/downloads/e04298d2-df83-4cf5-af43-ddc780efee15/Township%20Smoke%20Application%2008-2025.pdf?ver=1789009271453","label":"Official source (img1.wsimg.com)"},{"url":"https://gtfd2.org/?page_id=4","label":"Official source (gtfd2.org)"},{"url":"https://gtfd2.org/wp-content/uploads/2025/04/Application-CO-Insp.docx","label":"Official source (gtfd2.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://firesolutions.dca.nj.gov/ultra-fire-home/smoke-application-create/","label":"Official source (firesolutions.dca.nj.gov)"},{"url":"https://gtfd4.org/fire-prevention","label":"Official source (gtfd4.org)"}]$j$::jsonb, $t$The Township of Gloucester is served by six separate Boards of Fire Commissioners, known as Gloucester Township Fire District #1 through Gloucester Township Fire District #6$t$, $t$576a7324593076ccbc135dc79e9b98b765fea6a721fa3092194e1033dcae2862$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online"],"verification":{"fees":21,"fee_ok":14,"fee_bad":0,"fee_unchecked":7,"quotes":12,"q_ok":10,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0415.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0415.json. Red flag: town certificate not confirmed online$t$, true),
  ($t$0416$t$, $t$Haddon Township$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance (COC) / Temporary Certificate of Compliance (TCOC), Residential Resale Inspection (Township Code Chapter 186)$t$, $j$["Issued by: Construction & Zoning Office / Code Official (Township Annex, 10 Reeve Ave.)","Contact: 856-833-6265 · rsheppard@haddontwp.com","Apply: Application in and paid at least 14 business days before closing; inspections Mondays and Wednesdays 8 to 10 AM","How to apply: Download the Residential Resale / Tenant Change Inspection Application (PDF) or use the township's online GovPilot form (https://main.govpilot.com/web/public/474cdd15-dbc_Rental-Resale-Township-of-Haddon?uid=7071&ust=NJ&pu=1&id=0). Submit it with a check or money order payable to 'Township of Haddon' to the Annex Building, 10 Reeve Ave., at least 14 business days before closing. Questions: Ryan Sheppard, rsheppard@haddontwp.com.","Valid for: 6 months (if the sale does not happen within 6 months a new application, fee and inspection are required)","Interior and exterior inspection under the township Land Use code, International Property Maintenance Code and NJ fire code; includes the smoke/CO (CSDCMAC) check","House numbers: numerals only, at least 4 inches, contrasting color, on the house (not doors or mailboxes)","Smoke alarms on every level on the ceiling, at the base of basement stairs, within 10 feet of all bedrooms; no more than 10 years old; 10-year sealed battery where battery units are allowed; hardwired alarms cannot be replaced with battery alarms","CO alarm in the hallway within 10 feet of all bedrooms, less than 10 years old","Thumb-turn locks on all exit doors; no keyed locks on the egress side","Gutters, downspouts with splash blocks, roof, soffit, fascia, siding and paint in good repair","Guardrails on porches, decks and landings over 30 inches; handrails on steps with 3 or more risers","Sidewalk, driveway and apron level with no trip hazards; replacement rather than patching","GFCI outlets trip; outlet, switch and junction box covers in place; electrical panel covered, no open spaces, circuits labeled","Faucets hot on left, cold on right, no leaks; sink strainers; stove anti-tip device","Sump pump discharges outside, not into the sanitary sewer; water meter installed and accessible","Metal dryer vent; proper water heater and furnace venting; water heater bonding; oil heat emergency shut-off switch with red label","Attached garage walls/ceiling next to living space drywalled and taped","Bathroom window or working exhaust fan; screens installed","Pool barrier 5 to 6 feet with self-closing, self-latching gate","All permitted work must have final inspections and a Certificate of Approval (heater, water heater, finished basement, roof, siding, deck, etc.)","Also: Open permits must be closed: Any work that needed a permit must have had one, with final inspections done and a Certificate of Approval issued.","Also: Water meter: Water meter must be installed, connected and accessible at inspection."]$j$::jsonb, $j$[{"label":"COC application more than 14 business days before change of ownership","amount":"$150"},{"label":"COC application more than 7 but less than 13 business days before","amount":"$175"},{"label":"COC application more than 4 but less than 6 business days before","amount":"$200"},{"label":"COC application less than 4 business days before","amount":"$225"},{"label":"COC application after the change of ownership","amount":"$250"},{"label":"Re-inspection (paid before re-inspection is scheduled)","amount":"$25.00"},{"label":"First re-inspection after a Temporary COC","amount":"$25"},{"label":"Second re-inspection after a Temporary COC","amount":"$50"},{"label":"Third re-inspection after a Temporary COC","amount":"$75"},{"label":"Fourth or later re-inspection after a Temporary COC, each","amount":"$100"}]$j$::jsonb, $t$https://www.haddontwp.com/wp-content/uploads/2026/06/Resale-Tenant-Change-Inspection-Form.pdf$t$, $t$https://www.haddontwp.com/departmets/construction-office/$t$, $j$[{"url":"https://www.haddontwp.com/wp-content/uploads/2026/06/Resale-Tenant-Change-Inspection-Form.pdf","label":"Official source (haddontwp.com)"},{"url":"https://www.haddontwp.com/departmets/construction-office/","label":"Official source (haddontwp.com)"}]$j$::jsonb, $t$A Residential Property Inspection MUST be completed and a COC or Temporary COC MUST be issued PRIOR to closing per Township of Haddon Municipal Code Chapter 186-6 Article 3B.$t$, $t$c1ad30c9a2cf78deda897075666e6408122337b2826f45f1a8b2d24f6f41751d$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":0,"fee_bad":0,"fee_unchecked":10,"quotes":6,"q_ok":2,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0416.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0416.json$t$, true),
  ($t$0416$t$, $t$Haddon Township$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Haddon Township Construction & Zoning Office / Code Official (smoke and CO check done as part of the township Resale COC inspection) (town fire bureau)","Contact: 856-833-6265 · rsheppard@haddontwp.com","Apply: At least 14 business days before closing","How to apply: No separate smoke certificate application or fee was found. The Residential Resale / Tenant Change Inspection Application covers the smoke/CO (CSDCMAC) check together with the COC; see the the town certificate fees ($150 and up).","Fire official in the NJ state directory (town), updated 5/19/2026: William A Behnke · (856) 854-1176 · wbehnke@haddontwp.com;","Smoke alarms no more than 10 years old; 10-year sealed battery units where battery units are allowed; hardwired alarms cannot be replaced with battery alarms","CO alarms less than 10 years old, in the hallway within 10 feet of all bedrooms","Homes with a low-voltage fire alarm system must have it tested by a certified alarm contractor before the inspection and show the certificate","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.haddontwp.com/wp-content/uploads/2026/06/Resale-Tenant-Change-Inspection-Form.pdf$t$, $t$https://www.haddontwp.com/departmets/construction-office/$t$, $j$[{"url":"https://www.haddontwp.com/wp-content/uploads/2026/06/Resale-Tenant-Change-Inspection-Form.pdf","label":"Official source (haddontwp.com)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$I understand that any change of ownership/occupancy including storage of personal property may not occur, prior to successful inspection & possession of a (CSDCMAC) inspection.$t$, $t$7df36868a7bf593acb89a2a355831590c7cab5c499333f85bcb91ef51fbbece8$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":0,"fee_bad":0,"fee_unchecked":10,"quotes":6,"q_ok":2,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0416.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0416.json$t$, true),
  ($t$0417$t$, $t$Haddonfield Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale CO (made up of the Fire Marshal smoke detector certificate of compliance plus the sidewalk inspection certificate of compliance)$t$, $j$["Issued by: Borough of Haddonfield Construction and Zoning Office (Community Development), with the Bureau of Fire Prevention (Fire Marshals) and the Sidewalk Inspector","Contact: 856-429-4700 · SKrohn@haddonfield-nj.gov","Apply: Notify the Borough at least 30 days before transfer of title (or within 5 days of signing the sales contract, whichever is later) for the sidewalk inspection. Lower fees apply if applications are submitted more than 10 business days before settlement.","How to apply: Submit the Smoke Detector form, Sidewalk Inspection form and (if in the Historic District) the Historic District Disclosure form to the Construction and Zoning Office, Room 104, Borough Hall, 242 Kings Highway East, with the fees in cash or check payable to the Borough of Haddonfield. Staff check permit history first. Schedule the smoke inspection directly with the Fire Marshal. Sidewalk inspections happen Tuesdays and Thursdays without an appointment; results are emailed.","Valid for: 90 days","All construction permits must be inspected and closed before the CO is released","Sidewalks, driveway aprons and walkways in the public right-of-way free of trip hazards (no lifts, holes or height differences of 1/2 inch or more)","Sidewalk repairs completed and the Borough notified at least 7 days before title transfer, or money placed in escrow and repairs done within 30 days after closing","Smoke alarm on every level (10-year sealed battery if battery powered)","CO alarm outside the bedroom area","ABC portable fire extinguisher no larger than 10 lb, within 10 feet of the kitchen","Street number at least 4 inches, contrasting and readable from the street","Historic District disclosure form if the home is in the Historic District","Also: Open construction permits must be closed: Staff check permit history; all permits must be inspected and closed before the Resale CO is released, and no smoke inspection is scheduled while permits are open.","Also: Sidewalk and driveway apron inspection: Required on every sale; repairs or escrow before closing.","Also: Historic District disclosure: Buyers must be notified if the property is in the Historic District (Ch. 135-60). No fee.","Also: Move-out/move-in trash pickup: Schedule with Public Works at 856-429-0183 before putting out excess trash."]$j$::jsonb, $j$[{"label":"Sidewalk inspection, settlement more than 10 business days away (includes first re-check after repairs)","amount":"$50"},{"label":"Sidewalk inspection, settlement less than 10 business days away","amount":"$75"},{"label":"Sidewalk re-inspection, each (beyond the first re-check)","amount":"$25.00"},{"label":"Sidewalk late notice fee, each failure to give timely notice","amount":"$25.00"},{"label":"Historic District Disclosure Form","amount":"no fee"}]$j$::jsonb, $t$https://www.haddonfieldnj.org/Community%20Development/Sidewalk%20Inspection%20-%20Sale%20of%20Home%20-%20Application%20Form%20-%20Jan%202025.pdf?t=20260518153417071$t$, $t$https://www.haddonfieldnj.org/government/departments/community_development_and_construction/resale___rental_co_information.php$t$, $j$[{"url":"https://www.haddonfieldnj.org/government/departments/community_development_and_construction/resale___rental_co_information.php","label":"Official source (haddonfieldnj.org)"},{"url":"https://www.haddonfieldnj.org/Community%20Development/Sidewalk%20Inspection%20-%20Sale%20of%20Home%20-%20Application%20Form%20-%20Jan%202025.pdf?t=20260518153417071","label":"Official source (haddonfieldnj.org)"},{"url":"https://www.haddonfieldnj.org/government/departments/fire_department/smoke_detector___sidewalk_inspection_requests/index.php","label":"Official source (haddonfieldnj.org)"}]$j$::jsonb, $t$Selling a Home in the Borough of Haddonfield Resale CO 1. Smoke Detector Form / Fire Marshall CO Inspection$t$, $t$7c020edbbb4ac098da374070061375241398678d9a20f55130f263cbfcbf3a79$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":10,"fee_ok":10,"fee_bad":0,"fee_unchecked":0,"quotes":9,"q_ok":9,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0417.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0417.json$t$, true),
  ($t$0422$t$, $t$Lindenwold Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Continued Occupancy (CCO); Certificate of Transfer of Title (CTT) for vacant or rehab properties$t$, $j$["Issued by: Borough of Lindenwold Construction Office / Code Enforcement (Housing Clerk)","Contact: 856-783-2121 ext. 224 · hprotich@lindenwold.net","Apply: Not stated as a fixed deadline. The fee is lower if the inspection is scheduled 10 or more business days out. For a vacant CTT, call 5 to 7 business days before settlement for a pre-inspection.","How to apply: Fill out the one-page CCO application and submit it to the Code Enforcement Office at 15 N. White Horse Pike with a check or money order payable to the Borough of Lindenwold. Fees are per unit and nonrefundable. The Borough calls the listed contact to schedule after the permit and zoning search is done. A failed inspection needs a new application and fee before reinspection. For vacant or rehab properties, file the CTT and the CCO at the same time.","No open building or zoning permits (must be closed with fees paid)","No work done without a required construction or zoning permit","No unsafe structures or unsafe conditions","10-year sealed battery smoke alarm on every level and outside each sleeping area","CO alarm within 10 feet of sleeping areas","2A-10B:C fire extinguisher under 10 lbs, mounted within 10 ft of kitchen, tagged with current receipt","House numbers at least 4 inches, contrasting, fixed to the house and visible from the street","Handrails on 3 or more risers; guardrails on porches/decks 30 inches or higher","GFCI within 6 ft of water; no bare-wire fixtures","Heat, appliances (anti-tip on range), hot and cold water and toilets working","Water heater relief valve discharge pipe 2 to 6 inches from floor","Bathroom window or exhaust fan","No holes, flaking paint or water stains on walls, ceilings, floors; no roof leaks","Yard free of trash, debris and junk vehicles; all code violations abated","Utilities on at time of inspection","Also: Open permits must be closed: No open building or zoning permits; must be fully satisfied with fees and inspections before the CCO is issued.","Also: Work without permits: Unpermitted work (commonly finished basements, water heaters, furnaces) must be permitted and inspected before the CCO is issued.","Also: Zoning check: The Borough runs a zoning approval and permit search before scheduling the CCO inspection."]$j$::jsonb, $j$[{"label":"CCO inspection, 1-2 units, scheduled over 10 days out (form: 10 or more business days), per unit","amount":"$75"},{"label":"CCO inspection, scheduled less than 10 days out (form: 4 to 10 business days), per unit","amount":"$100"},{"label":"Re-inspection, per unit","amount":"$50"},{"label":"Administration fee for changing inspection date or unit number more than once","amount":"$20"},{"label":"Certificate of Transfer of Title (vacant property), includes one re-inspection within 120 days","amount":"$125"}]$j$::jsonb, $t$https://www.lindenwoldnj.gov/DocumentCenter/View/140/Residential-Property-Sales---Inspection-Application--CCO-Certificate-of-Continued-Occupancy-PDF$t$, $t$https://www.lindenwoldnj.gov/178/Code-Enforcement-Housing$t$, $j$[{"url":"https://www.lindenwoldnj.gov/178/Code-Enforcement-Housing","label":"Official source (lindenwoldnj.gov)"},{"url":"https://www.lindenwoldnj.gov/DocumentCenter/View/140/Residential-Property-Sales---Inspection-Application--CCO-Certificate-of-Continued-Occupancy-PDF","label":"Official source (lindenwoldnj.gov)"},{"url":"https://www.lindenwoldnj.gov/DocumentCenter/View/141/Residential-Property-Sales---Inspection-Application--CTT-Certificate-of-Title-Transfer--for-Vacant-or-Rehab-Properties-PDF","label":"Official source (lindenwoldnj.gov)"}]$j$::jsonb, $t$All sales of a property must file for a certificate of occupancy (C/O) inspection for smoke detectors, carbon monoxide detectors, fire extinguishers, and house numbers.$t$, $t$e4f88bddf501b96bde5e1a043dbc36b5a1bead8a5dd65d5a07f8a7a795d3641e$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":10,"q_ok":10,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0422.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0422.json$t$, true),
  ($t$0427$t$, $t$Pennsauken Township$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Housing Resale Certificate of Inspection (Housing Resale CO)$t$, $j$["Issued by: Department of Housing / Property Maintenance","Contact: 856-665-1000 ext. 1411 · spaul@pennsauken.gov","Apply: No fixed number of days published. The town says to leave enough time between the inspection and settlement so the certificate is issued before settlement.","How to apply: Complete the Housing Resale & Fire Certificate Inspection application (PDF) or apply online through the township's GovPilot portal. Submit the form with the $175 fee (cash, check or money order payable to Pennsauken Township) to the Municipal Building, Attn: Housing / Property Maintenance Dept., 5605 N. Crescent Blvd., Pennsauken, NJ 08110. The inspection is scheduled once the form and fee are received.","Interior and exterior housing resale inspection of every 1 and 2 family dwelling","Grading and drainage, sidewalks and driveways, accessory structures","Stumps from trees that caused sidewalk damage","Exterior structure: protective treatment, structural members, foundation walls, roofs and drainage","Roof certification and chimney certification (wood burning or gas) may be required","Stairways, decks, porches and balconies; handrails and guards","Interior surfaces, stairs and walking surfaces","Infestation / termite","Plumbing system hazards and plumbing certification","Mechanical appliances and mechanical certification","Electrical hazards and electrical certification; 2 outlets in every bedroom; GFCI style protection near sinks, sump pump, bathrooms, kitchen counters; weather resistant covered outdoor outlets","Smoke alarms, carbon monoxide detector, interior locked doors","Shed letter if there is a shed; grass or weeds","Rental registration if the property will be rented","New or open permits must be closed; no new occupancy until the final CO is issued","Also: Open and required construction permits must be closed: All permits must be obtained, inspected and pass inspection before the final Certificate of Inspection is issued. Construction dept: 856-665-1000 x129, building@pennsauken.gov.","Also: Temporary CO by buyer affidavit: Buyer may sign a notarized Affidavit for a Temporary CO, accepting responsibility for violations; must be delivered to Housing before settlement.","Also: Rental registration if buyer will rent: Checklist item 251.19 rental registration required; 1-2 family rentals register annually and are inspected."]$j$::jsonb, $j$[{"label":"Housing Resale CO plus Fire Certificate, combined application fee","amount":"$175.00"},{"label":"Housing Resale Certificate of Inspection portion","amount":"$100"}]$j$::jsonb, $t$https://www.pennsauken.gov/DocumentCenter/View/1116/Housing-Resale-And-Fire-Cert-Inspection-Application-PDF$t$, $t$https://www.pennsauken.gov/194/Housing-Property-Maintenance$t$, $j$[{"url":"https://www.pennsauken.gov/194/Housing-Property-Maintenance","label":"Official source (pennsauken.gov)"},{"url":"https://www.pennsauken.gov/DocumentCenter/View/1154/Housing-Resale-And-Fire-Cert-Inspection-Information-PDF","label":"Official source (pennsauken.gov)"},{"url":"https://www.pennsauken.gov/DocumentCenter/View/1406/Housing-Resale-Inspection-Checklist-PDF","label":"Official source (pennsauken.gov)"},{"url":"https://www.pennsauken.gov/DocumentCenter/View/1116/Housing-Resale-And-Fire-Cert-Inspection-Application-PDF","label":"Official source (pennsauken.gov)"}]$j$::jsonb, $t$For Residential Housing Sales, A housing resale CO and fire certificate is required for every transfer of ownership for all one and/or two-family dwellings. To obtain the CO and fire certificate the property must pass a housing resale inspection.$t$, $t$e8220170d559b8eb03cd2867d2cc6b9d3d2afe401ce8bc680e946cfb6d51ddf7$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":6,"q_ok":6,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0427.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0427.json$t$, true),
  ($t$0428$t$, $t$Pine Hill Borough$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Pine Hill Fire District #1, Bureau of Fire Prevention (fire district)","Contact: 856-784-0030 · firemarshal@pinehillfiredistrict.com","Apply: More than 10 business days before the inspection date for the lowest fee; inspections are done one day a week","How to apply: Fill out the application in the Smoke Detector Inspection Packet and mail it or drop it off with a check or money order (no cash) at the Bureau of Fire Prevention, 1109 Erial Road, Pine Hill, NJ 08021. The form and payment must be received before an appointment is scheduled; the office then contacts you. If dropping off, put it in the mailbox and send a follow-up email. The office is part time, so email firemarshal@pinehillfiredistrict.com for a faster reply. Fees are non-refundable.","Fire official in the NJ state directory (fire district), updated 3/5/2026: Robert Fowler · (856) 784-0030 · firemarshal@pinehillfiredistrict.com","Power to the house must be on before scheduling, or an approved Special Circumstance form (extra fee, plus a follow-up inspection or electrician letter before anyone moves in)","Smoke alarm on every level within 15 feet of the bedrooms","Smoke alarms older than 10 years must be replaced before inspection","Hardwired smoke alarms must stay and cannot be replaced with battery alarms","CO alarm in the hallway within 10 feet of all bedroom doors; CO alarms older than 7 years must be replaced; not plugged into switched outlets or near floor molding","Fire extinguisher rated 2A10BC (5 lbs), brand new or dated/tagged for the current year, mounted visibly within 10 feet of the kitchen or toward an exit from the kitchen","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"More than 10 business days before inspection","amount":"$45.00"},{"label":"5 to 9 business days before inspection","amount":"$90.00"},{"label":"4 or less business days before inspection","amount":"$161.00"},{"label":"Re-inspection","amount":"$20.00"},{"label":"Special Circumstance (power off with hardwired alarms): additional fee on top of the normal fee, same tiers, e.g. 10+ business days","amount":"$45.00"},{"label":"Penalty for occupying without the required follow-up inspection (Special Circumstance cases)","amount":"$500.00"}]$j$::jsonb, $t$https://pinehillfiredistrict.com/wp-content/uploads/2025/11/Smoke-Detector-Inspection-Packet.pdf$t$, $t$https://pinehillfiredistrict.com/department-list/inspection-office/$t$, $j$[{"url":"https://pinehillfiredistrict.com/wp-content/uploads/2025/11/Smoke-Detector-Inspection-Packet.pdf","label":"Official source (pinehillfiredistrict.com)"},{"url":"https://pinehillfiredistrict.com/department-list/inspection-office/","label":"Official source (pinehillfiredistrict.com)"},{"url":"https://web.archive.org/web/20240718161949/https://www.pinehillboronj.com/departments/construction-office/","label":"Official source (web.archive.org)"}]$j$::jsonb, $t$Application for Certification of Smoke Detector and carbon Monoxide Alarm Compliance as required by N.J.A.C 5:70-2.3, based upon the amount of time remaining before the date of inspection as follows:$t$, $t$331eadf9cb614dd572858f7daef80941462e60492443ffd5b765b0aa01ecd9b0$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":true,"flag_reasons":["town certificate not confirmed online"],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":4,"q_ok":4,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0428.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0428.json. Red flag: town certificate not confirmed online$t$, true),
  ($t$0431$t$, $t$Somerdale Borough$t$, $t$CAMDEN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Compliance / Certificate of Continued Occupancy (CCO), Residential Safety Inspection$t$, $j$["Issued by: Office of the Fire Marshal (Somerdale Fire Prevention Bureau)","Contact: 856-783-6320 ext. 2100 · dmarx@somerdale-nj.com","Apply: Apply 11 or more working days before settlement for the lowest fee","How to apply: Fill out the Application for Certificate of Compliance, Single Family Dwelling completely and submit it with a check or money order payable to the Somerdale Fire Prevention Bureau. Contact the Fire Marshal's office at 856-783-6320 ext. 2100 or dmarx@somerdale-nj.com. Borough Hall is at 105 Kennedy Blvd, open Mon to Thu 8 AM to 5:15 PM, closed Friday.","A representative must be on location for the inspection","Lead paint certification for any house built before 1978 (application form; the guideline sheet labels this as for rental properties)","House numbers in Arabic lettering, 3 inches, on the front wall or porch, 30 inches above ground","Smoke alarm on each floor and in each bedroom; 10-year sealed battery alarms where none exist or when replacing battery alarms; hardwired alarms may not be replaced with battery alarms","Carbon monoxide detector on each floor","2A/10BC fire extinguisher, not over 10 lbs, wall mounted about 5 ft from the ground (waist level accepted), within 10 ft of the kitchen and in view","Sidewalks and driveways with no cracks or unevenness, no skim coating or ramping; must be visible and clear of snow, ice and parked cars","Front and rear porch or deck well maintained and sturdy","Windows operable and in decent condition","Firmly secured railing on stairs with 4 or more steps","Water check: toilets flush, drains work, hot water","Covers on all light switches and receptacles","No holes in walls, floors or ceilings; painted","Sump pump must not be tied into the sewer","Yard and property maintained (grass cut, trimmed)","Secondary power source labels on electric panel and meter if there is solar or a generator; solar panels and EV chargers must have been permitted","Any open permits must be closed / finalized","Also: Open permits must be closed: Any open permits must be closed / finalized; solar panels and EV chargers must have been permitted.","Also: Lead paint certification for pre-1978 homes: The single family application states any house built before 1978 must have a lead paint certification provided (citing N.J. P.L. 2021, c. 182, the rental lead law)."]$j$::jsonb, $j$[{"label":"Single family, 11+ working days before settlement","amount":"$70.00"},{"label":"Single family, 4 to 10 working days before settlement","amount":"$90.00"},{"label":"Single family, 1 to 3 working days before settlement","amount":"$161.00"},{"label":"Reinspection (each)","amount":"$25.00"}]$j$::jsonb, $t$https://somerdale-nj.com/wp-content/uploads/2026/05/Single-Family-Dewelling.pdf$t$, $t$https://somerdale-nj.com/departments/fire-marshal/$t$, $j$[{"url":"https://somerdale-nj.com/departments/fire-marshal/","label":"Official source (somerdale-nj.com)"},{"url":"https://somerdale-nj.com/departments/construction/","label":"Official source (somerdale-nj.com)"},{"url":"https://somerdale-nj.com/wp-content/uploads/2026/05/Single-Family-Dewelling.pdf","label":"Official source (somerdale-nj.com)"},{"url":"https://somerdale-nj.com/wp-content/uploads/2026/05/Guidelines.pdf","label":"Official source (somerdale-nj.com)"}]$j$::jsonb, $t$The Office of the Fire Marshal is responsible for inspections not only for Special Events, but inspections prior to a new business opening as well as Certificate of Occupancy inspections prior to settlement on the purchase of a home or renting to a tenant.$t$, $t$712ff427d853ec9d85e4d3eb21cf7d3ce3e5d9ba5a925070bb17244d77bec1ad$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":6,"q_ok":3,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0431.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0431.json$t$, true),
  ($t$0436$t$, $t$Winslow Township$t$, $t$CAMDEN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Winslow Township Fire District No. 1 (Winslow Township Fire Department), Fire Prevention Division / Office of the Fire Marshal (fire district)","Contact: 609-561-4225 · firedistrict@winslowtwpfd.org","Apply: Apply 3 to 4 weeks before closing (recommended); fee depends on days of notice; certificate valid 90 days from inspection","How to apply: Apply online on the Fire District website and then pay through the linked Edmunds WIPP payment page, or download the packet and fax it to 609-561-5823, or apply in person at the Fire District Office, 9 Cedar Brook Road, Sicklerville (Monday to Friday, 9 am to 5 pm). Staff call within 24 hours to schedule. Inspections are on Tuesdays and Thursdays in a morning or afternoon block. Pay by check (payable to Winslow Township Fire District), credit card, debit card or money order. All fees are non-refundable.","Fire official in the NJ state directory (fire district), updated 2/6/2026: Joseph G Hahn · (609) 561-4225 · josephh@winslowtwpfd.org","Every smoke alarm must be less than 10 years old; take each alarm down and check the date on the back","Battery (DC) smoke alarms must be 10-year sealed units","Hardwired (110 volt) interconnected alarms must all sound when one is tested; AC power must be on or no inspection is done; replacing a hardwired alarm with a battery unit fails","Smoke alarm type and number depend on the year built (for example 1991 to present: hardwired with battery backup on each level and in each bedroom, interconnected)","CO alarm outside of but within 10 feet of all sleeping areas if there is any fuel-burning appliance, fireplace or attached garage","Homes with a secondary power source (solar, generator, battery storage) need a permanent, not handwritten, 'Caution: Multiple Sources of Power' label at the main panel and the electric meter (ANSI Z535.4)","Monitored low-voltage fire alarm systems must be tested and certified by an alarm contractor before the inspection; bring the certificate","An adult (18+) must be present for the whole inspection; no lockbox entry","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Application, 8 or more days advance notice","amount":"$65.00"},{"label":"Application, 4 to 7 days advance notice","amount":"$100.00"},{"label":"Application, 3 or fewer days notice","amount":"$150.00"},{"label":"Senior citizen (62 or older, proof of age attached) discount line","amount":"$30.00"},{"label":"Re-inspection (per visit)","amount":"$35.00"},{"label":"Missed appointment","amount":"$35.00"}]$j$::jsonb, $t$https://winslowtwpfd.org/online-resale-application$t$, $t$https://winslowtwpfd.org/fire-marshal-office$t$, $j$[{"url":"https://winslowtwpfd.org/vertical/sites/%7B2458775F-59B7-4354-B7A0-12D3BE8EC490%7D/uploads/Smoke_Application_2025.pdf","label":"Official source (winslowtwpfd.org)"},{"url":"https://www.winslowtownship.com/filestorage/3308/3536/3538/3540/RESALECERTIFICATE.pdf","label":"Official source (winslowtownship.com)"},{"url":"https://winslowtwpfd.org/history","label":"Official source (winslowtwpfd.org)"},{"url":"https://winslowtwpfd.org/fire-marshal-office","label":"Official source (winslowtwpfd.org)"},{"url":"https://winslowtwpfd.org/vertical/sites/%7B2458775F-59B7-4354-B7A0-12D3BE8EC490%7D/uploads/CSDCMACPFE_Instructions_4.15.2025.pdf","label":"Official source (winslowtwpfd.org)"}]$j$::jsonb, $t$CERTIFICATIONS ARE VALID FOR 90 DAYS FROM THE DATE OF INSPECTION$t$, $t$b19a6bd8a60f25ef64ae8c43126605ffcdfd786303575c609b3318cf3b338e63$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":9,"fee_bad":0,"fee_unchecked":0,"quotes":9,"q_ok":8,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0436.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0436.json$t$, true),
  ($t$0802$t$, $t$Deptford Township$t$, $t$GLOUCESTER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Housing Change in Ownership inspection / Certificate of Occupancy (Continued Certificate of Occupancy)$t$, $j$["Issued by: Deptford Township Construction Office, Housing Inspector","Contact: 856-845-5300 · constructioninspections@deptford-nj.org","Apply: Allow ten business days for the inspection to be completed","How to apply: Apply online through the Township's SDL portal (linked from the Construction page as the way to apply for a Housing Certificate of Occupancy), or complete the Application for Housing Change in Ownership (mark Resale) and leave it in the drop box outside the Municipal Building at 1011 Cooper Street. Get the Deptford Township MUA approval stamp on the form. Call (856) 845-5300 to schedule the inspection.","Valid for: Inspections are valid for 60 days","Inspection of the entire property under the International Property Maintenance Code, current edition","Inspection under Change in Occupancy rules N.J.A.C. 5:70-2.3 and 4.19 (smoke alarm, CO alarm and fire extinguisher rules) and Township Ordinance 0.2.15","All open construction permits must be completed and closed out before the certificate is issued","Any compliance order or notice of violation must be corrected before the home can be sold or rented","Homes on well or septic need a No Further Action letter from the Gloucester County Department of Health","Deptford Township MUA approval stamp on the application","Also: Deptford Township MUA approval: The resale application has a 'DEPTFORD TOWNSHIP MUA APPROVAL STAMP' box, and asks for the water meter location.","Also: Well or septic: County Health No Further Action letter: If the property has a well or septic, a No Further Action letter from the Gloucester County Department of Health is required before the certificate is issued.","Also: Open permits closed: All work on open construction permits must be completed and permits closed before the certificate of occupancy is issued."]$j$::jsonb, $j$[{"label":"Per unit, includes application, inspection and one re-inspection","amount":"$100 per unit"},{"label":"Each additional re-inspection, per unit","amount":"$75 per unit"}]$j$::jsonb, $t$https://www.deptford-nj.org/filestorage/34753/35668/35670/37913/2025_CHANGE_IN_OCCUPANT_APPLICATION__-_final.pdf$t$, $t$https://www.deptford-nj.org/construction$t$, $j$[{"url":"https://www.deptford-nj.org/filestorage/34753/35668/35670/37913/2025_CHANGE_IN_OCCUPANT_APPLICATION__-_final.pdf","label":"Official source (deptford-nj.org)"},{"url":"https://www.deptford-nj.org/construction","label":"Official source (deptford-nj.org)"}]$j$::jsonb, $t$APPLICATION FOR HOUSING CHANGE IN OWNERSHIP$t$, $t$2e0dbafb07a81f364071cfa31312cebb1086c1e57f30fac18b1b102e283ea7da$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":6,"q_ok":6,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0802.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0802.json$t$, true),
  ($t$0802$t$, $t$Deptford Township$t$, $t$GLOUCESTER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Deptford Township Construction Office, Housing Inspector (checked as part of the Housing Change in Ownership inspection) (town fire bureau)","Contact: 856-845-5300 · constructioninspections@deptford-nj.org","How to apply: No separate smoke certificate application was found. The Township resale housing application says the inspection is done under N.J.A.C. 5:70-2.3 and 4.19 (the state smoke alarm, carbon monoxide alarm and fire extinguisher rules). Under N.J.A.C. 5:70-2.3(a)1, where a town has its own resale inspection, a separate certificate is not required but the town may not issue its certificate until the home meets 5:70-4.19. Confirm with the Construction Office at (856) 845-5300.","Fire official in the NJ state directory (fire district), updated 4/29/2025: Francis E Pote · (856) 848-3098 · fpote@deptfordfd.org","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.deptford-nj.org/filestorage/34753/35668/35670/37913/2025_CHANGE_IN_OCCUPANT_APPLICATION__-_final.pdf$t$, $t$https://www.deptford-nj.org/construction$t$, $j$[{"url":"https://www.deptford-nj.org/filestorage/34753/35668/35670/37913/2025_CHANGE_IN_OCCUPANT_APPLICATION__-_final.pdf","label":"Official source (deptford-nj.org)"},{"url":"https://www.law.cornell.edu/regulations/new-jersey/N-J-A-C-5-70-2-3","label":"Official source (law.cornell.edu)"}]$j$::jsonb, $t$An inspection of the entire property according to: Change in Occupancy Pursuant to N.J.A.C. 5:70 -2.3 and 4.19; Ordinance # 0.2.15 and International Property Maintenance Code, Current Edition$t$, $t$690fc22537da6796b61d13dde03a89f52e97c0dfcb8bcf700952e1bd9cae35c7$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":6,"q_ok":6,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0802.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0802.json$t$, true),
  ($t$0803$t$, $t$East Greenwich Township$t$, $t$GLOUCESTER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: East Greenwich Township Construction Department (checked as part of the resale C.O. housing inspection) (town fire bureau)","Contact: 856-423-0654 ext. 8132 · rsnyder@eastgreenwichnj.com","How to apply: No separate smoke certificate application was found. The Township C.O. inspection checklist includes 'NJAC 5:70-4.19 Smoke detectors, carbon monoxide alarms, and fire extinguisher located in appropriate areas'. Under N.J.A.C. 5:70-2.3(a)1, where a town has its own resale inspection, a separate certificate is not required but the town may not issue its CO until the home meets 5:70-4.19. Confirm with the Construction Department.","Fire official in the NJ state directory (county fire marshal), updated 8/5/2026: Shawn K Layton · (856) 307-7912 · slayton@co.gloucester.nj.us","Township checklist: as of January 1, 2019 all battery smoke detectors must be 10-year sealed battery single station alarms; AC interconnected alarms do not need replacing","Smoke detectors on every level including basement and outside each sleeping area; basement detector near the bottom of the basement stairs","Carbon monoxide alarms in the immediate vicinity of sleeping areas","Fire extinguisher placement is checked on the C.O. inspection","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://drive.google.com/file/d/1KFkcT1ccswtj1lABto9y31QmLIX_Qg9O/view?usp=sharing$t$, $t$https://www.eastgreenwichnj.com/government/construction$t$, $j$[{"url":"https://drive.google.com/file/d/1fyG7txo9ueioQiCUTrqTHq5-3JPFfoIi/view?usp=sharing","label":"Official source (drive.google.com)"},{"url":"https://www.law.cornell.edu/regulations/new-jersey/N-J-A-C-5-70-2-3","label":"Official source (law.cornell.edu)"}]$j$::jsonb, $t$NJAC 5:70-4.19 Smoke detectors, carbon monoxide alarms, and fire extinguisher located in appropriate areas$t$, $t$30cdbb20c458c81ebf48a6c4e74ae2191500b98084f281151339be5723651113$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":1,"fee_bad":0,"fee_unchecked":3,"quotes":6,"q_ok":2,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/0803.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0803.json$t$, true),
  ($t$0804$t$, $t$Elk Township$t$, $t$GLOUCESTER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (C/O inspection)$t$, $j$["Issued by: Elk Township Construction Office, Housing Official","Contact: 856-881-6525 ext. 118 · construction@elktownshipnj.gov","Apply: 30 days advance notice before settlement is required","How to apply: Fill out the Certificate of Occupancy Application and give it to the Construction Office at 680 Whig Lane, Monroeville (in person, in the vestibule drop box, or by mail) with a check payable to 'Elk Township'. Apply at least 30 days before settlement. Inspections are Mondays and Wednesdays; late applications get no special treatment. If the home is sold 'as is', the buyer can sign the Township's notarized as-is letter agreeing to finish repairs within 60 days, and the Township then issues a Settlement Document.","Valid for: 3 months if the property is occupied, 6 months if vacant","Well water: passing test by an NJDEP certified lab (Private Well Testing Act), or County Health letter for a new well","Septic: Gloucester County Health Dept letter of Compliance-No Further Action, or License to Operate for a new system","Cesspools, privies and outhouses must be replaced with a septic system before transfer (limited exceptions)","Smoke detector in each bedroom and on every level (10 year sealed device)","Smoke and CO detectors outside bedrooms, within 10 feet of bedrooms","General condition of interior, exterior, grounds and accessory buildings (sheds, barns, garages)","Roofing, siding, trim, window glass, screens and doors","Pipes and traps under sinks; heater and water heater","Chimney condition; chimney certification for wood fireplaces, wood stoves or pellet stoves","GFCI outlets within 6 feet of water in kitchens, bathrooms and laundry","4 inch reflective house numbers","Township-issued trash and recycling containers on the premises","No open construction permits","Also: Well water test: Passing well water test by an NJDEP certified lab (NJAC 7:9E, Private Well Testing Act), or County Health Dept approval letter for a new well.","Also: Septic certification / cesspool replacement: Gloucester County Health Dept letter of Compliance-No Further Action (or License to Operate for new systems). Cesspools, privies and outhouses must be replaced with a septic system on transfer, with limited exceptions (NJAC 7:9A-3.16(b)).","Also: No open construction permits: Open construction permits must be closed.","Also: Township trash and recycling containers: Township-issued trash and recycle containers are required to be on the premises.","Also: As-is sale buyer letter: For homes sold 'as is', the buyer signs a notarized letter agreeing to finish required repairs within 60 days; a Settlement Document is issued when the letter is received."]$j$::jsonb, $j$[{"label":"First and second inspection","amount":"$100.00"},{"label":"Each additional inspection request","amount":"$50.00"}]$j$::jsonb, $t$https://www.elktownshipnj.gov/Documents/How%20Do%20I/Find%20Municipal%20Forms/Certificate-of-Occupancy-Application.pdf$t$, $t$https://www.elktownshipnj.gov/departments/construction.php$t$, $j$[{"url":"https://www.elktownshipnj.gov/Documents/How%20Do%20I/Find%20Municipal%20Forms/Certificate-of-Occupancy-Application.pdf","label":"Official source (elktownshipnj.gov)"}]$j$::jsonb, $t$30 DAYS ADVANCE NOTICE, PRIOR TO SETTLEMENT OR ANY CHANGE OF OCCUPANCY IS REQUIRED FOR C/O INSPECTIONS$t$, $t$2f59e419143edb8a3d52a46ea7722ae2316fdec493355d2bb18ddc111f198783$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":5,"q_ok":5,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0804.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0804.json$t$, true),
  ($t$0804$t$, $t$Elk Township$t$, $t$GLOUCESTER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Elk Township Construction Office, Housing Official (smoke and CO alarms checked on the resale C/O inspection) (town fire bureau)","Contact: 856-881-6525 ext. 118 · construction@elktownshipnj.gov","Apply: 30 days before settlement (same as the C/O inspection)","How to apply: No separate smoke certificate application was found. The smoke and CO alarm check is part of the Township C/O inspection. Under N.J.A.C. 5:70-2.3(a)1, where a town has its own resale inspection, a separate certificate is not required but the town may not issue its CO until the home meets N.J.A.C. 5:70-4.19. Ask the Construction Office whether a portable fire extinguisher is also checked, since the form does not mention one.","Fire official in the NJ state directory (county fire marshal), updated 6/17/2026: Shawn K Layton · (856) 307-7912 · slayton@co.gloucester.nj.us","Township CO form: smoke detector in each bedroom and on every level of the house, 10 year sealed device","Township CO form: smoke and CO detectors outside bedrooms within 10 feet of bedrooms","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.elktownshipnj.gov/Documents/How%20Do%20I/Find%20Municipal%20Forms/Certificate-of-Occupancy-Application.pdf$t$, $t$https://www.elktownshipnj.gov/departments/construction.php$t$, $j$[{"url":"https://www.elktownshipnj.gov/Documents/How%20Do%20I/Find%20Municipal%20Forms/Certificate-of-Occupancy-Application.pdf","label":"Official source (elktownshipnj.gov)"},{"url":"https://www.law.cornell.edu/regulations/new-jersey/N-J-A-C-5-70-2-3","label":"Official source (law.cornell.edu)"}]$j$::jsonb, $t$Smoke detector required in each bedroom and on every level of house (10 yr sealed device)$t$, $t$2e4b85a3cf4342aa61b7080427c01f0f88a85b28deb970277447dfe09e492079$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":5,"q_ok":5,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0804.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0804.json$t$, true),
  ($t$0805$t$, $t$Franklin Township$t$, $t$GLOUCESTER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate / New Tenant Certificate (Certificate of Occupancy Transfer, Township Code Chapter 178)$t$, $j$["Issued by: Franklin Township Housing Code Official (Zoning and Land Use Department)","Contact: 856-694-1234 · housinginspector@franklintownship.com","Apply: File at least 30 days before settlement (the information sheet says allow a minimum of three weeks and suggests applying when the house is listed)","How to apply: Fill out the Application for Resale Certificate or New Tenant Certificate and hand it in with the fee at the Housing Code Official's Office in the Municipal Building, 1571 Delsea Drive, Franklinville. Applications and fees are not accepted in the field. There is a box on the form for a Non-Occupy (AS IS SALE) certificate request. If the buyer is taking over responsibility for the certificate, notify the office in writing before it is issued.","Valid for: Applications are non-transferable and expire after 60 days","Passing water test and Gloucester County Board of Health septic approval","Reflective house numbers at least 3-1/2 inches high, readable from the street","Pool and yard fences with self-latching, out-swing gates (48 inch minimum height, 54 inch if latch at top)","Guardrails on landings or porches 30 inches or higher (36 inch minimum height, 4 inch spacing); sound stairs, decks, porches and balconies","No broken or missing glass; all windows with screens that open, close and lock","Stove anti-tilt device; all utilities on at inspection","Smoke detector on each level, in all bedrooms and outside each sleeping area (battery allowed)","Carbon monoxide detectors near sleeping areas (unless no fuel-burning device or attached garage)","ABC fire extinguisher at least 2A:10B:C, no more than 10 lbs, mounted in a visible, convenient spot","Handrails on stairs with four or more risers; bathroom window or exhaust fan","No electrical hazards or extension-cord wiring; GFCI at pools, spas, exterior, garage, kitchen, bath and within 5 feet of water","Plumbing vented and working; heat to all habitable rooms; water heater relief valve pipe ending within 6 inches of floor","Certifications may be required for roof, electrical, structural, heating or lead","Also: Well water test and septic approval: A passing water test and Gloucester County Board of Health septic approval are required before a Resale Certificate is issued.","Also: Records check: The office checks zoning, property, construction and violation records when processing the application (office-use section of the form).","Also: Buyer assumption of certificate: Under Chapter 178-4 the buyer may waive the seller's responsibility and take over getting the certificate, in writing filed with the Housing Code Official."]$j$::jsonb, $j$[{"label":"Initial inspection","amount":"$100.00"},{"label":"Each re-inspection","amount":"$50.00"},{"label":"Fines for not getting approval within 30 days of initial inspection (per day)","amount":"$100.00 - $200.00 per day"}]$j$::jsonb, $t$https://www.franklintownshipnj.org/DocumentCenter/View/6409/Application-for-Resale-Certificate-or-New-Tenant-Certificate-PDF$t$, $t$https://www.franklintownshipnj.org/152/Code-Enforcement-Land-Use$t$, $j$[{"url":"https://www.franklintownshipnj.org/DocumentCenter/View/6381/Resale-and-New-Tenant-Certificate-Information-and-Checklist-PDF","label":"Official source (franklintownshipnj.org)"},{"url":"https://www.franklintownshipnj.org/DocumentCenter/View/6409/Application-for-Resale-Certificate-or-New-Tenant-Certificate-PDF","label":"Official source (franklintownshipnj.org)"},{"url":"https://www.franklintownshipnj.org/DocumentCenter/View/179/Ordinance-024-14---Amending-Chapter-178---Certificate-of-Occupancy-Transfer-PDF","label":"Official source (franklintownshipnj.org)"}]$j$::jsonb, $t$A Resale Certificate / New Tenant Certificate is required in the Township of Franklin each time a residential dwelling unit changes occupant and tenant.$t$, $t$3825f81b64c709ca7806b3445f5dddecc2b24714e3ee4f2ee83957bd7444a7c7$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":6,"q_ok":5,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0805.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0805.json$t$, true),
  ($t$0805$t$, $t$Franklin Township$t$, $t$GLOUCESTER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Franklin Township (municipal fire code enforcing agency, Fire Marshals); alarms and extinguisher are checked on the Township Resale Certificate inspection (town fire bureau)","Contact: 856-694-1234 ext. 6","How to apply: No separate smoke certificate application or fee was found. The smoke alarm, CO alarm and fire extinguisher items are on the Township Resale Certificate checklist. Under N.J.A.C. 5:70-2.3(a)1, where a town has its own resale inspection, a separate certificate is not required but the town may not issue its certificate until the home meets N.J.A.C. 5:70-4.19. Confirm with the Fire Marshals at 856-694-1234 ext. 6.","Fire official in the NJ state directory (town), updated 6/16/2026: Anthony Baldosaro · (856) 694-1234 · abaldosaro@franklintownship.com","Township checklist: ABC fire extinguisher no smaller than 2A:10B:C, no more than 10 lbs, mounted in a visible and convenient location","Township checklist: smoke detector on each level, in all bedrooms and outside each sleeping area; battery units allowed","Township checklist: CO detectors in the vicinity of sleeping areas","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.franklintownshipnj.org/DocumentCenter/View/6409/Application-for-Resale-Certificate-or-New-Tenant-Certificate-PDF$t$, $t$https://www.franklintownshipnj.org/151/Fire-Departments$t$, $j$[{"url":"https://www.franklintownshipnj.org/DocumentCenter/View/6381/Resale-and-New-Tenant-Certificate-Information-and-Checklist-PDF","label":"Official source (franklintownshipnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.law.cornell.edu/regulations/new-jersey/N-J-A-C-5-70-2-3","label":"Official source (law.cornell.edu)"}]$j$::jsonb, $t$An ABC fire extinguisher must be no smaller than 2A:10B:C, weigh no more than 10lbs and mounted in a visible and convenient location.$t$, $t$a4bc9bd02433fce4081e505bd577b493ac379bbea639db133f0f47bfca6a7f1c$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":6,"q_ok":5,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0805.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0805.json$t$, true),
  ($t$0806$t$, $t$Glassboro Borough$t$, $t$GLOUCESTER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale of Dwelling Certificate (Resale CO); Transfer of Title when violations remain at settlement$t$, $j$["Issued by: Borough of Glassboro Code Enforcement Office (Health & Housing)","Contact: 856-881-9230 ext. 88140 · kharrell@glassboro.org","How to apply: Fill out the Application for Resale of Dwelling Certificate (it includes the Bureau of Fire Prevention smoke/CO/extinguisher application and a rental acknowledgement the buyer must sign even if the home will not be rented) and return it to the Code Enforcement Office, 10 S. Poplar Street, Glassboro, or email Katy Harrell at Kharrell@glassboro.org. Inspections are by appointment only and all paperwork must be in before the certificate is issued. If the home sells with open violations, use the Application for Transfer of Title instead; the buyer signs a notarized hold harmless agreement to fix the violations within 90 days.","Address numbers at least 4 inches, contrasting, visible from the street","Curb, sidewalk, driveway and apron free of major cracks and tripping hazards","Roof, gutters, siding, masonry, exterior doors, windows and screens in good repair (roof, electrical, HVAC, water heater and plumbing certifications may be required)","Exterior steps, decks, porches, guardrails (36 inch) and graspable handrails in good repair; decks and sheds must have been permitted","Chimney in good repair; certification required if a wood burning appliance is present","Pools permitted, clean, with self-closing gate and 48 inch minimum enclosure","Smoke alarms hardwired or 10 year sealed lithium, working, on every level in a common area","Carbon monoxide alarms on each level in a common area","ABC fire extinguisher, 10 lbs or under, within 10 feet of the kitchen","Stove anti-tip device; bathroom, kitchen and dryer ventilation working","GFI outlets in bathroom, kitchen, laundry and within 6 feet of any water source","No double keyed exterior locks; no keyed locks on interior doors","Walls, ceilings and floors in good repair; exterior grounds clean, no unpermitted fire pits","Also: Buyer rental acknowledgement: The buyer must sign the Acknowledgement for Rental Property and return it with the application, even if the home will not be rented; no Resale Certificate is issued without it.","Also: Open permits and RCA check: The office-use section has 'RCA checked' and 'Permits checked' boxes, so open permits are reviewed before the certificate is issued.","Also: Transfer of Title hold harmless agreement: For settlement before violations are fixed, buyers sign a notarized hold harmless agreement, may not occupy until health and safety violations are corrected, and must correct the listed violations within 90 days.","Also: Sewer or septic disclosure: The application asks whether the home is on public sewer or septic/cesspool."]$j$::jsonb, $j$[{"label":"Resale of Dwelling Certificate, single unit dwelling (includes one re-inspection)","amount":"$100.00"},{"label":"Second re-inspection (Resale of Dwelling Certificate)","amount":"$35.00"},{"label":"Transfer of Title (settlement before violations are fixed), single unit dwelling, includes one re-inspection","amount":"$125.00"}]$j$::jsonb, $t$https://www.glassboro.org/s/Resale-CO-App-2026-FILLABLE.pdf$t$, $t$https://www.glassboro.org/housing-code$t$, $j$[{"url":"https://www.glassboro.org/s/Transfer-of-Title-App-2026-FILLABLE.pdf","label":"Official source (glassboro.org)"},{"url":"https://www.glassboro.org/s/Resale-CO-App-2026-FILLABLE.pdf","label":"Official source (glassboro.org)"}]$j$::jsonb, $t$Properties are not permitted to go to settlement without proper Resale CO/Transfer of Title.$t$, $t$7cb671e4cb15a9c3869a9f5f7d45570d47fc8d74b9fdd6edffcfbdeea5565c95$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":6,"fee_bad":0,"fee_unchecked":0,"quotes":7,"q_ok":7,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0806.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0806.json$t$, true),
  ($t$0807$t$, $t$Greenwich Township$t$, $t$GLOUCESTER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy (Certificate of Continued Occupancy) inspection$t$, $j$["Issued by: Housing Inspector / Housing Officer, Greenwich Township Construction Office","Contact: 856-423-9129 ext. 201 or 214 · jgiordano@greenwichtwp.com","How to apply: Fill out the Application for Certificate of Occupancy (mark it Resale and give the settlement date) and submit it to the Construction Office at 420 Washington Street, Gibbstown, with the fee (form lists cash or check). The application is not complete until the owner or realtor calls the office to schedule the inspection: ext. 201 (Kay Hewes) or ext. 214 (inspection officer). Inspections are done Tuesdays and Thursdays, 10 AM to 2 PM. The Spring 2026 township newsletter says Certification of Continued Occupancy fees can also be paid online.","Yard clean, no trash, debris, junk or junk cars; lawn mowed","Exterior in good repair, no chipped paint or corrosion","House numbers visible from the street (3 or 4 inch depending on setback)","Handrails and guards on all stairways; basement stair openings blocked so no fall-through","Doors and windows in good condition; windows open smoothly, have screens, stay open; no broken glass","Bathrooms have a window or mechanical ventilation","GFI outlets in bathrooms, kitchens and laundry rooms within 6 ft of a water source; at least two outlets per room","Metal dryer vent (no plastic)","Smoke alarm on each floor: 10-year sealed battery unit unless hard-wired with battery backup","Carbon monoxide alarm if heat or hot water is gas or oil fired","Fire extinguisher rated 2-A:10-B:C (ABC)","Water heater in good condition with relief valve discharge pipe ending 6 inches from floor; toilets and plumbing with no leaks; adequate water pressure","Oil-fired heater inspected within last 2 years; wood fireplaces or stoves cleaned and inspected by a licensed chimney sweep","Electric service in good condition, no bare wires or missing box covers; oil tanks not leaking","Sidewalks with no raised sections over 1 inch; sheds, garages and fences in good condition","Also: Open construction permits must be closed: CO checklist: 'CO will not be issued if home has any open construction permits that are pending.'"]$j$::jsonb, $j$[{"label":"Residential inspection fee","amount":"$60.00"},{"label":"Re-inspection fee","amount":"$25.00"}]$j$::jsonb, $t$https://www.greenwichtwp.com/DocumentCenter/View/3009/CO-Inspection-Application-rev2025$t$, $t$https://www.greenwichtwp.com/2168/Construction-Code-Office$t$, $j$[{"url":"https://www.greenwichtwp.com/DocumentCenter/View/3009/CO-Inspection-Application-rev2025","label":"Official source (greenwichtwp.com)"},{"url":"https://www.greenwichtwp.com/2168/Construction-Code-Office","label":"Official source (greenwichtwp.com)"},{"url":"https://www.greenwichtwp.com/DocumentCenter/View/933/CO-Inspection-Check-list","label":"Official source (greenwichtwp.com)"}]$j$::jsonb, $t$RESALE: RENTAL: OTHER: SETTLEMENT/OCCUPANCY DATE: ... THIS DWELLING IS NOT TO BE OCCUPIED UNTIL A CERTIFICATE OF OCCUPANCY IS ISSUED BY THE HOUSING INSPECTOR OF GREENWICH TOWNSHIP.$t$, $t$53ce2900a1b7e3d56bda23d844278bfd285a9e0a98859b68c5e0eb7ad770b4ce$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":2,"fee_bad":0,"fee_unchecked":0,"quotes":5,"q_ok":5,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0807.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0807.json$t$, true),
  ($t$0808$t$, $t$Harrison Township$t$, $t$GLOUCESTER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Transfer of Ownership / Occupancy (CTO)$t$, $j$["Issued by: Harrison Township Housing Department (Housing Code Official, Property Maintenance / Code Enforcement)","Contact: 856-478-4111 · property_maintenance@harrisontwp.us","Apply: Apply at least 30 days before settlement. Inspections requested within 10 business days of the application are charged the expedited fee.","How to apply: Fill out the CTO application completely and submit it with the fee (cash or check) to the Housing Code Official's office, 114 Bridgeton Pike, Mullica Hill. Inspectors in the field will not accept applications or fees. After the application is processed, the owner or realtor must call or email the housing office to schedule the inspection. If the buyer is taking responsibility for the certificate, the office must be told in writing before the CTO is issued.","Passing inspection under the 2024 International Property Maintenance Code","Smoke detector certification from the fire department (Fire District #1)","Septic certification; if work is needed, written documentation or sealed correction plans, with 60 days to fix under a temporary certificate","Proper permits and inspections for any work done in the home","All utilities on and working at the time of inspection","Certifications may be required for chimneys, roof, electrical, structural and heating","Also: Septic certification: Required for issuance of the CTO; if the septic is not certified and work is needed, submit written documentation or sealed correction plans; 60 days to correct under a Temporary Certificate.","Also: Open permits: Proper permits and inspections are required for any work completed in the home.","Also: Utilities on: All utilities must be on and working at the time of inspection."]$j$::jsonb, $j$[{"label":"Residential initial inspection (covers initial inspection and first re-inspection)","amount":"$100.00"},{"label":"Residential expedited (inspection needed within 10 business days of application)","amount":"$150"},{"label":"Third and each later inspection","amount":"$50.00"}]$j$::jsonb, $t$https://harrisontwp.us/wp-content/uploads/2025/11/CTO-applicatiCertification-of-Tranfer-of-OwnershipOccupancy-Application-rev-11242025.pdf$t$, $t$https://harrisontwp.us/department/property-maintenance-code-enforcement/$t$, $j$[{"url":"https://harrisontwp.us/wp-content/uploads/2025/11/CTO-applicatiCertification-of-Tranfer-of-OwnershipOccupancy-Application-rev-11242025.pdf","label":"Official source (harrisontwp.us)"}]$j$::jsonb, $t$PROPERTY TYPE: ____House Sale / ____ House Rental / ____ Apartment Rental / _____ Commercial ... Please do not schedule a settlement date until the CTO is approved and returned.$t$, $t$20fc64665b02debe6b66e0e498333822f533cced332e64c1601a19ee481bbf2c$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":7,"fee_bad":0,"fee_unchecked":0,"quotes":4,"q_ok":4,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0808.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0808.json$t$, true),
  ($t$0811$t$, $t$Monroe Township$t$, $t$GLOUCESTER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Resale Certificate of Occupancy (Resale Inspection)$t$, $j$["Issued by: Monroe Township Housing Office (Housing Official Dan Kozak)","Contact: 856-728-9800 ext. 289 or 296 · housing@monroetownshipnj.org","Apply: Submit the application 3 to 4 weeks before settlement. Requests with less than 7 business days cost more.","How to apply: Download the Resale Application Packet, fill out the application, and have the buyer sign the Acknowledgement of Responsibility in front of a notary (the original is required; inspections cannot be scheduled without it). Submit in person or by mail to the Monroe Township Housing Office, 125 Virginia Avenue, Williamstown, NJ 08094, with exact cash, check or money order payable to 'Monroe Township Housing'. No credit or debit cards. All fees are non-refundable. For as-is sales, include the contract cover sheet and the clause making the buyer responsible for certificates and inspections.","Valid for: Inspections are only valid for 60 days","House numbers at least 3 inches on both sides of the mailbox","Smoke alarms on all levels; battery alarms must be 10-year sealed units; hardwired alarms must stay hardwired and be under 10 years old","Carbon monoxide alarms outside sleeping areas (exception for all-electric homes with detached garages)","Fire extinguisher 2A-10B:C, no more than 10 lb, mounted with its bracket within 10 ft of the kitchen in the exit path, top no higher than 5 ft, serviced and tagged within 12 months or new with receipt, manual left for new occupant","Satisfactory lab report including mercury for private wells","Satisfactory septic certification from Gloucester County Dept of Health for private septic","Exterior clean, safe and in satisfactory condition","Pool barriers: 4 ft fence and self-closing, self-latching gate that opens out with release 54 inches from the ground; no stagnant water","Hot tub safety straps in good working order","Abandoned property registration fees and emergency work charges paid","All zoning, construction and Board of Health permits and violations closed and penalties paid","All property maintenance violations satisfied and penalties paid","Buyer's notarized Acknowledgement of Responsibility form submitted with the application","Also: Open permits and violations must be closed: All construction permits and violations must be closed before the CO is issued; all zoning, construction, Board of Health and property maintenance violations satisfied and penalties paid.","Also: Private well test: Satisfactory lab report including mercury for private wells.","Also: Septic certification: Satisfactory septic certification for private septic systems by Gloucester County Dept of Health.","Also: Abandoned property fees and emergency work charges: Must be paid in full before the CO.","Also: Buyer Acknowledgement of Responsibility (notarized): Original notarized form completed by the buyer must be submitted with the application; the CO can be denied without it."]$j$::jsonb, $j$[{"label":"Resale inspection application","amount":"$200.00"},{"label":"Request with less than 7 business days","amount":"$300.00"},{"label":"No answer at door for scheduled inspection","amount":"$50.00"},{"label":"Reinspection","amount":"$25.00"},{"label":"Reinspection with less than 7 business days","amount":"$50.00"},{"label":"Affidavit / temporary certificate of occupancy (buyer takes responsibility for repairs)","amount":"$100.00"},{"label":"Failure to obtain resale certificate of occupancy (penalty)","amount":"$300.00"}]$j$::jsonb, $t$https://monroetownshipnj.org/wp-content/uploads/2026/08/Resale-App_Cklst_Aff-REVISED-8-3-26-1.pdf$t$, $t$https://monroetownshipnj.org/3-2/department-of-development-housing/housing-enforcement/$t$, $j$[{"url":"https://monroetownshipnj.org/3-2/department-of-development-housing/housing-enforcement/","label":"Official source (monroetownshipnj.org)"},{"url":"https://monroetownshipnj.org/wp-content/uploads/2026/08/Resale-App_Cklst_Aff-REVISED-8-3-26-1.pdf","label":"Official source (monroetownshipnj.org)"}]$j$::jsonb, $t$Resale Inspections take place at the change of each ownership for dwellings in Monroe Township, and the application can be found on the Township website in the forms section. An inspection shall be performed prior to the change of ownership, and a Certificate of Occupancy will be issued following a passing inspection.$t$, $t$5666e0fa7c6b73030852d65c4a56eea5aea86126c1e6bcb03e637fde17d47cbd$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":0,"fee_bad":0,"fee_unchecked":7,"quotes":6,"q_ok":3,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0811.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0811.json$t$, true),
  ($t$0811$t$, $t$Monroe Township$t$, $t$GLOUCESTER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Monroe Township Bureau of Fire Prevention (Department of Public Safety) (town fire bureau)","Contact: 856-728-9800 ext. 256 · fireprevention@monroetownshipnj.org","How to apply: Contact the Bureau of Fire Prevention. The smoke alarm, CO alarm and extinguisher items are also checked as part of the Housing Office resale CO inspection; the township does not say whether a separate Bureau certificate or fee is needed.","Fire official in the NJ state directory (town), updated 6/16/2026: Patrick Mason · (856) 728-9800 · pmason@monroetownshipnj.org","The township resale checklist says all battery smoke alarms must be 10-year sealed units (effective Jan 1, 2019), hardwired alarms must stay hardwired and be under 10 years old, and the extinguisher must be serviced and tagged by a certified contractor within 12 months or be new with a receipt, weigh no more than 10 lb, and be mounted with the top no more than 5 ft above the floor","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://monroetownshipnj.org/3-2/department-of-public-safety/fire-prevention/$t$, $j$[{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://monroetownshipnj.org/3-2/department-of-public-safety/fire-prevention/","label":"Official source (monroetownshipnj.org)"},{"url":"https://monroetownshipnj.org/wp-content/uploads/2026/08/Resale-App_Cklst_Aff-REVISED-8-3-26-1.pdf","label":"Official source (monroetownshipnj.org)"}]$j$::jsonb, $t$M Monroe Township$t$, $t$f0e4c687f3196238f39b1e9b51a54f9c0035b1086fefdd148de3de72a4e1d234$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":7,"fee_ok":0,"fee_bad":0,"fee_unchecked":7,"quotes":6,"q_ok":3,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0811.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0811.json$t$, true),
  ($t$0812$t$, $t$National Park Borough$t$, $t$GLOUCESTER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy for Change of Occupancy (resale inspection)$t$, $j$["Issued by: Housing Inspector, Property Maintenance and Rental Units Department","Contact: 856-845-3891 · ehagerty@nationalparknj.com","Apply: Apply at least three weeks before occupancy; the borough suggests applying when the house is listed","How to apply: Fill out the Application for a Certificate of Occupancy for Change of Occupancy and submit it with the fee to the Inspection Office at Borough Hall, 7 S. Grove Ave, National Park, NJ 08063. Inspectors in the field do not accept applications or fees. The application is not complete until the owner or agent calls 856-845-3891 to schedule. Inspection appointments are only on Thursdays, 12:00 PM to 1:00 PM.","Exterior walls sound and weatherproof; house numbers at least 3 inches, readable from the street; yard maintained","Garages, fences, walls, stairs, decks, porches sound; driveways and sidewalks without tripping hazards; no big foundation cracks","Porches or landings 30 inches high need rails with openings no more than 4 inches","Roof and chimney sound (roof or chimney certification may be required); no broken glass","No double-keyed deadbolt on the main door (thumb latch required)","Pool fence with self-closing, self-latching gate that swings out (48 inch minimum, 6 ft for inground); no stagnant water; GFCI for pools","All utilities on at inspection","Smoke detector on each level and outside sleeping areas (battery allowed); CO detector outside sleeping area (battery allowed)","A:B:C fire extinguisher, no larger than 10 lb, mounted within 10 ft of the kitchen","Mechanical equipment working; no excessive peeling paint, loose plaster or decayed wood; no insect infestation","Handrail 30 to 38 inches on stairs of 5 or more steps; every room has an operable window with screen","Electrical free of hazards: no extension-cord wiring, covers on all boxes, at least 2 outlets per room and 1 per bathroom","Plumbing without leaks, toilets flush, tub and shower watertight; heat to all habitable rooms","Water heater and boiler relief valve pipe ending within 6 inches of the floor; flue pipes sealed","Satisfactory drinking water lab report if not on public water","Also: Possible trade certifications: Roofing, chimney, structural, electrical, plumbing or heating certifications may be required by the inspector.","Also: Private water test: A satisfactory lab report is required for drinking water where public water is not supplied."]$j$::jsonb, $j$[{"label":"Inspection fee, per unit","amount":"$ 50.00"},{"label":"Re-inspection, per unit (charged for each inspection after the second)","amount":"$35.00"}]$j$::jsonb, $t$https://www.nationalparknj.com/Document%20Center/Departments/Property%20Maintenance/COApplication.pdf$t$, $t$https://www.nationalparknj.com/departments/property_maintenance/certificates_of_occupancy/index.php$t$, $j$[{"url":"https://www.nationalparknj.com/Document%20Center/Departments/Property%20Maintenance/COApplication.pdf","label":"Official source (nationalparknj.com)"},{"url":"https://www.nationalparknj.com/departments/property_maintenance/index.php","label":"Official source (nationalparknj.com)"}]$j$::jsonb, $t$A Certificate of Occupancy is required in the Borough of National Park every time a residential property changes occupants.$t$, $t$7e9e263706377765db2997a09bdcb44b80515cfa174f8fa7cac94db226b24431$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":6,"q_ok":3,"q_bad":0,"q_unchecked":3},"source":"property/data/municipal-requirements/checked/0812.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0812.json$t$, true),
  ($t$0815$t$, $t$Pitman Borough$t$, $t$GLOUCESTER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Municipal Compliance for Housing and Fire Safety Inspection (sale); certificate issued by the Housing/Fire Safety Office$t$, $j$["Issued by: Borough of Pitman Construction Office (Housing Officer and Fire Safety Official)","Contact: 856-589-2433 · construction@pitman.org","How to apply: Fill out the Municipal Compliance for Housing and Fire Safety Inspection Application, including the Sale section (buyer, sales rep and realty company, settlement date, underground oil tank, open permits), and give a lock box number if there is one. Return it to the Construction Office at Borough Hall, 110 South Broadway, Pitman, with payment by check or cash, or contact construction@pitman.org or firesafety@pitman.org. The office then sets the inspection date and time slot.","Smoke detectors present and working","Carbon monoxide detectors present and working","Handrails in place","Water heater relief valve with discharge pipe toward the floor","Appliance and exhaust venting","Emergency exit from a 3rd floor","Receptacles, electrical fixtures, GFI outlets, correct fuse/breaker size, no illegal extension cords","Windows open and lock; screens (April 1 to December 1)","Heating system, water heater and water pressure","Ceilings, walls, floors, interior doors, exterior door and lock","No infestation (mice, rats, roaches, ants); interior clean","Plumbing fixtures, water and drain pipes","Exterior: roof, deck, porch, steps, railings, chimney, fence, gutters/downspouts, siding, trim, paint, masonry, lighting, grounds, trash containers","House number posted","All utilities must be on for the inspection","Also: Open permits: The Sale section of the application asks whether there are open permits and the permit number.","Also: Underground oil tank: The Sale section asks whether there is an underground oil tank and for a DEP number.","Also: Transfer of Title Agreement: If violations are not fixed by settlement, the buyer signs a notarized Transfer of Title Agreement and may not occupy until the certificate is issued."]$j$::jsonb, $j$[{"label":"Initial inspection, per unit (combined housing and fire safety inspection)","amount":"$75.00"},{"label":"Reinspection","amount":"$45.00"}]$j$::jsonb, $t$https://www.pitman.org/Construction/HOUSING-FIRE%20SAFETY%20INSPECTION%20APPLICATION.pdf$t$, $t$https://www.pitman.org/departments/construction___zoning/index.php$t$, $j$[{"url":"https://www.pitman.org/Construction/HOUSING-FIRE%20SAFETY%20INSPECTION%20APPLICATION.pdf","label":"Official source (pitman.org)"},{"url":"https://www.pitman.org/Construction/Transfer%20of%20Title%20Agreement.pdf","label":"Official source (pitman.org)"},{"url":"https://www.pitman.org/housing%20inspection%20checklist.pdf","label":"Official source (pitman.org)"}]$j$::jsonb, $t$MUNICIPAL COMPLIANCE FOR HOUSING AND FIRE SAFETY INSPECTION APPLICATION$t$, $t$45325d7ae2bdbcbb77fb5b70c5cb249035482cbbf261c15b20b8dac8f2ccb4d9$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":7,"q_ok":6,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0815.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0815.json$t$, true),
  ($t$0816$t$, $t$South Harrison Township$t$, $t$GLOUCESTER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Continued/Change of Occupancy and Certificate of Resale$t$, $j$["Issued by: South Harrison Township Construction / Code Enforcement Office (Construction Official/Housing Official)","Contact: 856-769-3737 ext. 7805 · TACO@southharrison-nj.org","How to apply: Download the 'Certificate of Resale - Change of Occupancy' application from the Construction / Code Enforcement Office page, fill in owner, buyer, agent, appointment contact and settlement date, and submit it with the $100.00 fee to the Construction & Code Enforcement Office, 664 Harrisonville Road, Mullica Hill. Email TACO@southharrison-nj.org to schedule the inspection (inspections Tuesdays and Thursdays, 12:00 PM to 4:00 PM, upon request).","Visible 911 house number","Steps, walkways, ramps, guardrails and handrails (outside and inside)","No exterior obstructions or hazards; perimeter grading; gutters, downspouts and splash blocks","Basement or crawl space: foundation openings, secure and weatherproof access, vapor barrier intact","Sump pump electrical connection, backflow and discharge; no mold","No mice or insect infestation","Bathroom venting by fan or window","GFI receptacles in kitchen, bath and garage","Kitchen and bath flooring; switch and receptacle covers; electrical fixtures; panel box and panel covers intact; A/C disconnect","Window glass, working egress windows, window guards","Water heater chimney connection, relief valve and floor discharge","Water pipes, drain pipes, fixtures, toilet mounting, hot and cold water controls","Heating system and chimney connection","Smoke detectors and CO detectors","Fire extinguisher, size 2A-10BC, within 10 feet of the kitchen","Also: Trash and recycling cans: The resale form has check boxes for the number of trash cans and recycle cans."]$j$::jsonb, $j$[{"label":"Application fee (continued/change of occupancy and certificate of resale)","amount":"$100.00"}]$j$::jsonb, $t$https://drive.google.com/file/d/16rJRY5Y3-o_2-_YT93zK1770XIzET5V_/view?usp=sharing$t$, $t$https://www.southharrison-nj.org/municipal-departments/construction-code-enforcement-office$t$, $j$[{"url":"https://drive.google.com/file/d/16rJRY5Y3-o_2-_YT93zK1770XIzET5V_/view?usp=sharing","label":"Official source (drive.google.com)"},{"url":"https://www.southharrison-nj.org/municipal-departments/construction-code-enforcement-office","label":"Official source (southharrison-nj.org)"}]$j$::jsonb, $t$APPLICATION FOR CONTINUED/CHANGE OF OCCUPANCY & CERTIFICATE OF RESALE AND/OR RENTAL$t$, $t$058ee04ef688c6a81a2e4c50e7b4b8c181018dc82f447f6631ade4b0c947cd5f$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":7,"q_ok":5,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0816.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0816.json$t$, true),
  ($t$0816$t$, $t$South Harrison Township$t$, $t$GLOUCESTER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Entire township: issued by South Harrison Township Construction / Code Enforcement Office (smoke, CO and extinguisher checked on the resale inspection) (town fire bureau)","Entire township contact: 856-769-3737 ext. 7805 · TACO@southharrison-nj.org","Entire township, how to apply: No separate smoke/CO certificate form was found on the Township site. The Township resale application lists Smoke Detectors, CO Detectors and Fire Extinguisher (2A-10BC, within 10 feet of kitchen) as inspection items, and its $100.00 fee is listed under the town certificate. Under N.J.A.C. 5:70-2.3, where a town has its own resale inspection, a separate certificate is not required but the town may not approve until the home meets N.J.A.C. 5:70-4.19. Confirm with the Construction Office whether the County Fire Marshal also must issue a certificate.","Entire township: issued by Gloucester County Fire Marshal's Office (county local enforcing agency for the Uniform Fire Code)","Entire township contact: 856-307-7912 · gcfmo@co.gloucester.nj.us","Entire township, how to apply: No County smoke/CO/extinguisher certificate form or fee for home sales was found on the County website. Call or email the County Fire Marshal's Office (212 County House Road, Clarksboro) and ask how to request the resale inspection for this town, and whether the town collects the application and fee.","Fire official in the NJ state directory (county fire marshal), updated 4/2/2019: Shawn K Layton · (856) 307-7912 · slayton@co.gloucester.nj.us","Township resale form checks for a fire extinguisher, size 2A-10BC, within 10 feet of the kitchen","If smoke detectors are tied into a security system, the alarm company must be notified before testing","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://drive.google.com/file/d/16rJRY5Y3-o_2-_YT93zK1770XIzET5V_/view?usp=sharing$t$, $t$https://www.southharrison-nj.org/municipal-departments/construction-code-enforcement-office$t$, $j$[{"url":"https://drive.google.com/file/d/16rJRY5Y3-o_2-_YT93zK1770XIzET5V_/view?usp=sharing","label":"Official source (drive.google.com)"},{"url":"https://www.law.cornell.edu/regulations/new-jersey/N-J-A-C-5-70-2-3","label":"Official source (law.cornell.edu)"},{"url":"https://www.gloucestercountynj.gov/359/Office-of-the-Fire-Marshal","label":"Official source (gloucestercountynj.gov)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$IF SMOKE DETECTORS ARE TIED INTO A SECURITY SYTEM, THE ALARM COMPANY MUST BE NOTIFIED PRIOR TO TESTING!$t$, $t$31ec6a899c9c784a6b8d0289b97c9b9379d0d67785eb867af342b2488ddcbfec$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":1,"fee_ok":0,"fee_bad":0,"fee_unchecked":1,"quotes":7,"q_ok":5,"q_bad":0,"q_unchecked":2},"source":"property/data/municipal-requirements/checked/0816.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0816.json$t$, true),
  ($t$0818$t$, $t$Washington Township$t$, $t$GLOUCESTER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Occupancy - Sale (Certificate of Resale)$t$, $j$["Issued by: Washington Township Housing Office (Division of Community Development, in the Construction Office)","Contact: 856-589-0520 ext. 2231 or 2296 · vorr@twp.washington.nj.us","Apply: Have the inspection done at least 3 weeks before settlement (Housing FAQ). Expedited inspections are available for an added fee.","How to apply: Fill out every field of the Application for Certificate of Occupancy - Sale and submit the original with a wet ink signature (DocuSign is not accepted) plus the fee by check or cash payable to Township of Washington, to the Housing Office, Municipal Building, 523 Egg Harbor Road, Sewell. The office assistant schedules an AM or PM inspection window. The seller's agent may apply. No one needs to be home if the inspector can get in (lock box code or key left on the property; no loose pets). Pass: the CO is emailed. Fail: the report is emailed; fix items and call to schedule the reinspection.","House number plainly visible from the street, at least 4 inches high","Sidewalk free of trip hazards","Roof drains, gutters and downspouts in good repair","Windows and doors open easily and stay in place","Stairs, decks, porches and balconies permitted and structurally sound; guards over 30 inches; graspable handrails","Pool fully fenced with self-closing, self-latching gates that open outward","Exit doors open from inside without a key (no double-keyed deadbolts)","No more than 2 persons per bedroom; lofts cannot be bedrooms","Smoke detector on every level; hardwired stays hardwired, otherwise 10-year sealed battery","Carbon monoxide detector near all sleeping rooms","All utilities (electric, water, gas) on for the inspection","Water heater with proper temperature/pressure relief valve and discharge pipe (permit required)","Safe electrical system and covers; no hazards","Dryer exhaust vented outside in non-combustible material; bath fan or window vented outdoors","No plumbing leaks; fire-rated walls and ceilings intact; attic access; all open permits closed","Also: Open permits must be closed: Permits must be completed with the Construction Office in order to pass inspection; unpermitted work must be fixed before the CO is issued.","Also: Temporary Certificate of Occupancy (TCO): If the buyer agrees to take on repairs, a notarized Affidavit for TCO lets settlement go ahead; the fee ordinance lists $125 for a TCO request after the initial inspection.","Also: Well and septic: The sale application asks whether the home has a private well, private septic, Township water or Township sewer; the Housing page links to Gloucester County well and septic records. No sale-time well or septic test requirement was found."]$j$::jsonb, $j$[{"label":"Initial inspection, sale (includes smoke certification and 1st reinspection)","amount":"$150"},{"label":"Expedited inspection, within 2 days (added fee)","amount":"$100"},{"label":"Expedited inspection, 3-5 days (added fee)","amount":"$75"},{"label":"Fee ordinance: CO inspection portion, first two inspections (plus expedited add-ons)","amount":"$125"},{"label":"Reinspection, each (form: each additional after the included 1st reinspection)","amount":"$75"},{"label":"Temporary certificate of occupancy (TCO) request, after initial inspection","amount":"$125"},{"label":"Penalty for occupying without a certificate of occupancy (listed under Change in occupancy, § 179-73)","amount":"$100"}]$j$::jsonb, $t$https://www.twp.washington.nj.us/Housing/Forms%20and%20Resources/Application%20Certificate%20of%20Occupancy%20July%202026.pdf$t$, $t$https://www.twp.washington.nj.us/departments/housing/index.php$t$, $j$[{"url":"https://www.twp.washington.nj.us/departments/housing/index.php","label":"Official source (twp.washington.nj.us)"},{"url":"https://www.twp.washington.nj.us/departments/housing/faqs.php","label":"Official source (twp.washington.nj.us)"},{"url":"https://www.twp.washington.nj.us/Housing/Forms%20and%20Resources/Application%20Certificate%20of%20Occupancy%20July%202026.pdf","label":"Official source (twp.washington.nj.us)"},{"url":"https://www.twp.washington.nj.us/O017-2026%20Ordinance%20Amending%20Chapter%2080%20Fees.pdf","label":"Official source (twp.washington.nj.us)"}]$j$::jsonb, $t$179- 68. Certificates of occupancy shall be required for human habitation of all existing dwelling units in the Township of Washington before a change in occupancy or change of owner may be effected.$t$, $t$3d62d2a743b9d07293d4704c2e80e7cb2db20335eb38eb4e7a0334969892f475$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":9,"fee_ok":4,"fee_bad":0,"fee_unchecked":5,"quotes":9,"q_ok":8,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0818.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0818.json$t$, true),
  ($t$0819$t$, $t$Wenonah Borough$t$, $t$GLOUCESTER$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Mantua Township Fire District (handles Wenonah housing and fire safety inspections under a shared services agreement) (fire district)","Contact: 856-468-7222 ext. 102","Apply: Same tiers as the housing inspection: 10 or more business days before closing for the standard fee.","How to apply: Same application and scheduling as the housing inspection: the Borough of Wenonah Fire Safety Application on the fire district website, then call (856) 468-7222 ext. 102. No separate smoke certificate fee is published; the Borough lists one fee schedule (see the town certificate fees).","Fire official in the NJ state directory (county fire marshal), updated 2/4/2025: Shawn K Layton · (856) 307-7912 · slayton@co.gloucester.nj.us","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://mtfd22.com/wenonah-housing-insepctions/$t$, $t$https://boroughofwenonah.com/government/construction-code-enforcement/$t$, $j$[{"url":"https://boroughofwenonah.com/government/construction-code-enforcement/","label":"Official source (boroughofwenonah.com)"}]$j$::jsonb, $t$You will be required to complete a form that can be found online at Borough of Wenonah Fire Safety Application$t$, $t$aee3401f8560019311937a92bdabe5bcc834d5e04c345713b6e8f3403cb796ba$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":4,"fee_ok":4,"fee_bad":0,"fee_unchecked":0,"quotes":4,"q_ok":4,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/0819.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0819.json$t$, true),
  ($t$0821$t$, $t$Westville Borough$t$, $t$GLOUCESTER$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Inspection (Residential)$t$, $j$["Issued by: Borough of Westville Housing & Code Enforcement","Contact: 856-456-0030 option 5","Apply: Schedule as far in advance as possible (the Borough says to allow about one week for scheduling).","How to apply: Fill out the Certificate of Inspection application online (Borough web form) or print the PDF and return it with the $100 fee to Borough of Westville, c/o Residential Application, 165 Broadway, Westville NJ 08093. Checks payable to 'Borough of Westville'. No credit cards in the office; cash must be exact; online payment needs a Customer ID and PIN from the Housing office. Inspections are Tuesdays and Thursdays, 9 to 12 or 1 to 3; call 856-456-0030 option 5 to schedule.","Remove trash and debris inside and outside","Fix tripping hazards on sidewalks, walkways, steps and driveway","Cut high grass and weeds; no standing water","Exterior in good repair: siding, roof, flashing, gutters, foundation; scrape and paint peeling paint","Address numbers visible from the street","Handrail on steps with 3 or more risers; guardrails where the drop is 30 inches or more","Windows open and stay open, with tight screens and no broken glass","Bedrooms need two ways out (a door and a window)","Bathrooms need a window or an exhaust fan vented outside","Plumbing, heating and electrical safe and working; appliances on grounded outlets","Water heater gives at least 120 degree water and has a discharge pipe ending 2 to 6 inches from the floor","GFCI outlets at kitchen sink, utility sinks, bathrooms, sump pumps and outside","Work done without permits must get permits and pass final inspection","Proof of extermination if there are signs of insects or rodents","Smoke alarms, CO alarms and a fire extinguisher (see fire certificate section)","Also: Unpermitted work: Work done without the needed permits must be permitted and pass final inspection."]$j$::jsonb, $j$[{"label":"Certificate of Inspection, per unit","amount":"$100"},{"label":"Re-inspection, 1st","amount":"$50"},{"label":"Re-inspection, 2nd","amount":"$60"},{"label":"Re-inspection, 3rd","amount":"$75"},{"label":"Re-inspection, 4th and later, per unit","amount":"$100"}]$j$::jsonb, $t$https://westville-nj.com/wp-content/uploads/2026/03/CERTIFICATE-OF-INSPECTION-RESIDENTIAL-APPLICATION.pdf$t$, $t$https://westville-nj.com/departments/housing-code-enforcement/$t$, $j$[{"url":"https://westville-nj.com/departments/housing-code-enforcement/","label":"Official source (westville-nj.com)"},{"url":"https://westville-nj.com/wp-content/uploads/2026/03/CERTIFICATE-OF-INSPECTION-RESIDENTIAL-APPLICATION.pdf","label":"Official source (westville-nj.com)"},{"url":"https://westville-nj.com/departments/housing-code-enforcement/certificate-of-inspection-application/","label":"Official source (westville-nj.com)"}]$j$::jsonb, $t$When a property is sold, rented or a change of tenant occurs, the owner is required to complete a Certificate of Inspection application. Property owners should schedule this inspection as far in advance as possible.$t$, $t$7dd8c710fd16726612d5748915226bf377eeb3d60fcd09f65513c21973584c34$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":5,"fee_ok":5,"fee_bad":0,"fee_unchecked":0,"quotes":5,"q_ok":4,"q_bad":0,"q_unchecked":1},"source":"property/data/municipal-requirements/checked/0821.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/0821.json$t$, true),
  ($t$2102$t$, $t$Alpha Borough$t$, $t$WARREN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Habitability (CH), applied for on the Residential Property Sale Application & Fire Safety Certification Form$t$, $j$["Issued by: Borough of Alpha Code & Zoning Enforcement","Contact: Andrew Melendez, Zoning Official and Housing Inspections (also Code Enforcement Officer) · 908-454-0088 x173 · codeenforcement@alphaboronj.org","How to apply: Download the Residential Property Sale Application & Fire Safety Certification Form from the Construction & Zoning page. Fill in the property, owner, broker, buyer and closing date details, sign the smoke/CO/extinguisher attestation, and submit it with payment by check, cash or money order payable to the Borough of Alpha to Code & Zoning Enforcement, 1001 East Blvd, Phillipsburg (Alpha), NJ 08865. An official will call to schedule the Habitability Inspection; the owner or a designee must be there. If violations are found you get a Violation Notice with a comply-by date. If the home cannot pass re-inspection in time for closing, a Conditional CH may be requested once all fire and life safety items are fixed; the buyer must then sign a notarized affidavit taking responsibility for the open violations.","No CH while any construction permit is still open; all building permits must be closed","Exterior: fences, garage and sheds in good condition; chimney mortar and bricks secure","Exterior: foundation free of cracks; gutters and downspouts attached and working; roof with no loose shingles, leaks or bowing","Exterior: paint free of chipping; sidewalks level and free of cracks; landscaping clean and trimmed","Stairs in good condition with secure railings for three or more treads","No vermin or pest infestation, inside or out","Asbestos encapsulated or professionally removed; basement floor and walls free of moisture and cracks","Bathroom window or working exhaust fan; kitchen ventilation vented outside from the stove","At least two working outlets in every habitable room; GFCI outlets in kitchen and bathrooms","Furnace and water heater in good working order; fireplace working with proof of the last flue cleaning","Plumbing free of leaks; floors, ceilings and walls in good condition","Working sash locks on all first-floor windows; all windows in good working order","Smoke detectors on every floor including basements and attics; CO detectors within 10 feet of every bedroom","Fire extinguisher in each kitchen (1 to 3 family)","Also: Open construction permits must be closed: No CH is issued while an open construction permit exists; call the Construction Department at 908-454-0088 ext. 176 to review open permits.","Also: Final water reading: Requests for final water readings must be submitted in writing to taxcollector@alphaboronj.org (Utility Collector, 908-454-0088 ext. 120)."]$j$::jsonb, $j$[{"label":"Sale of a single-family dwelling (when occupancy will change)","amount":"$75"},{"label":"Sale of a two-family dwelling","amount":"$150"}]$j$::jsonb, $t$https://www.alphaboronj.org/Property_Sale_App__Fire_Safety_Cert_Form.pdf?t=202406101420570$t$, $t$https://www.alphaboronj.org/offices/construction___zoning/index.php$t$, $j$[{"url":"https://www.alphaboronj.org/Property_Sale_App__Fire_Safety_Cert_Form.pdf?t=202406101420570","label":"Official source (alphaboronj.org)"},{"url":"https://www.alphaboronj.org/offices/construction___zoning/index.php","label":"Official source (alphaboronj.org)"},{"url":"https://www.alphaboronj.org/offices/code_enforcement_officer/index.php","label":"Official source (alphaboronj.org)"}]$j$::jsonb, $t$Before you sell any residential property in Alpha, you must obtain a Certificate of Habitability from the zoning and code enforcement department and should comply will all but not limited to construction, zoning, and property maintenance codes and ordinances. This applies to single-family homes, two-family homes, co-ops, apartments, condos, town homes, multi-family homes and dwelling units in mixed-use buildings.$t$, $t$127af817f0051fd0d267550fd37d6cbe54c1b6ba3c33850836cb96aa118f6d74$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":12,"q_ok":6,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/2102.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/2102.json$t$, true),
  ($t$2102$t$, $t$Alpha Borough$t$, $t$WARREN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Borough of Alpha Code & Zoning Enforcement (fire safety certification combined with the Certificate of Habitability) (town fire bureau)","Contact: Andrew Melendez, Zoning Official and Housing Inspections (also Code Enforcement Officer) · 908-454-0088 x173 · codeenforcement@alphaboronj.org","How to apply: Same combined form, inspection and fee as the Certificate of Habitability (see the town certificate). The owner signs an attestation that smoke/CO alarms and the extinguisher are installed, and the smoke, CO and extinguisher items are checked during the Habitability Inspection.","Fire official in the NJ state directory (NJ DCA, state), updated 5/30/2025: Louis Kilmer · (609)633-6132","Homes built before 1977: 10-year sealed battery smoke alarms (or combination smoke/CO); homes built after 1977: working AC hardwired alarms, which may not be replaced with battery alarms","Smoke alarms on each level and outside each sleeping area; basement alarm near the bottom of the basement stairs","CO alarms near the sleeping areas (within 10 feet of bedroom doors or one in each bedroom) in homes with a fuel-burning device or attached garage","Form still requires a portable fire extinguisher: at least 2A:10B:C, no more than 10 lbs, within 10 feet of the kitchen in the path of egress, on the maker's bracket, top no more than 5 feet above the floor, serviced and tagged within 12 months or with a purchase receipt, owner's manual left for the new occupant. Form dated June 2024, before the February 2025 state law change","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[]$j$::jsonb, $t$https://www.alphaboronj.org/Property_Sale_App__Fire_Safety_Cert_Form.pdf?t=202406101420570$t$, $t$https://www.alphaboronj.org/offices/construction___zoning/index.php$t$, $j$[{"url":"https://www.alphaboronj.org/Property_Sale_App__Fire_Safety_Cert_Form.pdf?t=202406101420570","label":"Official source (alphaboronj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$ALL HOMES MUST MEET THE FOLLOWING REQUIREMENTS FOR: Certification of Smoke Detector, Carbon Monoxide Alarm and Fire Extinguisher$t$, $t$1f45cf30d514ecb09480ad7d683a1b1850febf98cb4e805378496a70c264e921$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":2,"fee_ok":0,"fee_bad":0,"fee_unchecked":2,"quotes":12,"q_ok":6,"q_bad":0,"q_unchecked":6},"source":"property/data/municipal-requirements/checked/2102.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/2102.json$t$, true),
  ($t$2119$t$, $t$Phillipsburg Town$t$, $t$WARREN$t$, $t$resale_cco$t$, $t$explicit_required$t$, $t$Certificate of Habitability (CH)$t$, $j$["Issued by: Town of Phillipsburg Office of Inspections (Inspections / Building Dept)","Contact: 908-454-5500 ext 346 · constructionofficial@phillipsburgnj.org","Apply: A minimum of 2 weeks is usually required","How to apply: Email the Office of Inspections at constructionofficial@phillipsburgnj.org (buying/selling property) to request the Certificate of Habitability inspection; fees are paid before the inspection and checks are payable to the Town of Phillipsburg. Office at 120 Filmore Street, Monday to Friday 8 am to 4 pm. If violations remain at closing, the buyer can sign a notarized Affidavit of Understanding for a 180-day conditional certificate (form: https://phillipsburgnj.org/wp-content/uploads/2024/10/Affidavit-Of-Understanding-2024.docx). No CH application form is posted.","Smoke alarms: at least one working alarm on each level and within 10 feet of each sleeping area; battery alarms must be listed 10-year sealed type; wired alarms may not be replaced with battery alarms","CO alarms within 10 feet of each sleeping area (hardwired, plug-in or battery)","Fire extinguisher: 2A:10-B:C minimum, 10 pounds maximum, mounted within 10 feet of the kitchen (not near the stove), no higher than 5 feet, new or tagged","House numbers at least 4 inches, visible from all facing streets and alleys","Yard, fences, sheds, sidewalks and curbs kept free of weeds, debris and trip hazards","Exterior in good repair: no rotten wood or peeling paint, roof, siding, gutters, downspouts, chimney and foundation in good condition","Handrails on stairs with more than four risers; guardrails on porches and decks 30 inches or taller","Interior clean, walls, ceilings and floors free of breaks or flaking paint; old unused appliances, water heaters, boilers and oil tanks removed","Electrical: at least two receptacles per room, GFCI in bathrooms, kitchen counters and outside, grounded or GFCI three-prong outlets, covered boxes, no visible knob-and-tube wiring or fuse panels","Proof of professional heating system service; no plumbing leaks; approved fittings; property connected to town sewer","Other violations under the 2000 International Property Maintenance Code and town code may be cited","Also: Rental units: yearly rental registration and yearly Certificate of Habitability: Rental registration ($100 per unit per the town's guide) is filed online; the CH must be renewed every year for rentals. Not needed for a sale to an owner-occupant beyond the resale CH.","Also: Property must be connected to town sewer: Listed in the Certificate of Habitability compliance guide."]$j$::jsonb, $j$[{"label":"Certificate for sale or transfer, per unit (1 to 19 units per lot)","amount":"$100"},{"label":"Conditional certificate (buyer affidavit), plus $50 per covered unit beyond 5","amount":"$100"},{"label":"Conditional certificate affidavit, buyer who did not pay for the CH inspection","amount":"$100"}]$j$::jsonb, null, $t$https://phillipsburgnj.org/our-town/departments/inspections/$t$, $j$[{"url":"https://phillipsburgnj.org/our-town/departments/inspections/","label":"Official source (phillipsburgnj.org)"},{"url":"https://phillipsburgnj.org/wp-content/uploads/2024/07/O2024-12-Amend-Ch-219-Cert-of-Habit-Requirements-and-Fees-1st-read.pdf","label":"Official source (phillipsburgnj.org)"},{"url":"https://phillipsburgnj.org/wp-content/uploads/2024/10/Affidavit-Of-Understanding-2024.docx","label":"Official source (phillipsburgnj.org)"},{"url":"https://phillipsburgnj.org/wp-content/uploads/2022/07/CH-Info-FAQ-Handout-v3.pdf","label":"Official source (phillipsburgnj.org)"}]$j$::jsonb, $t$Certificates of Habitability ... required for the occupancy of a home. Inspections for the certificate are required to insure that properties are brought up to code. A minimum of 2 weeks is usually required.$t$, $t$8caf3a208ed999f0ab4dfb6f37cce89c7096709026256c1ad01887528399e567$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":1,"fee_bad":0,"fee_unchecked":5,"quotes":11,"q_ok":7,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/2119.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/2119.json$t$, true),
  ($t$2119$t$, $t$Phillipsburg Town$t$, $t$WARREN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Town of Phillipsburg Fire Official (Chapter 311, Fire Prevention) (town fire bureau)","Apply: More than 10 business days before the change of occupancy for the lowest fee","How to apply: No smoke certificate application form or instructions are posted yet. Contact the Office of Inspections (constructionofficial@phillipsburgnj.org, 908-454-5500) to ask how to book the CSACMAPFEC inspection; it may be done together with the Certificate of Habitability inspection.","Fire official in the NJ state directory (NJ DCA, state), updated 2/6/2026: Louis Kilmer · (609)633-6132","The town's Certificate of Habitability inspection checks smoke alarms, CO alarms and a fire extinguisher (see resale certificate requirements); the town's 2022 guide still lists a fire extinguisher (2A:10-B:C, max 10 pounds, within 10 feet of the kitchen, no higher than 5 feet)","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received more than 10 business days before change of occupancy","amount":"$45.00"},{"label":"Request received 4 to 10 business days before change of occupancy","amount":"$90.00"},{"label":"Request received fewer than 4 business days before change of occupancy","amount":"$161.00"}]$j$::jsonb, null, $t$https://phillipsburgnj.org/our-town/departments/inspections/$t$, $j$[{"url":"https://phillipsburgnj.org/wp-content/uploads/2026/08/O2026-24-Amend-Ch-311-Fire-Official-2nd-read.pdf","label":"Official source (phillipsburgnj.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/state_towns%207_17_26.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$The application fee for a certificate of smoke alarm, carbon monoxide alarm and portable fire extinguisher compliance (CSACMAPFEC), as required by N.J.A.C. 5:70-2.3, shall be in accordance with the following fees schedule:$t$, $t$178dddfc73b7187dfe223acc186ff3e9b22da2924936d0e9a42a910932eb9972$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":6,"fee_ok":1,"fee_bad":0,"fee_unchecked":5,"quotes":11,"q_ok":7,"q_bad":0,"q_unchecked":4},"source":"property/data/municipal-requirements/checked/2119.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/2119.json$t$, true),
  ($t$2121$t$, $t$Washington Borough$t$, $t$WARREN$t$, $t$resale_cco$t$, $t$official_process_found$t$, $t$Resale / Continued Certificate of Occupancy (CCO)$t$, $j$["Not required for sales, per Washington Borough. Confirm with the office if the buyer's lender or title company asks.","Contact: Todd Pantuso, Police Officer / Code Enforcement Officer · 908-689-1630 · pantuso@wtpd.net","How to apply: No town resale certificate is needed. The seller only needs the fire official's smoke alarm / CO alarm certificate (see fire certificate).","Also: Rental units: borough rental inspection and landlord registration (not needed for a sale to an owner-occupant): All residential rental properties must be inspected before a new tenant moves in (Safety and Property Maintenance Inspection and smoke/CO alarm test, call 908-689-3600 ext. 120). Landlords register yearly with the Office of Housing."]$j$::jsonb, $j$[]$j$::jsonb, null, $t$https://www.washingtonboro-nj.gov/160/Code-Enforcement$t$, $j$[{"url":"https://www.washingtonboro-nj.gov/Faq.aspx?QID=75","label":"Official source (washingtonboro-nj.gov)"},{"url":"https://www.washingtonboro-nj.gov/160/Code-Enforcement","label":"Official source (washingtonboro-nj.gov)"}]$j$::jsonb, $t$The Borough does not require a Certificate of Occupancy upon the resale of properties (required for new construction only.) We do require an inspection by the Fire Official for residential properties prior to transfer of ownership$t$, $t$0bfaab7b5fadd62a5eed4c6b2492463f8b8ad60719d1e95431d62b40c803eb05$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2121.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/2121.json$t$, true),
  ($t$2121$t$, $t$Washington Borough$t$, $t$WARREN$t$, $t$smoke_fire_cert$t$, $t$explicit_required$t$, $t$Smoke / CO alarm certificate$t$, $j$["Issued by: Washington Township (Morris County) Bureau of Fire Prevention, under a shared services agreement with Washington Borough (town fire bureau)","Contact: Matthew Lopez, Fire Marshal · 908-876-8637 · fireinspection@wtmorris.net","Apply: Call to schedule 2 to 3 weeks before closing; more than 10 business days ahead for the lowest fee","How to apply: Call the Washington Township (Morris County) Fire Prevention Office at 908-876-8637 to schedule (by appointment only; no form needed to schedule). Checks are payable to Washington Township. Office hours Monday to Friday 8:30 am to noon and 1 pm to 4:30 pm. Certificates are valid for six months.","Fire official in the NJ state directory (town), updated 9/8/2025: Matthew J Lopez · (908) 876-4711 · mlopez@wtmorris.net","Smoke alarms more than 10 years old (from the manufacture date) or giving an end-of-life signal must be replaced","Battery-only smoke alarms must be 10-year sealed battery units; replaceable-battery single-station alarms are not accepted (since January 1, 2019)","Hardwired (A/C powered) alarms cannot be replaced with battery alarms","Smoke alarm type depends on the year built: before 1977 a 10-year sealed alarm on each level and within 10 feet of bedrooms; 1977 onward hardwired alarms on sleeping levels (and basement from October 1978; interconnected from August 1984); March 1991 onward hardwired interconnected alarms with battery backup on every level and in each bedroom","CO alarms within 10 feet of bedrooms; homes built 1993 and later need hardwired CO alarms with battery backup","All smoke and CO alarms must be listed (for example UL) and installed before booking the inspection","Battery smoke alarms may not be within 5 feet of a kitchen or bathroom","Fire extinguisher (still on the June 2024 form): listed 2A-10B:C, no more than 10 pounds, within 10 feet of the kitchen in the path of exit, mounted on its bracket with the top no more than 5 feet above the floor, serviced and tagged within 12 months or a recent purchase receipt, and the manual left for the buyer","State rule: a 2025 law (P.L.2025, c.19) dropped the fire extinguisher from the state requirement. Follow the town's current form, which may still list one."]$j$::jsonb, $j$[{"label":"Request received more than 10 business days before change in occupant","amount":"$40"},{"label":"Request received 4 to 10 business days before change in occupant","amount":"$70"},{"label":"Request received fewer than 4 days before change in occupant","amount":"$125"}]$j$::jsonb, $t$https://www.washingtonboro-nj.gov/DocumentCenter/View/447/Certificate-of-Smoke-Alarm-Carbon-Monoxide-Alarm-and-Portable-Fire-Extinguisher-Compliance-for-Resale-or-Rental-PDF$t$, $t$https://www.washingtonboro-nj.gov/162/Fire-Prevention$t$, $j$[{"url":"https://www.washingtonboro-nj.gov/Faq.aspx?QID=75","label":"Official source (washingtonboro-nj.gov)"},{"url":"https://www.washingtonboro-nj.gov/162/Fire-Prevention","label":"Official source (washingtonboro-nj.gov)"},{"url":"https://www.washingtonboro-nj.gov/DocumentCenter/View/447/Certificate-of-Smoke-Alarm-Carbon-Monoxide-Alarm-and-Portable-Fire-Extinguisher-Compliance-for-Resale-or-Rental-PDF","label":"Official source (washingtonboro-nj.gov)"},{"url":"https://www.wtmorris.org/media/attachments/2024/08/14/2024-requirements-for-csacmapfec-updated-061224.pdf","label":"Official source (wtmorris.org)"},{"url":"https://web.archive.org/web/20260501121051/https://www.wtmorris.org/index.php/departments/fire-prevention","label":"Official source (web.archive.org)"},{"url":"https://nj.gov/dca/dfs/pdf/ANNUAL%20REGISTRY/THIRD%20QUARTER%20LEA%20REGISTRY%202026.pdf","label":"Official source (nj.gov)"},{"url":"https://www.nj.gov/dca/dfs/pdf/fire%20directory_county%20summary/fire_code_enforcement_director.pdf","label":"Official source (nj.gov)"}]$j$::jsonb, $t$We do require an inspection by the Fire Official for residential properties prior to transfer of ownership, as well as inspections of commercial properties for compliance with local and State laws. Inspections are by Appointment only. Call 908-876-8637$t$, $t$c0db2cfc373e07ad28799c1617575ef5d5877997c72851c800402eccee22dd0c$t$, $t$2026-09-30T12:00:00Z$t$, $j${"checked":{"researched_on":"2026-09-30","approved_on":"2026-09-30","needs_lookup":false,"flag_reasons":[],"verification":{"fees":3,"fee_ok":3,"fee_bad":0,"fee_unchecked":0,"quotes":12,"q_ok":12,"q_bad":0,"q_unchecked":0},"source":"property/data/municipal-requirements/checked/2121.json"}}$j$::jsonb, $t$Checked from official sources on 2026-09-30 and approved in the NJ Resale Certificate Tracker on 2026-09-30. Source: property/data/municipal-requirements/checked/2121.json$t$, true)
